// rocks sit on the ground: a crater under them means their cell is built again from the new ground
function rocksRefresh(x0,z0,x1,z1){
 for(const [k,C] of rockCells){
  if(C.x0>x1+60||C.x0+ROCK_CELL<x0-60||C.z0>z1+60||C.z0+ROCK_CELL<z0-60)continue;
  C.bufs.forEach(b=>gl.deleteBuffer(b));C.vao.forEach(a=>a&&gl.deleteVertexArray(a));rockCells.delete(k);
 }
}
// build what is missing around the camera (nearest first) and drop what is far away
function updateVegetation(camX,camY,camZ,budget){
 if(camY-Math.max(0,T.height(camX,camZ))>3500)return;
 const gR=Q.giant*1.25,rR=Q.rock*1.25,todo=[];
 const scan=(map,size,R,mk)=>{
  const c0=Math.floor((camX-R)/size),c1=Math.floor((camX+R)/size),d0=Math.floor((camZ-R)/size),d1=Math.floor((camZ+R)/size);
  for(let dz=d0;dz<=d1;dz++)for(let dx=c0;dx<=c1;dx++){
   const d=Math.hypot((dx+.5)*size-camX,(dz+.5)*size-camZ);
   if(d<R+size*.71&&!map.has(dx+','+dz))todo.push([d,map,dx,dz,mk]);
  }
  for(const [k,v] of map)if(Math.hypot(v.x0+size/2-camX,v.z0+size/2-camZ)>R+size*2.5){
   v.bufs.forEach(b=>gl.deleteBuffer(b));v.vao.forEach(a=>a&&gl.deleteVertexArray(a));map.delete(k);
  }
 };
 scan(giantRegions,GREGION,gR,buildGiantRegion);scan(rockCells,ROCK_CELL,rR,buildRockCell);
 todo.sort((a,b)=>a[0]-b[0]);
 for(let i=0;i<todo.length&&i<budget;i++){const [,map,x,z,mk]=todo[i];map.set(x+','+z,mk(x,z));}
}

// a giant that leans or lies down stops being drawn from its region's buffer (its instance is zeroed there) and is drawn here with its tilt
function treeToDynamic(g){
 if(dmgTrees.has(g))return;dmgTrees.add(g);
 if(g._buf){gl.bindBuffer(gl.ARRAY_BUFFER,g._buf);gl.bufferSubData(gl.ARRAY_BUFFER,g._idx*INSTANCE_FLOATS*4,new Float32Array(INSTANCE_FLOATS));}
}
let dynTree=null;
function drawDamagedTrees(planes,vp,stats){
 if(!dmgTrees.size)return;
 if(!dynTree){const b=gl.createBuffer();dynTree={b,vao:[instanceVAO(treeMesh[TREE_MESH.TREE],b),instanceVAO(treeMesh[TREE_MESH.TREE_LOW],b)],data:new Float32Array(INSTANCE_FLOATS)};}
 setU(progTree,'uFadeR',Q.giant);setU(progTree,'uLodR',GIANT_LOD);setU(progTree,'uType',1);setU(progTree,'uCellRel',[-cam.x,-cam.z]);
 for(const g of dmgTrees){
  const d=Math.hypot(g.x-cam.x,g.z-cam.z);if(d>Q.giant+g.height)continue;
  const cx=g.x-cam.x,cz=g.z-cam.z,cy=g.y+g.height*.5-cam.y;
  if(!visible(planes,cx,cy,cz,g.height*.85+g.crown*.3))continue;
  const a=dynTree.data;a[0]=g.x;a[1]=g.y;a[2]=g.z;a[3]=g.height;a[4]=g.rot;a[5]=g.tint;a[6]=g.crown;a[7]=g.trunk;
  gl.bindBuffer(gl.ARRAY_BUFFER,dynTree.b);gl.bufferData(gl.ARRAY_BUFFER,a,gl.STREAM_DRAW);
  setU(progTree,'uTilt',g.tilt||0);setU(progTree,'uTiltDir',[Math.cos(g.fd||0),Math.sin(g.fd||0)]);
  for(let lod=0;lod<2;lod++){setU(progTree,'uLod',lod);gl.bindVertexArray(dynTree.vao[lod]);gl.drawArraysInstanced(gl.TRIANGLES,0,treeMesh[lod].nV,1);}
  stats.trees++;stats.tris+=(treeMesh[0].nV+treeMesh[1].nV)/3;
 }
 setU(progTree,'uTilt',0);
}
function drawVegetation(planes,vp,common,stats){
 gl.useProgram(progTree.p);common(progTree);setU(progTree,'uVP',vp);setU(progTree,'uWind',wind);setU(progTree,'uTilt',0);
 // giants: the detailed mesh up close, a cheap one beyond GIANT_LOD (the vertex shader hides each instance from the wrong one)
 setU(progTree,'uFadeR',Q.giant);setU(progTree,'uLodR',GIANT_LOD);setU(progTree,'uType',1);
 for(const R of giantRegions.values()){
  if(!R.count)continue;
  const cx=R.x0+GREGION/2-cam.x,cz=R.z0+GREGION/2-cam.z,cy=(R.ymin+R.ymax)/2-cam.y;
  if(Math.hypot(cx,cz)-GREGION*.71>Q.giant+400)continue;
  if(!visible(planes,cx,cy,cz,GREGION*.71+(R.ymax-R.ymin)*.5))continue;
  setU(progTree,'uCellRel',[R.x0-cam.x,R.z0-cam.z]);
  for(let lod=0;lod<2;lod++){
   setU(progTree,'uLod',lod);
   gl.bindVertexArray(R.vao[lod]);gl.drawArraysInstanced(gl.TRIANGLES,0,treeMesh[lod].nV,R.count);
  }
  stats.trees+=R.count;stats.tris+=R.count*(treeMesh[0].nV+treeMesh[1].nV)/6;
 }
 drawDamagedTrees(planes,vp,stats);
 // rocks
 setU(progTree,'uFadeR',Q.rock);setU(progTree,'uLodR',1e9);setU(progTree,'uLod',0);setU(progTree,'uType',2);
 for(const C of rockCells.values()){
  if(!C.count)continue;
  const cx=C.x0+ROCK_CELL/2-cam.x,cz=C.z0+ROCK_CELL/2-cam.z,cy=(C.ymin+C.ymax)/2-cam.y;
  if(Math.hypot(cx,cz)-ROCK_CELL*.71>Q.rock)continue;
  if(!visible(planes,cx,cy,cz,ROCK_CELL*.71+(C.ymax-C.ymin)*.5+10))continue;
  setU(progTree,'uCellRel',[C.x0-cam.x,C.z0-cam.z]);
  gl.bindVertexArray(C.vao[0]);gl.drawArraysInstanced(gl.TRIANGLES,0,treeMesh[TREE_MESH.ROCK].nV,C.count);
  stats.tris+=C.count*treeMesh[TREE_MESH.ROCK].nV/3;
 }
 gl.bindVertexArray(null);
}

// the nearest giant crowns, as shadow ellipses for the terrain shader (centre shifted away from the sun)
const shadowData=new Float32Array(24*4);
function collectShadows(lightDir){
 const near=[],ly=Math.max(lightDir[1],.12),lx=lightDir[0]/ly,lz=lightDir[2]/ly,reach=2600;
 for(const R of giantRegions.values()){
  if(Math.hypot(R.x0+GREGION/2-cam.x,R.z0+GREGION/2-cam.z)>reach+GREGION*.71+300)continue;
  for(const g of R.giants){
   if(dmgTrees.has(g))continue;
   const sx=g.x-lx*g.height*.78-cam.x,sz=g.z-lz*g.height*.78-cam.z,d=Math.hypot(sx,sz)-g.crown*.5;
   if(d<reach)near.push([d,sx,sz,g.crown*.5]);
  }
 }
 near.sort((a,b)=>a[0]-b[0]);
 const n=Math.min(24,near.length);
 for(let i=0;i<n;i++){shadowData[i*4]=near[i][1];shadowData[i*4+1]=near[i][2];shadowData[i*4+2]=near[i][3];}
 return n;
}

// ---------- harbours: quays, cranes, containers, warehouses, a small town ----------
function boxMeshes(){
 const V=[];
 function quad(a,b,c,d){V.push(...a,...b,...c,...a,...c,...d);}
 const c=(x,y,z)=>[x,y,z];
 function box(y0,y1,out){
  const p=[[-.5,y0,-.5],[.5,y0,-.5],[.5,y0,.5],[-.5,y0,.5],[-.5,y1,-.5],[.5,y1,-.5],[.5,y1,.5],[-.5,y1,.5]];
  quad(p[0],p[1],p[5],p[4]);quad(p[1],p[2],p[6],p[5]);quad(p[2],p[3],p[7],p[6]);quad(p[3],p[0],p[4],p[7]);
  if(out)quad(p[4],p[5],p[6],p[7]);
 }
 const B=[];V.length=0;box(0,1,true);B.push(...V);
 V.length=0;box(0,1,false);
 const R=1.3;                      // roof ridge
 quad([-.5,1,-.5],[.5,1,-.5],[.5,R,0],[-.5,R,0]);quad([.5,1,.5],[-.5,1,.5],[-.5,R,0],[.5,R,0]);
 V.push(-.5,1,.5,-.5,1,-.5,-.5,R,0, .5,1,-.5,.5,1,.5,.5,R,0);
 const G=V.slice();
const Cy=[],S=22;
 for(let i=0;i<S;i++){const a0=i/S*6.2832,a1=(i+1)/S*6.2832,x0=Math.cos(a0)*.5,z0=Math.sin(a0)*.5,x1=Math.cos(a1)*.5,z1=Math.sin(a1)*.5;
  Cy.push(x0,0,z0,x1,0,z1,x1,1,z1, x0,0,z0,x1,1,z1,x0,1,z0, x0,1,z0,x1,1,z1,0,1,0);}
 const Dm=[],RS=6,SG=18;
 for(let r=0;r<RS;r++){const p0=r/RS*1.5708,p1=(r+1)/RS*1.5708;
  for(let i=0;i<SG;i++){const a0=i/SG*6.2832,a1=(i+1)/SG*6.2832;
   const P=(p,a)=>[Math.cos(p)*Math.cos(a)*.5,Math.sin(p),Math.cos(p)*Math.sin(a)*.5];
   const A=P(p0,a0),B2=P(p0,a1),C=P(p1,a1),D=P(p1,a0);
   Dm.push(...A,...B2,...C,...A,...C,...D);}}
 const mk=a=>{const b=gl.createBuffer();gl.bindBuffer(gl.ARRAY_BUFFER,b);gl.bufferData(gl.ARRAY_BUFFER,new Float32Array(a),gl.STATIC_DRAW);return {buf:b,nV:a.length/3};};
// arch: a half-ellipse profile (x: -.5..+.5, y: 0..1) extruded along z, with flat end walls
 const Ar=[],AS=24;
 for(let i=0;i<AS;i++){
  const t0=i/AS*3.14159,t1=(i+1)/AS*3.14159,x0=Math.cos(t0)*.5,y0=Math.sin(t0),x1=Math.cos(t1)*.5,y1=Math.sin(t1);
  Ar.push(x0,y0,-.5,x1,y1,-.5,x1,y1,.5, x0,y0,-.5,x1,y1,.5,x0,y0,.5);
  Ar.push(x0,y0,.5,x1,y1,.5,0,0,.5, x1,y1,-.5,x0,y0,-.5,0,0,-.5);
 }
 return [mk(B),mk(G),mk(Cy),mk(Dm),mk(Ar)];
}
