 const concrete=[.42,.41,.40],steel=[.50,.54,.54],navy=[.44,.48,.50],olive=[.30,.34,.24],dark=[.22,.24,.24],yellow=[.9,.72,.08],white=[.9,.9,.88],redc=[.8,.1,.07];
