// settings controls: each segmented row picks one value; every pick is remembered (quality and water keep their old keys so older saves still apply)
function paintSeg(id,test){for(const b of $(id).children)b.classList.toggle('on',test(b));}
function bindSeg(id,pick,isOn){for(const b of $(id).children)b.onclick=()=>{pick(b.dataset.v,b);optsSave();paintSeg(id,x=>isOn(x.dataset.v,x));};paintSeg(id,x=>isOn(x.dataset.v,x));}
(function(){
 const q=$('s-q');
 QUALITY.forEach((Qo,i)=>{const b=document.createElement('button');b.textContent=Qo.name.toUpperCase();b.dataset.v=String(i);q.appendChild(b);});
 {const sw=+store.get('irontide.w');if(sw===1||sw===2)waterMode=sw;}
 const saved=store.get('irontide.q');if(saved!==null&&!params.has('q')&&QUALITY[+saved]){qi=+saved;qiChosen=qi;applyQuality();}
 // choices remembered from last time
 if(opts.cycle===false){game.cycle=false;todSpeed=0;}
 if(typeof opts.sea==='number')seaBase=opts.sea;
 if(opts.wx&&opts.wx!=='auto'&&!params.has('wx')){wx.auto=false;setWeather(opts.wx,false);}
 bindSeg('s-q',v=>{qi=+v;qiChosen=qi;dyn=1;applyQuality();store.set('irontide.q',v);},v=>+v===qi);
 bindSeg('s-t',v=>{game.cycle=v==='1';todSpeed=game.cycle?1/(60*22):0;opts.cycle=game.cycle;},v=>v===(game.cycle===false?'0':'1'));
 bindSeg('s-w',v=>{seaBase=+v;opts.sea=seaBase;},v=>Math.abs(+v-(seaBase??wind))<.2);
 bindSeg('s-x',v=>{if(v==='auto'){wx.auto=true;wx.timer=60;}else{wx.auto=false;setWeather(v,true);}opts.wx=v;},v=>v===(wx.auto?'auto':wx.kind));
 bindSeg('s-r',v=>{waterMode=+v;waterQ.zero=-1e9*(waterMode);store.set('irontide.w',v);},v=>v===String(waterMode));
 bindSeg('s-d',v=>{game.debug=v==='1';hudEl.style.display=game.debug?'block':'none';},v=>v===(game.debug?'1':'0'));
 bindSeg('s-l',v=>{opts.life=v==='1';},v=>v===(opts.life?'1':'0'));
 bindSeg('s-f',v=>{opts.fov=+v;},v=>Math.abs(+v-opts.fov)<.01);
 bindSeg('s-m',v=>{opts.sens=+v;},v=>Math.abs(+v-opts.sens)<.01);
 bindSeg('s-i',v=>{opts.invert=v==='1';},v=>v===(opts.invert?'1':'0'));
 bindSeg('s-c',v=>{opts.follow=v==='1';},v=>v===(opts.follow?'1':'0'));
 bindSeg('s-res',v=>{opts.res=v;dyn=1;W=0;},v=>v===opts.res);
 bindSeg('s-sh',v=>{opts.sharp=+v;},v=>Math.abs(+v-opts.sharp)<.01);
 bindSeg('s-lk',v=>{opts.look=v;},v=>v===opts.look);
 bindSeg('s-hz',v=>{opts.haze=v;},v=>v===opts.haze);
 bindSeg('s-tm',v=>{opts.terr=v==='1';mapLast.mode=-1;},v=>v===(opts.terr?'1':'0'));
 bindSeg('s-by',v=>{opts.buoys=v==='1';},v=>v===(opts.buoys?'1':'0'));
 bindSeg('s-bn',v=>{opts.banners=v==='1';},v=>v===(opts.banners?'1':'0'));
 bindSeg('s-lad',v=>{ladLoad().sandbox=v==='1';ladSave();ladHudDirty=true;garage.specs={ship:null,tank:null,plane:null};toast(v==='1'?'Sandbox: every vehicle and weapon is open, at full difficulty.':'The ladder: Step '+(ladStep()+1)+', '+LADDER[ladStep()].name+'.',4500);},v=>v===(ladLoad().sandbox?'1':'0'));
 bindSeg('s-sk',v=>{opts.shake=+v;if(+v>0){shakeS.trauma=0;camShake(.5);}},v=>Math.abs(+v-opts.shake)<.01);          // a sample kick so the choice can be felt
 bindSeg('s-mk',v=>{opts.marks=v;},v=>v===opts.marks);
 bindSeg('s-ar',v=>{opts.arrows=v==='1';},v=>v===(opts.arrows?'1':'0'));
 bindSeg('s-dt',v=>{opts.detail=+v;},v=>Math.abs(+v-opts.detail)<.01);
 bindSeg('s-tf',v=>{opts.traffic=v==='1';},v=>v===(opts.traffic?'1':'0'));
 bindSeg('s-hs',v=>{opts.hud=+v;applyHud();},v=>Math.abs(+v-opts.hud)<.01);
 bindSeg('s-un',v=>{opts.units=v;},v=>v===opts.units);
 bindSeg('s-du',v=>{opts.dist=v;},v=>v===(opts.dist||'metric'));
 applyHud();
 $('s-warreset').onclick=()=>{if(confirm('Hand every captured territory back to its original owner?')){resetWar();toast('The war map is back to how it began.');}};
})();
addEventListener('keydown',e=>{
 if(e.code==='Escape'){
  if(game.state==='playing'){setState('paused');clearInput();}          // v4.6 the menu opens, the world carries on
  else if(game.state==='paused'){setState('playing');}
  else if($('settings').classList.contains('on'))showScreen(settingsFrom==='pause'?'pause':'menu');
 }
 if(e.code==='KeyF'&&game.state==='playing'){if(outpostResupply())return;const c=dockCandidate();if(c&&hostilePort(c))toast('The '+portFaction(c).name+' will not let you in. Their guns are tracking you - get out of range.',4500);else if(c&&dockSlow())startDock(c);else if(c)toast(VS.type==='plane'?'Too fast to land. Throttle back below '+Math.round(VS.stall*1.4*3.6)+' km/h.':'Too fast to dock. Slow down first.');}
 if(e.code==='KeyR'&&game.state==='playing'){if(engineDead())callTug();else if(camMode==='ship')reloadAll();}
});
// leaving pointer lock (the browser eats Escape for that) pauses the game
document.addEventListener('pointerlockchange',()=>{if(!document.pointerLockElement&&game.state==='playing'&&!params.has('manual')&&camMode==='ship'&&player)setState('paused');});
// ---------- v2.1 pilot profiles, the objective, and training ----------
// PROFILE: every player enlists with a call sign. The profile lives in this browser (irontide.profile) and, when the page runs with the
//   artifact database and the viewer is signed in to Claude, it is tied to their account: a public pilot card at pilots/<uid> (call sign,
//   rank, step, captures - read by everyone for the roster) and a private cloud save at data/users/<uid>/save (career, ladder, war map).
//   A new browser on the same account restores from the cloud save; otherwise the local save wins and is pushed up every ~45 s.
// OBJECTIVE: the Azure Compact must secure its theatre - the territories around home - by holding OBJ_SHARE of them with its ally.
//   Securing a theatre pays out and widens the war to the next, bigger theatre (war.th).
// TRAINING: a guided first sortie for a new pilot (TUT steps, each with a check); K skips it, Enter moves past the reading steps.
const PROFILE_KEY='irontide.profile';
let profile=null;try{const p=JSON.parse(store.get(PROFILE_KEY));if(p&&p.callsign)profile=p;}catch(e){}
function profileSave(){if(profile)store.set(PROFILE_KEY,JSON.stringify(profile));}
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const cloud={db:null,user:null,uid:null,ok:false,ro:false,status:'Checking your account…',roster:[],last:{card:'',save:''},pushT:30,busy:false,rosterOff:null};
