async function acctSubmit(kind,f){
 f=f||{u:'ac-user',p:'ac-pass',s:'ac-status'};
 const u=$(f.u).value.trim(),pw=$(f.p).value,st=$(f.s);
 if(!/^[A-Za-z0-9_-]{3,16}$/.test(u)){st.textContent='Usernames are 3-16 letters, numbers, _ or -.';return;}
 if(pw.length<6){st.textContent='Passwords need at least 6 characters.';return;}
 st.textContent=kind==='login'?'Logging in…':'Creating your account…';
 try{
  const d=await api(kind==='login'?'/login':'/register',{method:'POST',body:{username:u,password:pw}});
  ACCT.token=d.token;ACCT.user=d.username;store.set('irontide.token',d.token);store.set('irontide.user',d.username);$(f.p).value='';
  const m=await api('/me');
  if(kind==='login'&&m.save){cloudRestore(m.save);st.textContent='Loaded your pilot from the account.';toast('Welcome back'+(profile?', '+profile.callsign:'')+'.',4000);if(profile&&$('signup').classList.contains('on')){showScreen('menu');}}
  else if(kind==='login'&&!profile){st.textContent='Logged in. This account has no pilot yet - enlist one and it will save here.';}
  else if(profile){st.textContent='Account created - your current pilot is now saved to it.';}
  else st.textContent='Account ready. Enlist a pilot and it will save to this account.';
  acctSignedIn(d.username);
  if(profile)await serverPush(true);
 }catch(e){st.textContent=e.message||'Could not reach the game server.';}
}
