function cloudRestore(s){
 try{
  if(s.career){store.set(CAREER_KEY,s.career);const c=JSON.parse(s.career);if(c&&typeof c.xp==='number'){const b=careerBlank();career={...b,...c,rep:[0,1,2,3].map(i=>+(c.rep&&c.rep[i])||0),stats:{...b.stats,...(c.stats||{})},mastery:c.mastery||{},disc:c.disc||{}};}}
  if(s.ladder){store.set(LADDER_KEY,s.ladder);ladder=null;ladHudDirty=true;}
  if(s.war){store.set(WAR_KEY,s.war);const w=JSON.parse(s.war);if(w){war.own=w.own&&typeof w.own==='object'?w.own:{};war.caps=w.caps|0;war.lost=w.lost|0;war.log=Array.isArray(w.log)?w.log:[];war.th=typeof w.th==='number'?w.th:1;facCache.clear();for(const k of Object.keys(war.own))rebuildTerritory(k);}}
  if(s.profile){const p=JSON.parse(s.profile);if(p&&p.callsign){profile=p;profileSave();}}
  if(s.salvage){store.set('irontide.salvage',s.salvage);SALV=null;}
  objCache=null;
 }catch(e){}
}
(async function cloudInit(){
 const use=window.claude&&window.claude.use;
 if(!use){cloud.status='Your profile is saved in this browser.';serverInit();if($('signup').classList.contains('on'))$('su-status').textContent=cloud.status;return;}
 try{
  const [db0,user]=await Promise.all([window.claude.use('db'),window.claude.use('user')]);
  // v3.9 this host hands documents back locked (frozen); the game edits what it receives (the front lines, territories), which threw
  // "Cannot add property ..., object is not extensible" every frame. Every document read now comes back as an ordinary editable copy.
  const thawData=v=>{if(!v||typeof v!=='object')return v;try{return structuredClone(v);}catch(e){return JSON.parse(JSON.stringify(v));}};
  const wSnap=x=>x&&{id:x.id,exists:x.exists,ref:x.ref,metadata:x.metadata,data:()=>thawData(x.data())};
  const wQuery=q=>q&&{docs:(q.docs||[]).map(wSnap),size:q.size,empty:q.empty,docChanges:()=>(q.docChanges?q.docChanges():[]).map(c=>({type:c.type,doc:wSnap(c.doc),oldIndex:c.oldIndex,newIndex:c.newIndex}))};
  const wDoc=r=>({id:r.id,path:r.path,get:async()=>wSnap(await r.get()),set:(...a)=>r.set(...a),update:(...a)=>r.update(...a),delete:(...a)=>r.delete(...a),
   acquire:(...a)=>r.acquire(...a),onSnapshot:(cb,err)=>r.onSnapshot(x=>cb(wSnap(x)),err),collection:c=>wCol(r.collection(c))});
  const wCol=r=>({id:r.id,path:r.path,orderBy:(...a)=>wCol(r.orderBy(...a)),limit:(...a)=>wCol(r.limit(...a)),where:(...a)=>wCol(r.where(...a)),
   get:async()=>wQuery(await r.get()),add:async(...a)=>wDoc(await r.add(...a)),doc:id=>wDoc(r.doc(id)),onSnapshot:(cb,err)=>r.onSnapshot(x=>cb(wQuery(x)),err)});
  const db=db0?{doc:p=>wDoc(db0.doc(p)),collection:c=>wCol(db0.collection(c))}:db0;
  try{if(user&&user.isOwner&&user.isOwner())ownerReady();}catch(e){}
  const uid=user?await user.id():null;
  if(!db||!uid){cloud.status='Not signed in to the game database - your profile is saved in this browser.';}
  else{
   cloud.db=db;cloud.user=user;cloud.uid=uid;cloud.ok=true;
   if(user.can){try{const w=await user.can('data.write');if(w===false)cloud.ro=true;}catch(e){}}
   cloud.status=cloud.ro?'Signed in, but this share is view-only: your profile is saved in this browser.':'Signed in: your pilot is saved to your account and follows you to other devices.';
   const [card,save]=await Promise.all([db.doc('pilots/'+uid).get(),db.doc('data/users/'+uid+'/save').get()]);
   if(save.exists&&!profile){cloudRestore(save.data());if(profile){toast('Welcome back, '+profile.callsign+'. Your career was restored from your account.',6000);if($('signup').classList.contains('on'))showScreen('menu');}}
   if(card.exists&&profile&&card.data().callsign&&card.data().callsign!==profile.callsign&&!save.exists){/* keep the local call sign */}
   mmoStart(db,uid);
   cloud.rosterOff=db.collection('pilots').orderBy('xp','desc').limit(10).onSnapshot(q=>{cloud.roster=q.docs.map(d=>d.data()).filter(Boolean);renderPilot();},()=>{});
   if(profile)cloudPush(false);
  }
 }catch(e){cloud.status='Your profile is saved in this browser.';}
 if($('signup').classList.contains('on'))$('su-status').textContent=cloud.status;
 renderPilot();
})();
