function assignSlots(list){const used={};return list.map(m=>{const d=modDef(m.t);if(!d||!d.slot||d.slot==='-')return '-';let sl=d.slot;
 if(used[sl]&&used[sl]!==d.wk){sl='v';if(used.v&&used.v!==d.wk)return null;}used[sl]=used[sl]||d.wk;return sl;});}
