 const xc=flat===1?-L*.06:flat===2?-L*.2:L*.04,zoff=flat?hb*(flat===1?1.02:.5):0,out=[];
 const bl=bs===3?[-4*l,8*l]:bs===4?[-6*l,6*l]:[-11*l,14*l],bz=(bs===3?9:bs===4?7:9.5)*w;
 out.push({x0:xc+bl[0],x1:xc+bl[1],z0:zoff-bz,z1:zoff+bz,name:'bridge'});
 const xf=xc-.14*L-3*l;
 if(fn===1)out.push({x0:xf-6*l,x1:xf+6*l,z0:(flat?zoff:0)-7*w,z1:(flat?zoff:0)+7*w,name:'funnel'});
 if(fn===2)out.push({x0:xf-3*l,x1:xf+9*l,z0:(flat?zoff:0)-10*w,z1:(flat?zoff:0)+10*w,name:'funnels'});
