// ---- aircraft geometry: the plan view of the wings, as in the mesh ----
const PLANE_CAP=[12,14,22,34,8,72,44,26,64,120,16,28,40,30,150,34];
const PLANE_PROP=[[-.5,.2],[-.42,.28],[-.3,.5],[-.18,.82],[-.08,.97],[0,1],[.16,1],[.26,1],[.32,.96],[.38,.84],[.44,.62]];
const AIR={};                                                                 // v4.0 the Service Tree aircraft designs (filled in with the plane meshes)
const airKit=spec=>{if(!spec||spec.type!=='plane'||!spec.node)return null;const K=AIR[spec.node];return K&&spec.p.airframe===K.af?K:null;};
const airStoreU=K=>.95*(K.sk||.9);                                            // the size of this design's missiles and bombs
// a design's fuselage at u (-.5 tail .. .5 nose): [half height, half width, centre height] as multiples of R, or null off the ends
function airProfAt(K,u){const S=K.prof;if(u<S[0][0]||u>S[S.length-1][0])return null;
 for(let i=0;i<S.length-1;i++){const a=S[i],b=S[i+1];if(u<=b[0]){const t=(u-a[0])/((b[0]-a[0])||1);return [a[1]+(b[1]-a[1])*t,a[2]+(b[2]-a[2])*t,(a[3]||0)+((b[3]||0)-(a[3]||0))*t];}}return null;}
