 if(d.K){const p=airProfAt(d.K,fx);if(p)best=p[1]*d.R*.9;}
 else{const prof=(()=>{for(let i=0;i<PLANE_PROP.length-1;i++){const a=PLANE_PROP[i],b=PLANE_PROP[i+1];if(fx<=b[0]){const t=(fx-a[0])/(b[0]-a[0]);return a[1]+(b[1]-a[1])*t;}}return .5;})();
  if(fx>=-.5&&fx<=.46)best=prof*d.R*.9;}
