 if(!(d.lobT>t)||d.lobT>t+1){d.lobT=t+.3;d.lobEl=null;
  const G=gunShot(d);G.wantHdg=headingOf(ap[0]-G.x,ap[2]-G.z);G.wantEl=low;
  if(shotBlocked(G)){const L=gunLob(G);d.lobEl=L;}}
