 for(let i=0;i<30;i++){const a=-1+2*hsh(i,7,301),v=.75+.45*hsh(i,7,302),q=P(a,Math.min(1,v));blob(q[0]+(v-1)*.4,q[1]+.12*(hsh(i,7,303)-.3),q[2]*(1+(v-1)*.6),.025+.05*hsh(i,7,304));}
