 const put=(Li,x,y,z,yaw,su,sv,sh,col,kind)=>Li.push(x-ox,y,z-oz,yaw,sv,sh,su,col[0],col[1],col[2],kind||0);
 const sand=[.55,.49,.36],sandD=[.45,.40,.29],wire=[.18,.18,.17],wood=[.33,.25,.17],woodD=[.24,.18,.12],slit=[.05,.05,.05],iron=[.22,.21,.2];
 const floor=T.height(x,z),yawU=Math.atan2(ux,uz),main=Ln.kind==='front'||Ln.kind==='sup';
 // revetted walls: every slab on the front line, every other on the support lines, every fourth in the maze
