 if(q%2===0)put(B,fsx,fy+.05,fsz,yawU,6.4,P.fw*.9,.1,shade(wood,1.1));
 {const sx=x+cx*(half+.8),sz=z+cz*(half+.8);put(B,sx,T.height(sx,sz)+.2,sz,yawU+1.5708,.95,3.2,.6,q%2?sand:sandD);}
 if(Ln.kind==='front'){if(q%2===0){F.fire[si].push([fsx,fsz,(fsx-J.L0.mx)*J.ex+(fsz-J.L0.mz)*J.ez]);if(q%12===0)F.slots[si].push([fsx,fsz]);}}
 // duckboards along the back of the floor
 if(q%2===1){const bx=x-cx*(P.fi-2),bz=z-cz*(P.fi-2);put(B,bx,floor+.08,bz,yawU,3.2,1.6,.1,shade(wood,1.2));}
 // dugout doors in the rear wall
