  const P=[o.c[0]+ax[0][0]*sx+ax[1][0]*sy+ax[2][0]*sz,o.c[1]+ax[0][1]*sx+ax[1][1]*sy+ax[2][1]*sz,o.c[2]+ax[0][2]*sx+ax[1][2]*sy+ax[2][2]*sz];
