 for(const o of vBoxes){const s0=cs.length;contactsVsOBB(B,o,o.vo,null,cs,.5);for(let j=s0;j<cs.length;j++)cs[j].veh=o;if(cs.length===s0)vehicleCorners(B,o,cs,.5);}
