 if(g.tilt){const fx=Math.cos(g.fd),fz=Math.sin(g.fd),a=ox*fx+oz*fz,c=Math.cos(g.tilt),s=Math.sin(g.tilt),a2=a*c-oy*s;oy=a*s+oy*c;ox+=(a2-a)*fx;oz+=(a2-a)*fz;}
