  if(size>=8&&g.holes<200){g.holes++;addDecal(nx*Rt*1.05,ly,nz*Rt*1.05,nx,0,nz,Math.min(40,size*.8+g.trunk*.2),DECAL_TYPE.SCORCH,g);}
