function groundNormal(x,z,o){const e=1.2,h0=T.height(x,z),gx=(T.height(x+e,z)-T.height(x-e,z))/(2*e),gz=(T.height(x,z+e)-T.height(x,z-e))/(2*e),l=Math.hypot(gx,1,gz);o[0]=-gx/l;o[1]=1/l;o[2]=-gz/l;return h0;}
