 for(const z of [-.74,.74])box(S,-.4,1.38,z,1.9,.16,.04,[.1,.14,.18]);                     // cabin windows
 box(S,-.1,-1.3,0,1.6,1.0,.18,[.15,.15,.16]);box(S,-.2,-1.55,0,1.9,.3,.42,[.15,.15,.16]); // fin keel and bulb
 box(S,-3.75,-.6,0,.4,1.0,.06,[.15,.15,.16]);                                              // rudder
 for(const sg of [-1,1])for(let k=0;k<5;k++)box(S,-3+k*1.6,1.2,sg*1.12*(1-Math.max(0,(k-2.6)/4)),.04,.5,.04,[.75,.77,.78]);   // guardrail stanchions
 box(S,-3.2,1.2,0,1.2,.35,1.6,teak);                                                        // cockpit seats
