  const dY=shipHull(B,S,{top:hg,under:[.30,.09,.07],deck:wd,bw:.3,n:20,band:[1.1,1.5,-10,9.5,[.5,.5,.5],5]});
  box(B,0,dY(0),0,7,1.9,3.8,hg);for(const sg of [-1,1])for(let x=-2.6;x<=2.6;x+=1.3)box(B,x,dY(0)+1.1,sg*1.91,.6,.4,.05,gls);
  box(B,1.5,dY(0)+1.9,0,3,1.1,3.4,hg);box(B,1.5,dY(0)+3,0,3.2,.08,3.6,wd);
  cylY(B,-1.8,dY(0)+1.9,0,.75,4.6,14,[.14,.14,.15]);cylY(B,-1.8,dY(0)+6.5,0,.8,.3,14,blk);
  cyl(B,[3.6,dY(0)+1.9,0],[3.6,dY(0)+10,0],.1,.05,6,dk);box(B,3.6,dY(0)+8.2,0,.1,.1,3.2,dk);box(B,3.6,dY(0)+9.4,.0,.05,1,1.6,[.9,.9,.85],5);
  for(const x of [6.8,-7.6]){cylY(B,x,dY(x),0,1.1,.9,14,hg);cylX(B,x+(x>0?.4:-.4)*1,dY(x)+.7,0,x>0?2.6:-2.6,.09,6,dk);}
