 for(const z of [-1.6,-.4])box(R,1.8,4.05,z,.35,.4,.25,dk);                  // periscopes
 box(R,-6.15,1.2,0,.12,1.3,2.4,dk);for(let k=-1;k<=1;k++)box(R,-4.8,4.05,k*1.3,.8,.12,.5,dk);   // rear hatch and vents
 box(R,3.8,1.2,0,1.6,1.9,4.4,steel);                                        // gun shield / mantlet face
