 for(const y of [1.9,3.0])cylY(Y,0,y,0,.62-(y-1.9)*.3,.07,12,[.6,.6,.6],5);
 cylY(Y,0,4.0,0,.22,.1,10,dk);cylY(Y,0,4.1,0,.14,.32,10,[1,.9,.55],7);cylY(Y,0,4.42,0,.2,.06,10,dk);
