// ---- camera shake: your own big guns, hits on your vehicle and explosions near the camera give the view a short, decaying kick ----
const shakeS={trauma:0,seed:Math.random()*100};
function camShake(amt){if(opts.shake>0)shakeS.trauma=Math.min(1,shakeS.trauma+amt*opts.shake);}
function camShakeAt(x,y,z,size){if(opts.shake<=0||!player)return;const d=Math.hypot(x-cam.x,y-cam.y,z-cam.z);const k=size/(40+d*.35);if(k>.04)camShake(Math.min(.6,k*.9));}
function applyShake(dt){
 if(shakeS.trauma<=0)return;
 shakeS.trauma=Math.max(0,shakeS.trauma-dt*1.6);
 if(game.state!=='playing')return;
 const s=shakeS.trauma*shakeS.trauma,t=performance.now()/1000*24+shakeS.seed,n=(a)=>Math.sin(t*1.7+a)*.6+Math.sin(t*3.1+a*2.3)*.4;
 cam.yaw+=n(1)*.022*s;cam.pitch+=n(4)*.018*s;
 const k=Math.min(6,orbit.dist*.012)*s;cam.x+=n(7)*k;cam.y+=n(9)*k*.6;cam.z+=n(11)*k;
}

// ---- exhaust: the player's funnels smoke with the engine order, a tank's exhaust puffs as it drives ----
let exhaustT=0;
function updateExhaust(dt){
 if(!player||!VS||game.state!=='playing'||dt<=0||(typeof ride!=='undefined'&&ride))return;    // v3.2: no track dust while riding in a transport
 const e=player,thr=Math.abs(helm.throttle||0),flank=keys.ShiftLeft||keys.ShiftRight;
 if(VS.type==='ship'&&exhaustPts.length){
  exhaustT-=dt*(.6+thr*2.4+(flank?1.5:0));if(exhaustT>0)return;exhaustT=.13;
  const c=Math.cos(e.hd),s=-Math.sin(e.hd),rp={y:e.fy||0};
  for(const p of exhaustPts){const x=e.x+c*p[0]-s*p[2],z=e.z+s*p[0]+c*p[2];
   shellFx.push({kind:'smoke',x:x-c*e.v*.2,y:(e.y||0)+rp.y+p[1],z:z-s*e.v*.2,age:0,life:5+thr*3,size:Math.max(3,VS.beam*.46)*(.6+thr*.6+(flank?.4:0)),tint:.45,op:.78,rise:.9});}   // v4.9 funnel smoke: dark, thick, and it trails away on the wind
 }else if(VS.type==='tank'&&Math.abs(e.v||0)>.5){
  exhaustT-=dt*(1+thr*2);if(exhaustT>0)return;exhaustT=.35;
  const c=Math.cos(e.hd),s=-Math.sin(e.hd),bk=VS.length*.48;
  shellFx.push({kind:'dust',x:e.x-c*bk,y:(e.y||0)+.3,z:e.z-s*bk,age:0,life:1.6,size:3+Math.abs(e.v)*.12});
 }
}

// ---- helicopters: transport flights between neighbouring bases of the same power, taking off and landing on the runway ----
// A hostile power's helicopter can be shot down (it falls burning); the same route flies again on its next run.
const heliRoutes=new Map(),heliLive=[],heliFalls=[];
// damage taken by each helicopter or ship run (by key), -1 once it is destroyed; the key carries the run number, so the next run flies again
const trafficDmg=new Map(),isGone=key=>trafficDmg.get(key)===-1;
// one lasting object per ship or helicopter run, moved every frame, so a missile locked on it follows it; seen = the last frame it was placed
const trafficObjs=new Map();
function trafficObj(key,init){let o=trafficObjs.get(key);if(!o){o={key,...init};trafficObjs.set(key,o);}o.seen=frameNo;return o;}
const trafficLost=o=>isGone(o.key)||frameNo-o.seen>3;
let heliKeys=[];
const HELI={wait:28,climb:20,v:55,alt:170,pu:-48,pv:78};                   // the pad: on the quay apron between the floodlights (see buildPort)
function heliPad(p){return [p.x+p.ux*HELI.pu+p.vx*HELI.pv,p.z+p.uz*HELI.pu+p.vz*HELI.pv];}
function heliRoute(a,b){
 const k=a.id<b.id?a.id+'>'+b.id:b.id+'>'+a.id;let r=heliRoutes.get(k);if(r!==undefined)return r;
 const A=a.id<b.id?a:b,B=a.id<b.id?b:a,pa=heliPad(A),pb=heliPad(B),D=Math.hypot(pb[0]-pa[0],pb[1]-pa[1]);
 let top=0;for(let i=1;i<40;i++){const f=i/40;top=Math.max(top,T.height(pa[0]+(pb[0]-pa[0])*f,pa[1]+(pb[1]-pa[1])*f));}
 const cruise=Math.max(HELI.alt,top+110),fly=HELI.climb*2+Math.max(0,D-2*HELI.v*HELI.climb*.35)/HELI.v;
 r={k,a:pa,b:pb,D,alt:cruise,fid:portFaction(A).id,fly,period:2*(HELI.wait+fly),h:strHash(k)};
 heliRoutes.set(k,r);return r;
}
// position of the helicopter on route r at time t: x, y, z, heading, pitch, rotor speed (0..1)
function heliPose(r,t){
 const P=r.period,u=((t+(r.h&1023)*.37)%P+P)%P,half=P/2,back=u>=half,w=back?u-half:u,from=back?r.b:r.a,to=back?r.a:r.b;
 const dx=(to[0]-from[0])/r.D,dz=(to[1]-from[1])/r.D,hd=headingOf(dx,dz),pad=3.3,cyc=Math.floor((t+(r.h&1023)*.37)/P)*2+(back?1:0);
 if(w<HELI.wait){const spool=clamp((w-HELI.wait+9)/9,0,1);return {x:from[0],y:pad,z:from[1],hd,pitch:0,spin:Math.max(spool,clamp(1-w/7,0,1)),cyc,air:false};}
 const f=w-HELI.wait,ramp=HELI.v*HELI.climb*.35,cr=r.fly-2*HELI.climb;
 let s,y,pitch;
 if(f<HELI.climb){const k=f/HELI.climb;s=ramp*k*k;y=pad+(r.alt-pad)*(k<.3?k*.6:.18+(k-.3)/.7*.82);pitch=-.14*Math.min(1,k*3);}
 else if(f<HELI.climb+cr){s=ramp+(f-HELI.climb)*HELI.v;y=r.alt;pitch=-.09;}
 else{const k=clamp((r.fly-f)/HELI.climb,0,1);s=r.D-ramp*k*k;y=pad+(r.alt-pad)*(k<.3?k*.6:.18+(k-.3)/.7*.82);pitch=.12*Math.min(1,k*3);}
 s=clamp(s,0,r.D);
 return {x:from[0]+dx*s,y:Math.max(y,pad),z:from[1]+dz*s,hd,pitch,spin:1,cyc,air:true};
}
function emitHeli(x,y,z,hd,pitch,roll,fid,spin,t){
 emit(UNIT.HELI,x,y,z,hd,pitch,roll,fid+1,1);
 const c=Math.cos(hd),s=-Math.sin(hd),ang=t*(spin>.05?27*spin:0)+fid;
 emit(UNIT.ROTOR,x-c*3.95*Math.sin(pitch),y+3.95,z-s*3.95*Math.sin(pitch),ang,0,0,0,1);
 const tx=x-c*9.0-s*.3,tz=z-s*9.0+c*.3;
 emit(UNIT.TROTOR,tx,y+3.8+Math.sin(pitch)*-9,tz,hd,ang*4.6,0,0,1);
}
function updateHelis(t,dt){
 heliLive.length=0;
 if(!opts.life||!opts.traffic)return;
 if(frameNo%90===0||!heliKeys.length){
  const ports=T.portsIn(cam.x-14000,cam.z-14000,cam.x+14000,cam.z+14000);heliKeys=[];
  for(const p of ports){let best=null,bd=1e9;for(const q of ports){if(q===p||portFaction(q).id!==portFaction(p).id)continue;const d=Math.hypot(q.x-p.x,q.z-p.z);if(d>2500&&d<15000&&d<bd){bd=d;best=q;}}
   if(best){const r=heliRoute(p,best);if(!heliKeys.includes(r))heliKeys.push(r);}}
 }
 for(const r of heliKeys){
  const P=heliPose(r,t),key=r.k+'|'+P.cyc;
  if(trafficDmg.has(key))continue;
  if(Math.hypot(P.x-cam.x,P.z-cam.z)>UNIT_DRAW_R[UNIT.HELI])continue;
  const roll=P.air?.05*Math.sin(t*.7+r.h):0;
  emitHeli(P.x,P.y,P.z,P.hd,P.pitch,roll,r.fid,P.spin,t);
  if(P.air){const h=trafficObj(key,{v:HELI.v,fid:r.fid});h.x=P.x;h.y=P.y+1.8;h.z=P.z;h.hd=P.hd;heliLive.push(h);}
  else if(P.spin>.5&&Math.hypot(P.x-cam.x,P.z-cam.z)<900&&Math.random()<dt*6)shellFx.push({kind:'dust',x:P.x+(Math.random()-.5)*14,y:P.y,z:P.z+(Math.random()-.5)*14,age:0,life:1.5,size:6});   // rotor wash on the pad
 }
 // shot-down helicopters fall, spinning and trailing smoke, and burst where they land
 for(let i=heliFalls.length-1;i>=0;i--){
  const f=heliFalls[i];f.t+=dt;f.vy-=9.81*dt;f.y+=f.vy*dt;f.x+=f.vx*dt;f.z+=f.vz*dt;f.hd+=dt*(2+f.t*1.5);
  const g=Math.max(T.height(f.x,f.z),0);
  if(Math.random()<dt*14)shellFx.push({kind:'smoke',x:f.x,y:f.y+2,z:f.z,age:0,life:3,size:4});
  if(f.y<=g){heliFalls.splice(i,1);shellFx.push({kind:g>0?'blast':'splash',x:f.x,y:g+1,z:f.z,age:0,life:1,size:16},{kind:'blast',x:f.x,y:g+3,z:f.z,age:.1,life:.9,size:12});camShakeAt(f.x,g,f.z,16);continue;}
  emitHeli(f.x,f.y,f.z,f.hd,.25,.3*Math.sin(f.t*3),f.fid,.6,t);
 }
}
function damageHeli(h,dmg,src){
 const hp=(trafficDmg.get(h.key)||0)+dmg;
 if(isGone(h.key))return;
 if(hp<120){trafficDmg.set(h.key,hp);return;}
 trafficDmg.set(h.key,-1);
 const c=Math.cos(h.hd),s=-Math.sin(h.hd);
 heliFalls.push({x:h.x,y:h.y-1.8,z:h.z,vx:c*h.v*.5,vz:s*h.v*.5,vy:2,hd:h.hd,fid:h.fid,t:0});
 shellFx.push({kind:'blast',x:h.x,y:h.y,z:h.z,age:0,life:.7,size:9});
 if(src===undefined){
  if(playerIsFoeOf(h.fid)){game.score+=70;ladEv('air');award(45,FACTIONS[h.fid].tag+' helicopter shot down',{rep:gladRep(h.fid,3)});}
  else{addRep(h.fid,-30,'shot down a helicopter');toast('That was a '+FACTIONS[h.fid].name+' helicopter!',3500);}
 }
}

// ---- sea lanes: escorted supply convoys between a power's harbours ----
// Each harbour joins the nearest harbours of the same power (or an ally) that can be reached through open water - straight, or round one
// headland via a waypoint. Convoys of freighters with a gunboat escort sail the lane from basin to basin, turn round inside the harbour and come
// back. A freighter sunk is a supply loss for its power (like a road convoy). Escorts fire on you if you are that power's enemy.
const seaLanes=new Map(),laneQueue=[],laneList=[],shipDead=new Map(),seaWrecks=[],seaLive=[],escortFire=new Map();
let laneScanX=1e9,laneScanZ=1e9;
const LANE={v:7.5,gap:330,deep:-9};
function laneOpen(a,b){const D=Math.hypot(b[0]-a[0],b[1]-a[1]),n=Math.ceil(D/180);for(let i=1;i<n;i++){const f=i/n;if(T.height(a[0]+(b[0]-a[0])*f,a[1]+(b[1]-a[1])*f)>LANE.deep)return false;}return true;}
function buildLane(p,q){
 const mouth=(o,u)=>[o.x+o.ux*u,o.z+o.uz*u];
 const pa=mouth(p,1250),pb=mouth(q,1250);
 let mid=null;
 if(!laneOpen(pa,pb)){
  const mx=(pa[0]+pb[0])/2,mz=(pa[1]+pb[1])/2,D=Math.hypot(pb[0]-pa[0],pb[1]-pa[1]),nx=-(pb[1]-pa[1])/D,nz=(pb[0]-pa[0])/D;
  for(const k of [.15,-.15,.3,-.3,.5,-.5]){const w=[mx+nx*D*k,mz+nz*D*k];if(T.height(w[0],w[1])<LANE.deep&&laneOpen(pa,w)&&laneOpen(w,pb)){mid=w;break;}}
  if(!mid)return null;
 }
 const pts=[mouth(p,260),pa];if(mid)pts.push(mid);pts.push(pb,mouth(q,260));
 const dist=[0];for(let i=1;i<pts.length;i++)dist.push(dist[i-1]+Math.hypot(pts[i][0]-pts[i-1][0],pts[i][1]-pts[i-1][1]));
 const L=dist[dist.length-1],id=p.id+'~'+q.id,h=strHash(id);
 return {id,pts,dist,L,fid:portFaction(p).id,h,n:Math.max(1,Math.floor(L/9000)),bb:[Math.min(...pts.map(v=>v[0])),Math.min(...pts.map(v=>v[1])),Math.max(...pts.map(v=>v[0])),Math.max(...pts.map(v=>v[1]))]};
}
function scanLanes(){
 laneScanX=cam.x;laneScanZ=cam.z;
 const ports=T.portsIn(cam.x-24000,cam.z-24000,cam.x+24000,cam.z+24000);
 for(const p of ports){
  const F=portFaction(p);
  const near=ports.filter(q=>q!==p&&(portFaction(q).id===F.id||!atWar(portFaction(q).id,F.id))).map(q=>[q,Math.hypot(q.x-p.x,q.z-p.z)]).filter(([q,d])=>d>3000&&d<26000).sort((a,b)=>a[1]-b[1]).slice(0,2);
  for(const [q] of near){const k=p.id<q.id?p.id+'~'+q.id:q.id+'~'+p.id;if(!seaLanes.has(k)&&!laneQueue.some(e=>e.k===k))laneQueue.push({k,p:p.id<q.id?p:q,q:p.id<q.id?q:p});}
 }
}
function laneAt(L,s){
 let lo=0,hi=L.dist.length-1;while(hi-lo>1){const m=(lo+hi)>>1;if(L.dist[m]<=s)lo=m;else hi=m;}
 const a=L.pts[lo],b=L.pts[hi],sl=L.dist[hi]-L.dist[lo]||1,f=clamp((s-L.dist[lo])/sl,0,1);
 return [a[0]+(b[0]-a[0])*f,a[1]+(b[1]-a[1])*f,(b[0]-a[0])/sl,(b[1]-a[1])/sl];
}
function updateSeaLanes(t,dt){
 seaLive.length=0;
 if(!opts.life||!opts.traffic)return;
 if(Math.hypot(cam.x-laneScanX,cam.z-laneScanZ)>4000)scanLanes();
 for(let i=0;i<2&&laneQueue.length;i++){const e=laneQueue.shift();const L=buildLane(e.p,e.q);seaLanes.set(e.k,L);if(L)laneList.push(L);}   // two new lanes a frame at most
 const R=UNIT_DRAW_R[UNIT.FREIGHT],live=(game.state==='playing'||game.state==='docking')&&player;
 for(const L of laneList){
  const b=L.bb;if(cam.x<b[0]-R||cam.x>b[2]+R||cam.z<b[1]-R||cam.z>b[3]+R)continue;
  const dwell=600,P=2*L.L+2*dwell;
  for(let c=0;c<L.n;c++){
   const big=L.L>15000,line=big?['E','F','F','E']:['E','F','F'];
   for(let i=0;i<line.length;i++){
    const raw=hsh(L.h,c,41)*P+LANE.v*t-i*LANE.gap,cyc=Math.floor(raw/P),u=((raw%P)+P)%P;
    if((u>=L.L&&u<L.L+dwell)||u>=2*L.L+dwell)continue;                       // turning round inside the harbour
    const fwd=u<L.L,s=fwd?u:2*L.L+dwell-u,key=L.id+'|'+c+'|'+i+'|'+cyc;
    if(isGone(key))continue;
    let [x,z,tx,tz]=laneAt(L,s);if(!fwd){tx=-tx;tz=-tz;}
    x-=tz*12;z+=tx*12;                                                        // keep to the right of the lane
    const d=Math.hypot(x-cam.x,z-cam.z);if(d>R)continue;
    const hd=headingOf(tx,tz),fr=line[i]==='F',len=fr?112:23,rp=ridePose(x,z,hd,t,len);
    if(fr)emit(UNIT.FREIGHT,x,rp.y-.1,z,hd,rp.pitch,rp.roll,L.fid+1,1);
    else emit(UNIT.BOATAI,x,rp.y+.2,z,hd,rp.pitch+.04,rp.roll,L.fid+1,1);
    const o=trafficObj(key,{v:LANE.v,L:len,B:fr?17.8:6.2,fid:L.fid,fr,y:0});o.x=x;o.z=z;o.hd=hd;
    seaLive.push(o);
    // bow wave and wake
    if(d<2500){const wk=escortFire.get(key+'w')||0;if(t-wk>(fr?.5:.35)){escortFire.set(key+'w',t);const bx=Math.cos(hd),bz=-Math.sin(hd);
     foamTrail.push({x:x-bx*len*.48,z:z-bz*len*.48,age:0,life:fr?9:6,a:.6,r0:fr?5:2.5,r1:fr?16:9});if(fr)foamTrail.push({x:x+bx*len*.47,z:z+bz*len*.47,age:0,life:2.5,a:.5,r0:3,r1:7});}}
    // freighter funnel smoke
    if(fr&&d<3000&&Math.random()<dt*4.5){const bx=Math.cos(hd),bz=-Math.sin(hd);shellFx.push({kind:'smoke',x:x-bx*50,y:rp.y+22,z:z-bz*50,age:0,life:5,size:6});}
    // an escort that is your enemy opens fire when you come within 2.4 km
    if(!fr&&live&&playerIsFoeOf(L.fid)&&game.hull>0){
     const D=Math.hypot(player.x-x,player.z-z);
     if(D<2400){const ft=escortFire.get(key)||0;if(t-ft>1.6+hsh(L.h,i,c)*.8){escortFire.set(key,t);const bx=Math.cos(hd),bz=-Math.sin(hd);
      warShoot(L.fid,x+bx*7,rp.y+3.2,z+bz*7,player,520,12,.9,9.81,.018,true);shellFx.push({kind:'puff',x:x+bx*8,y:rp.y+3.2,z:z+bz*8,age:0,life:.3,size:3});}}
    }
   }
  }
 }
 if(escortFire.size>600)escortFire.clear();
 // sinking freighters and escorts settle by the stern, list and burn, then slip under
 for(let i=seaWrecks.length-1;i>=0;i--){
  const w=seaWrecks[i];w.t+=dt;if(w.t>40){seaWrecks.splice(i,1);continue;}
  if(Math.hypot(w.x-cam.x,w.z-cam.z)>UNIT_DRAW_R[UNIT.FREIGHT])continue;
  const k=w.t/40,y=-k*k*(w.fr?22:9),pitch=-k*(w.fr?.22:.3),roll=Math.min(.5,w.t*.03)*w.sg;
  emit(w.fr?UNIT.FREIGHT:UNIT.BOATAI,w.x,y,w.z,w.hd,pitch,roll,w.fid+1,1);
  if(w.t<32&&Math.random()<dt*(w.fr?9:4))shellFx.push({kind:'smoke',x:w.x+(Math.random()-.5)*w.L*.6*Math.cos(w.hd),y:Math.max(2,y+10),z:w.z-(Math.random()-.5)*w.L*.6*Math.sin(w.hd),age:0,life:5,size:w.fr?9:5});
  if(w.t<20&&Math.random()<dt*1.2)shellFx.push({kind:'blast',x:w.x,y:Math.max(1,y+8),z:w.z,age:0,life:.6,size:w.fr?10:6});
 }
}
function sinkShip(o,src){
 if(isGone(o.key))return;trafficDmg.set(o.key,-1);
 seaWrecks.push({x:o.x,z:o.z,hd:o.hd,fid:o.fid,fr:o.fr,L:o.L,t:0,sg:Math.random()<.5?-1:1});
 for(let i=0;i<(o.fr?6:3);i++){const k=(i/5-.5)*o.L*.7;shellFx.push({kind:'blast',x:o.x+Math.cos(o.hd)*k,y:6+Math.random()*6,z:o.z-Math.sin(o.hd)*k,age:-i*.15,life:.9,size:12+Math.random()*10});}
 camShakeAt(o.x,5,o.z,30);
 if(o.fr)supplyHit[o.fid]=Math.min(12,(supplyHit[o.fid]||0)+2);
 if(src===undefined){
  if(playerIsFoeOf(o.fid)){game.score+=o.fr?160:90;ladEv('convoy');mmoTre(o.fr?80:40);award(o.fr?80:50,FACTIONS[o.fid].tag+(o.fr?' supply freighter sunk':' convoy escort sunk'),{rep:gladRep(o.fid,o.fr?4:3)});
   if(o.fr)news(`${fTag(o.fid)} supply freighter sunk - their sea lane is cut for now`,12000);}
  else{addRep(o.fid,-40,'attacked a convoy at sea');toast('That was a '+FACTIONS[o.fid].name+' supply ship!',3500);}
 }
}
function hitShip(o,dmg,src){
 if(isGone(o.key))return;const hp=(trafficDmg.get(o.key)||0)+dmg;trafficDmg.set(o.key,hp);if(trafficDmg.size>3000)trafficDmg.clear();
 if(hp>=(o.fr?650:320))sinkShip(o,src);
}
// rounds and blasts: called from hitWar / warAreaDamage, and torpedoes look for these hulls too
function hitTraffic(s,src){
 for(const o of seaLive){
  if(src!==undefined&&!atWar(src,o.fid))continue;
  const dx=s.x-o.x,dz=s.z-o.z;if(Math.abs(dx)>o.L||Math.abs(dz)>o.L)continue;
  const c=Math.cos(o.hd),sn=Math.sin(o.hd),lx=dx*c-dz*sn,lz=dx*sn+dz*c;
  if(Math.abs(lx)>o.L*.5||Math.abs(lz)>o.B*.55||s.y<-3||s.y>(o.fr?24:9))continue;
  shellFx.push({kind:'blast',x:s.x,y:s.y,z:s.z,age:0,life:.6,size:7+Math.min(s.dmg,200)*.05});hitShip(o,s.dmg,src);return true;
 }
 for(const h of heliLive){
  if(isGone(h.key)||(src!==undefined&&!atWar(src,h.fid)))continue;
  const dx=s.x-h.x,dy=s.y-h.y,dz=s.z-h.z;if(dx*dx+dy*dy+dz*dz>64)continue;
  shellFx.push({kind:'blast',x:s.x,y:s.y,z:s.z,age:0,life:.35,size:4});damageHeli(h,s.dmg,src);return true;
 }
 return false;
}
function trafficArea(x,y,z,r,dmg){
 for(const o of seaLive){const d=Math.max(0,Math.hypot(o.x-x,o.z-z)-o.L*.4);if(d<r&&y<(o.fr?24:9)+r*.5)hitShip(o,dmg*(1-.6*d/r));}
 for(const h of heliLive){if(isGone(h.key))continue;const d=Math.hypot(h.x-x,h.y-y,h.z-z);if(d<r)damageHeli(h,dmg*(1-.6*d/r));}
}
const trafficProx=(x,z)=>seaLive.some(o=>{const dx=x-o.x,dz=z-o.z,c=Math.cos(o.hd),sn=Math.sin(o.hd);return Math.abs(dx*c-dz*sn)<o.L*.5+2&&Math.abs(dx*sn+dz*c)<o.B*.5+2;});
function trafficTargets(){
 const out=[];
 for(const o of seaLive)if(playerIsFoeOf(o.fid)&&!isGone(o.key))out.push({ref:o,get x(){return o.x;},get z(){return o.z;},get ay(){return o.fr?8:3;},y:0,get dead(){return trafficLost(o);}});
 for(const h of heliLive)if(playerIsFoeOf(h.fid)&&!isGone(h.key))out.push({ref:h,get x(){return h.x;},get z(){return h.z;},get ay(){return h.y;},get y(){return h.y;},get dead(){return trafficLost(h);}});
 return out;
}
function updateTraffic(t,dt){
 updateSeaLanes(t,dt);updateHelis(t,dt);updateExhaust(dt);collectContacts();drawContacts();updateGunsight(dt);
 if(frameNo%300===0)for(const [k,o] of trafficObjs)if(frameNo-o.seen>600)trafficObjs.delete(k);
}
// ---- enemy contacts: brackets over every hostile in range, arrows at the screen edge for those off screen, red marks on the minimap ----
// Covers warships, gunboats, AI tanks and fighters, war-front tanks and fighters, coastal batteries and towers, convoy ships and helicopters.
const contacts=[],contactEls=[];
const CONTACT_R={off:0,near:2500,far:6000};
function contactEl(i){
 let d=contactEls[i];if(d)return d;
 d=document.createElement('div');d.className='ctc';
 d.innerHTML='<div class="cb"><i></i><i></i><i></i><i></i></div><div class="cl"><b></b><span></span></div><div class="ch"><i></i></div><div class="ca"></div>';
 document.getElementById('ui').appendChild(d);return contactEls[i]=d;
}
{const st=document.createElement('style');st.textContent=`
.ctc{position:absolute;left:0;top:0;pointer-events:none;display:none;color:#ff5a48;font:700 10px/1.2 system-ui,sans-serif;letter-spacing:.12em;text-shadow:0 0 3px #000,0 0 6px #000}
.ctc .cb{position:absolute;left:0;top:0}
.ctc .cb i{position:absolute;width:9px;height:9px;border:2px solid currentColor;filter:drop-shadow(0 0 2px #000)}
.ctc .cb i:nth-child(1){left:0;top:0;border-right:0;border-bottom:0}.ctc .cb i:nth-child(2){right:0;top:0;border-left:0;border-bottom:0}
.ctc .cb i:nth-child(3){left:0;bottom:0;border-right:0;border-top:0}.ctc .cb i:nth-child(4){right:0;bottom:0;border-left:0;border-top:0}
.ctc .cl{position:absolute;left:0;top:0;white-space:nowrap;text-align:center}
.ctc .cl span{display:block;color:#fff;font-weight:600;opacity:.9}
.ctc .ch{position:absolute;left:0;top:0;width:46px;height:4px;background:rgba(0,0,0,.6);border:1px solid rgba(255,255,255,.35)}
.ctc .ch i{display:block;height:100%;background:currentColor}
.ctc .ca{position:absolute;left:0;top:0;width:0;height:0;border:9px solid transparent;border-left:16px solid currentColor;transform-origin:4px 9px;filter:drop-shadow(0 0 3px #000)}
.ctc.off .cb,.ctc.off .ch{display:none}.ctc:not(.off) .ca{display:none}`;document.head.appendChild(st);}
const hpFrac=(o,max)=>{if(o.hpMax===undefined)o.hpMax=Math.max(o.hp||0,max||1);return clamp((o.hp||0)/o.hpMax,0,1);};
function collectContacts(){
 contacts.length=0;
 const on=player&&camMode==='ship'&&(game.state==='playing'||game.state==='docking');
 if(!on)return;
 const R=6000,px=player.x,pz=player.z;
 const add=(x,y,z,fid,label,hp,size,L,hd)=>{const d=Math.hypot(x-px,z-pz);if(d<R&&d>8)contacts.push({x,y,z,fid,label,hp,d,size,r:L?Math.max(3,size*.12):Math.max(2.5,size*.33),L,hd});};
 for(const f of foes)if(!f.dead&&foeHostile(f))add(f.x,f.y+9*f.scale,f.z,f.fid,f.bot?'AI '+f.bot.cs:'WARSHIP',f.hp/f.hp0,60*f.scale,f.L,f.hd);
 for(const e of units){if(!e.ai||e.dead||!aiHostile(e))continue;
  const k=e.kind===UNIT.TANKAI?['TANK',3,9]:e.kind===UNIT.PLANEAI?['FIGHTER',1,12]:e.kind===UNIT.BOATAI?['GUNBOAT',3,14]:['HOSTILE',2,8];
  add(e.x,e.y+k[1],e.z,e.fid??2,k[0],hpFrac(e,e.hp0||UNIT_HP[e.kind]),k[2]);}
 for(const a of air)if(!a.dead&&playerIsFoeOf(a.fid))add(a.x,a.y,a.z,a.fid,a.transport?'TRANSPORT':a.bot?'AI '+a.bot.cs:'FIGHTER',hpFrac(a,a.transport?260:150),a.transport?16:12);
 for(const k of armour)if(!k.dead&&playerIsFoeOf(k.fid))add(k.x,k.y+3,k.z,k.fid,k.bot?'AI '+k.bot.cs:'TANK',hpFrac(k,k.hp0||525),9);
 for(const f of forts.values())if(!f.dead&&f.port&&hostilePort(f.port))add(f.x,f.y,f.z,f.fid,f.name,f.hp/f.hp0,14);
 for(const o of seaLive)if(playerIsFoeOf(o.fid)&&!isGone(o.key))add(o.x,o.fr?8:2.5,o.z,o.fid,o.fr?'FREIGHTER':'ESCORT',1-(trafficDmg.get(o.key)||0)/(o.fr?650:320),o.fr?70:16,o.L,o.hd);
 for(const h of heliLive)if(playerIsFoeOf(h.fid)&&!isGone(h.key))add(h.x,h.y,h.z,h.fid,'HELICOPTER',1-(trafficDmg.get(h.key)||0)/120,12);
 mmoContacts(add);
 contacts.sort((a,b)=>a.d-b.d);if(contacts.length>24)contacts.length=24;
}
// DOM writes only when a value changes, positions as transforms (no layout): the markers used to restyle every element every frame
// (display is checked against the element too, so a panel hidden elsewhere - setState - is never left hidden by a stale cache)
const setSt=(el,k,v)=>{if(el['_'+k]!==v||(k==='display'&&el.style.display!==v)){el.style[k]=v;el['_'+k]=v;}};
const setTx=(el,v)=>{v=String(v);if(el.textContent!==v)el.textContent=v;};
const setHt=(el,v)=>{if(el._ht!==v){el._ht=v;el.innerHTML=v;}};
const trXY=(x,y,extra)=>`translate3d(${Math.round(x)}px,${Math.round(y)}px,0)${extra}`;
function drawContacts(){
 const lim=CONTACT_R[opts.marks]??6000;let n=0;while(n<contacts.length&&n<16&&contacts[n].d<lim)n++;
 const W=VW,H=VH;
 let rt,up,arrows=0;
 if(n){const fw=fwdVec();rt=norm(cross(fw,[0,1,0]));up=cross(rt,fw);}
 for(let i=0;i<Math.max(n,contactEls.length);i++){
  const c=contacts[i],el=i<n?contactEl(i):contactEls[i];
  if(i>=n){setSt(el,'display','none');continue;}
  if(!el._b){el._b=el.children[0];el._l=el.children[1];el._l1=el._l.firstChild;el._l2=el._l.children[1];el._h=el.children[2];el._hi=el._h.firstChild;el._a=el.children[3];}
  const s=toScreen(c.x,c.y,c.z),dist=fmtD(c.d);
  setSt(el,'color',FACTIONS[c.fid]?FACTIONS[c.fid].css:'#ff5a48');
  if(s&&s[0]>12&&s[0]<W-12&&s[1]>12&&s[1]<H-12){
   setSt(el,'display','block');if(el._off!==false){el._off=false;el.classList.remove('off');}
   // the bracket shrinks with distance but never below a size that is easy to spot
   const dd=Math.hypot(c.x-cam.x,c.y-cam.y,c.z-cam.z),px=Math.round(clamp(c.size/dd*H*.9,22,140)/2)*2;
   setSt(el._b,'width',px+'px');setSt(el._b,'height',px*.75+'px');setSt(el._b,'transform',trXY(s[0],s[1],' translate(-50%,-50%)'));
   setSt(el._l,'transform',trXY(s[0],s[1]-px*.375-4,' translate(-50%,-100%)'));setTx(el._l1,c.label);setTx(el._l2,dist);
   setSt(el._h,'transform',trXY(s[0],s[1]+px*.375+4,' translate(-50%,0)'));setSt(el._hi,'width',Math.round(clamp(c.hp,0,1)*20)*5+'%');
  }else{
   if(!opts.arrows||arrows>=6){setSt(el,'display','none');continue;}             // only the six nearest get an edge arrow: more just clutters the border
   arrows++;
   setSt(el,'display','block');if(el._off!==true){el._off=true;el.classList.add('off');}
   const vx=c.x-cam.x,vy=c.y-cam.y,vz=c.z-cam.z,a=Math.atan2(-(vx*up[0]+vy*up[1]+vz*up[2]),vx*rt[0]+vy*rt[1]+vz*rt[2]);
   const ax=W/2+Math.cos(a)*(W/2-46),ay=H/2+Math.sin(a)*(H/2-46);
   setSt(el._a,'transform',trXY(ax-4,ay-9,` rotate(${a.toFixed(2)}rad)`));
   setSt(el._l,'transform',trXY(ax-Math.cos(a)*30,ay-Math.sin(a)*22+6,' translate(-50%,-100%)'));setTx(el._l1,c.label);setTx(el._l2,dist);
  }
 }
}
// on the minimap: a red diamond with a dark outline for each contact
function mapContacts(mapX,span,n){
 for(const c of contacts){if(c.fid!==PF)continue;   // v3.6: own side only
  const px=(c.x-cam.x)/span*n+n/2,py=(c.z-cam.z)/span*n+n/2;if(px<0||py<0||px>n||py>n)continue;
  mapX.fillStyle=FACTIONS[c.fid]?FACTIONS[c.fid].css:'#ff3b2a';mapX.strokeStyle='#000';mapX.lineWidth=1;
  mapX.beginPath();mapX.moveTo(px,py-4);mapX.lineTo(px+4,py);mapX.lineTo(px,py+4);mapX.lineTo(px-4,py);mapX.closePath();mapX.fill();mapX.stroke();}
}
