// ---------- v3.6 the artillery danger zone: no-man's land is a killing ground ----------
// Between the two trench lines of every front the enemy's artillery parks (the real guns behind their line) range in on anything that
// moves: the first rounds land wide, every salvo walks closer, and standing still is death. Armour shrugs off near misses and is the
// way through: a tank takes a third of the splash, and a tank that gets across and past the enemy trench breaks the line (a big push).
// ---------- v3.6 death and the Service Tree ----------
// Every time your vehicle is destroyed you drop two tiers in that branch: the vehicles above are lost and must be bought back with
// salvage. Five deaths in a row in one branch inside a window wipes the whole branch back to tier 1. The window depends on the tier you
// died at: T6 15 min, T5 20 min, T4 30 min, T3 and below 1 hour. A kill, or 10 minutes alive, clears the run of deaths.
const DEATH_WIN=t=>t>=6?15:t===5?20:t===4?30:60;
const dw={was:1,alive:0,kills:-1,pend:null};
function deathWatch(dt){
 if(!player||!VS||game.state!=='playing')return;
 const S=salvLoad(),d=DOM_OF[VS.type];
 if(dw.kills<0)dw.kills=career.stats.kills|0;
 if((career.stats.kills|0)>dw.kills){dw.kills=career.stats.kills|0;if(S.deaths&&S.deaths[d]&&S.deaths[d].length){S.deaths[d]=[];salvSave();}}
 if(game.hull>0){dw.alive+=dt;if(dw.alive>600&&S.deaths&&S.deaths[d]&&S.deaths[d].length){S.deaths[d]=[];salvSave();}}
 if(game.hull<=0&&dw.was>0)deathPenalty();
 dw.was=game.hull;
}
function deathPenalty(){
 dw.alive=0;
 const n=VS&&VS.node&&NODE.get(VS.node);if(!n||OWNER)return;
 const S=salvLoad(),d=n.dom,t=n.t,now=Date.now();
 S.deaths=S.deaths||{};const L=(S.deaths[d]=(S.deaths[d]||[]).filter(x=>now-x<3600e3));L.push(now);
 const recent=L.filter(x=>now-x<=DEATH_WIN(t)*60e3).length;
 let pick;
 if(recent>=5){
  for(const q of TREE[d])if(q.t>1)delete S.own[q.id];
  pick=TREE[d][0];S.deaths[d]=[];
  setTimeout(()=>toast('FIVE DEATHS IN A ROW - your whole '+DOM_LABEL[d].toLowerCase()+' branch has been wiped back to tier 1.',8000),1200);
 }else{
  const keep=Math.max(1,t-2);
  for(const q of TREE[d])if(q.t>keep)delete S.own[q.id];
  // fall back down the line you came up: the owned ancestor at the tier you keep
  let cur=n;while(cur&&cur.t>keep){const par=cur.parents.map(id=>NODE.get(id));cur=par.find(q=>S.own[q.id])||par[0];}
  pick=cur&&S.own[cur.id]?cur:TREE[d].filter(q=>S.own[q.id]&&q.t<=keep).sort((a,b)=>b.t-a.t)[0]||TREE[d][0];
  const left=5-recent;
  setTimeout(()=>toast(`DESTROYED - you drop to tier ${pick.t} (${pick.name}). Lost vehicles can be bought back with salvage. ${left<=2?left+' more death'+(left>1?'s':'')+' in '+DEATH_WIN(t)+' min wipes the branch!':''}`,8000),1200);
 }
 S.pick[d]=pick.id;salvSave();dw.pend=pick.id;
}
// after the tow or recovery, you come back in the vehicle you dropped to
function deathRespawn(){
 if(!dw.pend||!NODE.has(dw.pend))return;const n=NODE.get(dw.pend);dw.pend=null;
 const spec=nodeSpec(n);garage.specs[n.type]=spec;if(VS&&VS.type===n.type)setVehicle(spec);
}
const DZ_HALF=TRENCH_OFF+80;
ui.insertAdjacentHTML('beforeend','<div id="dz" style="position:absolute;left:50%;top:132px;transform:translateX(-50%);display:none;padding:8px 18px;font:700 13px/1.3 inherit;font-family:inherit;letter-spacing:.2em;color:#fff;background:rgba(150,20,10,.78);border:1px solid #ff6b5b;text-align:center;pointer-events:none"></div>');
const dz={in:null,t:0,salvoT:0,spread:220,cross:new Map()};
function dzFront(px,pz){
 for(const F of fronts.values()){if(!F.built||!F.near||!F.near.length)continue;
  let best=null,bd=1e9;for(const q of F.near){const d=Math.hypot(q[0]-px,q[1]-pz);if(d<bd){bd=d;best=q;}}
  if(bd>900)continue;
  const off=(px-best[0])*F.n[0]+(pz-best[1])*F.n[1];                    // + toward side a (si 0), - toward side b
  return {F,off,q:best};}
 return null;
}
function dangerZone(dt,px,pz){
 const el=$('dz');
 if(game.state!=='playing'||!player||!VS||(VS.type==='plane'&&(player.y-Math.max(T.height(px,pz),0))>350)||VS.type==='ship'){el.style.display='none';dz.in=null;return;}
 const h=dzFront(px,pz);
 if(!h){el.style.display='none';dz.in=null;return;}
 const {F,off}=h,inZone=Math.abs(off)<DZ_HALF,side=off>0?0:1,tank=VS.type==='tank';
 // crossing tracking: which side of the line you started on, and whether you got through the enemy trench
 const ck=F.key,st=dz.cross.get(ck);
 if(Math.abs(off)>DZ_HALF+40){const mySide=sideFid(F,side)===PF;
  if(!st||st.side!==side){if(st&&st.fromMine&&!mySide&&tank&&!(MMO.on&&!MMO.host)){frontPush(ck,side===0?-22:22);toast('BREAKTHROUGH! Your tank broke the enemy line - the front surges forward.',4500);award(120,'Breakthrough at '+terrName(side===0?F.a:F.b));}
   else if(st&&st.fromMine&&!mySide&&tank&&MMO.on){fpPend[ck]=(fpPend[ck]||0)+(side===0?-22:22);toast('BREAKTHROUGH! Your tank broke the enemy line.',4500);award(120,'Breakthrough');}
   dz.cross.set(ck,{side,fromMine:mySide});}}
 if(!inZone){el.style.display='none';dz.in=null;return;}
 if(dz.in!==ck){dz.in=ck;dz.t=0;dz.spread=240;dz.salvoT=2.5;}
 dz.t+=dt;
 el.style.display='block';
 el.innerHTML=`ARTILLERY ZONE<br><span style="font-size:11px;letter-spacing:.12em;font-weight:600">${tank?'Armour takes a third of the splash - push through!':'Get across fast or get out - only tanks survive here'}</span>`;
 // the enemy guns: whichever side of this front is not yours (both, if neither is)
 dz.salvoT-=dt;if(dz.salvoT>0)return;
 dz.salvoT=(tank?2.6:1.8)+Math.random()*.8;
 const sp=Math.hypot(player.vx||0,player.vz||0)||(player.v||0);
 dz.spread=Math.max(tank?28:12,dz.spread*(tank?.86:.78)+(sp>6?6:0));   // each salvo walks closer; moving fast keeps them guessing
 for(const si of [0,1]){const fid=sideFid(F,si);if(fid===PF)continue;
  const guns=artyPark(F,si);if(!guns.length)continue;
  for(let k=0;k<2;k++){const g=guns[Math.floor(Math.random()*guns.length)],a=Math.random()*6.283,r=dz.spread*(.3+Math.random()*.7);
   const lead=1.2,tx=px+(player.vx||0)*lead+Math.cos(a)*r,tz=pz+(player.vz||0)*lead+Math.sin(a)*r;
   g.rec=1;shellFx.push({kind:'blast',x:g.x+Math.cos(g.aim)*6,y:g.y+7,z:g.z-Math.sin(g.aim)*6,age:0,life:.3,size:14});
   warShoot(fid,g.x,g.y+8,g.z,{x:tx,y:Math.max(T.height(tx,tz),0),z:tz},300,tank?50:150,1.4,9.81,.004,true);}}
}
var MMO={db:null,room:null,uid:null,peer:null,on:false,host:false,hostT:5,pilots:[],remotes:new Map(),terrInit:false,
 season:{n:1,winner:null,hist:[]},off:null,outposts:new Map(),treas:[null,null,null,null],radio:[],pings:[],presT:0,cardT:0,
 hitBy:null,killSent:false,offT:8,seasonT:12,treasT:20,unsub:[]};
