  const b=sc.bloc[0]>=sc.bloc[1]?0:1,hist=[...MMO.season.hist,{n:MMO.season.n,winner:b,end:Date.now(),weekly:1}].slice(-10);
  await MMO.db.doc('world/season').set({n:MMO.season.n+1,winner:b,hist,start:Date.now(),wk:weekId()}).catch(()=>{});
  const q=await MMO.db.collection('terr').get().catch(()=>null);if(q)for(const d of q.docs)await MMO.db.doc('terr/'+d.id).delete().catch(()=>{});
  news(`<b style="color:#ffd36b">THE WEEK'S WAR IS OVER</b> &middot; the ${b===0?'Compact and League':'Dominion and Syndicate'} held more ground. A new war begins.`,60000);
