function buildOutpost(){
 if(!MMO.on){toast('Outposts need the shared war (log in from ACCOUNT to play online)',3500);return;}
 if(!player||VS.type!=='tank'){toast('Drive a tank to where you want the outpost, then press O',3200);return;}
 const OC=OUTPOST_COST*(docOn('fort')?.5:1);if((career.credits||0)<OC){toast('An outpost costs '+OC+' credits',3000);return;}
 const x=player.x,z=player.z,h=T.height(x,z);
 if(h<3||T.portW(x,z)>.01||T.roadDist(x,z)<20){toast('Pick open, dry ground away from roads and bases',3000);return;}
 const F=factionAt(x,z),nearFront=[...fronts.values()].some(Fr=>Fr.pts.some(p=>Math.hypot(p[0]-x,p[1]-z)<2500));
 if(F.rel<0&&!nearFront){toast('Build in friendly territory or within 2.5 km of a front line',3200);return;}
 if([...MMO.outposts.values()].some(o=>Math.hypot(o.x-x,o.z-z)<600)){toast('Too close to another outpost',2500);return;}
 if([...MMO.outposts.values()].filter(o=>o.fid===PF).length>=12){toast('Your side already holds 12 outposts - the oldest must fall first',3200);return;}
 career.credits-=OC;careerDirty=true;mmoTre(300);
 MMO.db.collection('outposts').add({fid:PF,x,z,hp:OUTPOST_HP,by:profile?profile.callsign:'',t:Date.now()}).then(()=>{toast('Outpost built. Allies can rearm and repair here (F). Hold it.',4500);news(`${fTag(PF)} outpost built by ${esc(profile?profile.callsign:'')}`,15000);}).catch(()=>{career.credits+=OC;toast('Could not build the outpost here',2500);});
}
function outpostStruct(o){
 const L=[[],[],[],[],[]],B=L[0],G=L[1],C=L[2],ox=o.x,oz=o.z,h0=T.height(o.x,o.z);
 const put=(Li,x,y,z,yaw,su,sv,sh,col,kind)=>Li.push(x-ox,y,z-oz,yaw,sv,sh,su,col[0],col[1],col[2],kind||0);
 const sand=[.55,.49,.36],olive=[.30,.34,.24],conc=[.52,.52,.49],wood=[.36,.27,.18],fc=FACTIONS[o.fid].col;
 for(let k=0;k<16;k++){const a=k/16*6.2832,x=o.x+Math.cos(a)*26,z=o.z+Math.sin(a)*26;put(B,x,T.height(x,z)-.2,z,a+Math.PI/2,10.4,1.4,1.3,sand);}   // the berm
 put(G,o.x-8,h0,o.z+4,0,10,7,3.4,olive,1);                                          // tent
 put(B,o.x+6,h0-1,o.z-6,0,7,6,3,conc);put(B,o.x+6,h0+2,o.z-6,0,7.6,6.6,.4,shade(conc,.8));   // bunker
 put(B,o.x,h0,o.z,0,.3,.3,14,wood);put(B,o.x,h0+10,o.z+1.6,0,.2,3.2,2.2,fc,12);         // flagpole and flag
 for(let k=0;k<6;k++)put(B,o.x-14+k*1.3,h0,o.z-12,0,1.1,1.1,.9,[.32,.36,.22]);           // ammo crates
 put(C,o.x+14,h0,o.z+10,0,3,3,4,[.4,.42,.38]);                                        // fuel tank
 for(let k=0;k<3;k++)put(B,o.x+16,h0+k*5,o.z-14,0,.15,.15,5,[.25,.25,.25]);put(B,o.x+16,h0+15,o.z-14,0,.1,1.8,.1,[.25,.25,.25]);   // radio mast
 const S={L:L.map(a=>new Float32Array(a)),n:L.map(a=>a.length/11),ox,oz,vao:[null,null,null,null,null],bufs:[],obs:new Float32Array(0),nObs:0,ux:1,uz:0,vx:0,vz:1};
 makePortVAOs(S);S.cy=h0;return S;
}
function drawOutposts(planes,tris){
 for(const o of MMO.outposts.values()){const cx=o.x-cam.x,cz=o.z-cam.z,D=Math.hypot(cx,cz);if(D>3000)continue;
  if(!o.S)o.S=outpostStruct(o);if(!visible(planes,cx,o.S.cy-cam.y,cz,60))continue;drawStructSet(o.S,tris);}
}
function outpostTick(dt){
 for(const o of MMO.outposts.values()){
  const D=player?Math.hypot(o.x-player.x,o.z-player.z):1e9;
  if(D<1500&&!infantry.some(e=>!e.dead&&e.outpost===o.id)&&o.hp>0)for(let k=0;k<3;k++){const a=k*2.1;addSoldier(o.x+Math.cos(a)*22,o.z+Math.sin(a)*22,o.fid,{hold:true,outpost:o.id,mg:k===0,hp:40});}
 }
}
// your rounds landing near an enemy outpost wear it down
function outpostDamage(x,z,r,dmg){
 for(const o of MMO.outposts.values()){if(!(o.fid>=0)||!FACTIONS[o.fid]||FACTIONS[o.fid].rel>=0)continue;const d=Math.hypot(o.x-x,o.z-z);if(d>r+24)continue;
  o.hp=(o.hp||0)-dmg*(1-.5*Math.min(1,d/(r+24)));
  if(o.hp<=0){MMO.db.doc('outposts/'+o.id).delete().catch(()=>{});award(250,FACTIONS[o.fid].tag+' outpost destroyed');mmoTre(200);news(`${fTag(o.fid)} outpost destroyed by ${esc(profile?profile.callsign:'')}`,15000);}
  else{o.dirty=true;}}
}
function outpostFlush(){for(const o of MMO.outposts.values())if(o.dirty){o.dirty=false;MMO.db.doc('outposts/'+o.id).update({hp:Math.max(0,Math.round(o.hp))}).catch(()=>{});}}
function outpostResupply(){
 if(!player)return false;
 for(const o of MMO.outposts.values()){if(!sameBloc(o.fid,PF)||Math.hypot(o.x-player.x,o.z-player.z)>90)continue;
  if(Math.abs(player.v||0)>4&&VS.type!=='plane'){toast('Stop at the outpost to rearm',2000);return true;}
  rearmAll();salvBank('outpost');game.hull=Math.max(game.hull,.75);game.fuel=Math.max(game.fuel,.6);toast('Rearmed at the outpost - hull patched to 75%, fuel to 60%',3000);return true;}
 return false;
}
// ---------- the live room: other pilots, player versus player, squads, radio, pings ----------
function mmoRoom(room){
 MMO.room=room;
 room.onPeers(ch=>{
  for(const p of ch.peers){if(p.isMe&&p.sameTab){MMO.peer=p.peer;continue;}if(p.isMe)continue;
   const pr=p.presence||{};if(typeof pr.x!=='number'){MMO.remotes.delete(p.peer);continue;}
   let r=MMO.remotes.get(p.peer);if(!r){r={peer:p.peer,ix:pr.x,iy:pr.y||0,iz:pr.z,ihd:pr.hd||0};MMO.remotes.set(p.peer,r);}
   r.p=pr;r.fid=Math.max(0,Math.min(3,pr.fid|0));r.cs=String(pr.cs||'?').slice(0,16);r.t=performance.now();r.by=p.by;
  }
  for(const p of ch.left)MMO.remotes.delete(p.peer);
 },()=>{});
 room.on('hit',m=>{const d=m.data||{};if(m.isMe||d.to!==MMO.peer||!player||game.state!=='playing')return;
  const r=MMO.remotes.get(m.peer);if(!r||sameBloc(r.fid,PF))return;
  const dmg=Math.min(400,Math.max(0,+d.dmg||0))*(1-.07*upLvl('armour'));game.hull=Math.max(0,game.hull-dmg/(1300*VS.hp));hitFlash=1;camShake(.3);
  MMO.hitBy={peer:m.peer,cs:r.cs,t:performance.now()};
  if(game.hull<=0&&!MMO.killSent){MMO.killSent=true;room.emit('kill',{to:m.peer,cs:profile?profile.callsign:'?',vt:VS.type}).catch(()=>{});toast('Destroyed by '+r.cs+'. Press R for a tug.',5000);}
 },()=>{});
 room.on('kill',m=>{const d=m.data||{};if(m.isMe||d.to!==MMO.peer)return;
  award(200,'Pilot '+String(d.cs||'?').slice(0,16)+' destroyed');ladEv(d.vt==='plane'?'air':d.vt==='tank'?'armour':'ship');
  news(`You destroyed <b>${esc(String(d.cs||'?').slice(0,16))}</b>`,12000);},()=>{});
 room.on('radio',m=>{const d=m.data||{},fid=d.fid|0;if(!sameBloc(fid,PF))return;if(d.ch==='sq'&&(!MMO.sq()||d.sq!==MMO.sq()))return;
  radioAdd(String(d.cs||'?').slice(0,16),String(d.text||'').slice(0,140),fid,d.ch==='sq',m.isMe);},()=>{});
 room.on('drop',m=>{if(!m.isMe)salvRemoteDrop(m.data||{});});              // v3.0: another pilot's cargo spilled
 room.on('ping',m=>{const d=m.data||{};if(!sameBloc(d.fid|0,PF)||typeof d.x!=='number')return;
  MMO.pings.push({x:d.x,z:d.z,cs:String(d.cs||'?').slice(0,16),t:performance.now(),fid:d.fid|0,wp:!!d.wp,sq:d.sq});if(MMO.pings.length>12)MMO.pings.shift();
  if(!m.isMe)news(`<b style="color:${FACTIONS[d.fid|0].css}">${esc(String(d.cs||'?').slice(0,16))}</b>: ${d.wp?'squad waypoint set':'need help at <b>'+esc(String(d.terr||'').slice(0,40))+'</b>'}`,14000);},()=>{});
}
MMO.sq=()=>profile&&profile.sq||'';
function presenceTick(dt){
 if(!MMO.room)return;MMO.presT-=dt;if(MMO.presT>0)return;MMO.presT=.12;
 const pr={cs:profile?profile.callsign:'?',fid:PF,sq:MMO.sq()||null};
 if(player&&VS&&(game.state==='playing'||game.state==='docking')&&camMode==='ship'){
  Object.assign(pr,{vt:VS.type,L:Math.round(VS.length),x:Math.round(player.x*10)/10,y:Math.round((player.y||0)*10)/10,z:Math.round(player.z*10)/10,hd:Math.round(player.hd*1000)/1000,
   p:Math.round((player.pitch||0)*1000)/1000,r:Math.round((player.roll||0)*1000)/1000,v:Math.round((player.v||0)*10)/10,hull:Math.round(game.hull*100)});
  if(game.hull>0)MMO.killSent=false;
 }else Object.assign(pr,{vt:null,x:null,y:null,z:null});
 MMO.room.presence(pr).catch(()=>{});
}
function remotesTick(dt){
 const now=performance.now();
 for(const [k,r] of MMO.remotes){const p=r.p;if(now-r.t>15000||typeof p.x!=='number'){MMO.remotes.delete(k);continue;}
  const a=Math.min(1,dt*8);r.ix+=(p.x-r.ix)*a;r.iy+=((p.y||0)-r.iy)*a;r.iz+=(p.z-r.iz)*a;r.ihd+=wrapPi((p.hd||0)-r.ihd)*a;}
}
function emitRemotes(){
 for(const r of MMO.remotes.values()){const p=r.p;if(!p.vt||Math.hypot(r.ix-cam.x,r.iz-cam.z)>8000)continue;
  if(p.vt==='ship')emit(UNIT.ENEMY,r.ix,r.iy,r.iz,r.ihd,p.p||0,p.r||0,r.fid+1,Math.max(.25,(p.L||130)/FOE_L));
  else if(p.vt==='tank')emit(UNIT.TANKAI,r.ix,r.iy,r.iz,r.ihd,p.p||0,0,r.fid+1,Math.max(.6,(p.L||9)/9.2));
  else emit(UNIT.PLANEAI,r.ix,r.iy,r.iz,r.ihd,p.p||0,p.r||0,r.fid+1,Math.max(.6,(p.L||17)/17));}
}
// call-sign tags over other pilots (allies and squadmates; enemies come through the contact brackets)
const tagEls=[];
function drawTags(){
 let n=0;
 if(game.state==='playing'&&camMode==='ship')for(const r of MMO.remotes.values()){const p=r.p;if(!p.vt||!sameBloc(r.fid,PF))continue;
  const D=Math.hypot(r.ix-player.x,r.iz-player.z);if(D>6000)continue;const s=toScreen(r.ix,r.iy+(p.vt==='ship'?(p.L||100)*.18:6),r.iz);if(!s)continue;
  let el=tagEls[n];if(!el){el=document.createElement('div');el.style.cssText='position:absolute;left:0;top:0;pointer-events:none;font:600 11px system-ui;letter-spacing:.08em;text-shadow:0 1px 2px #000;white-space:nowrap;z-index:5';ui.appendChild(el);tagEls.push(el);}
  const sq=MMO.sq()&&p.sq===MMO.sq();el.style.display='block';el.style.color=sq?'#7dff7a':FACTIONS[r.fid].css;
  el.style.transform=`translate(${Math.round(s[0])}px,${Math.round(s[1])}px) translate(-50%,-120%)`;
  const t=(sq?'◆ ':'')+r.cs.toUpperCase()+' · '+fmtD(D);if(el.textContent!==t)el.textContent=t;n++;}
 n=drawBotTags(n);
 for(let i=n;i<tagEls.length;i++)tagEls[i].style.display='none';
}
// enemy pilots: contact brackets, missile targets, and your rounds against them
function mmoContacts(add){for(const r of MMO.remotes.values()){const p=r.p;if(!p.vt||sameBloc(r.fid,PF))continue;add(r.ix,r.iy+(p.vt==='ship'?10:3),r.iz,r.fid,'PILOT '+r.cs.toUpperCase(),(p.hull||100)/100,p.vt==='ship'?Math.max(30,(p.L||100)*.5):12);}}
function mmoTargets(out){for(const r of MMO.remotes.values()){const p=r.p;if(!p.vt||sameBloc(r.fid,PF))continue;out.push({ref:r,get x(){return r.ix;},get z(){return r.iz;},get ay(){return r.iy+(p.vt==='ship'?8:2);},dead:false});}}
const remoteR=p=>p.vt==='ship'?Math.max(12,(p.L||100)*.4):p.vt==='tank'?6:9;
function mmoHit(s){
 if(!MMO.room)return false;
 for(const r of MMO.remotes.values()){const p=r.p;if(!p.vt||sameBloc(r.fid,PF))continue;
  const R=remoteR(p),dx=s.x-r.ix,dy=s.y-(r.iy+(p.vt==='ship'?5:1.5)),dz=s.z-r.iz;if(dx*dx+dz*dz>R*R||Math.abs(dy)>R)continue;
  MMO.room.emit('hit',{to:r.peer,dmg:Math.round(s.dmg)}).catch(()=>{});shellFx.push({kind:'blast',x:s.x,y:s.y,z:s.z,age:0,life:.6,size:8+Math.min(s.dmg,200)*.06});return true;}
 return false;
}
function mmoArea(x,y,z,r,dmg){
 if(MMO.room)for(const q of MMO.remotes.values()){const p=q.p;if(!p.vt||sameBloc(q.fid,PF))continue;const d=Math.hypot(q.ix-x,q.iz-z)-remoteR(p);if(d<r&&Math.abs(q.iy-y)<r+20)MMO.room.emit('hit',{to:q.peer,dmg:Math.round(dmg*(1-.6*Math.max(0,d)/r))}).catch(()=>{});}
 if(MMO.on)outpostDamage(x,z,r,dmg);
}
// squads
function squadMates(){const sq=MMO.sq();if(!sq)return [];return [...MMO.remotes.values()].filter(r=>r.p.sq===sq&&sameBloc(r.fid,PF)&&r.p.vt);}
function squadNear(R){if(!player)return false;return squadMates().some(r=>Math.hypot(r.ix-player.x,r.iz-player.z)<R);}
// radio and pings
const radioEl=document.createElement('div');radioEl.id='radio';radioEl.style.cssText='position:absolute;left:18px;bottom:190px;width:min(420px,60vw);font:12px system-ui;line-height:1.45;pointer-events:none;z-index:6';ui.appendChild(radioEl);
const radioIn=document.createElement('input');radioIn.maxLength=140;radioIn.placeholder='Radio to your side (start with /s for your squad) - Enter sends, Esc closes';
radioIn.style.cssText='position:absolute;left:18px;bottom:160px;width:min(420px,60vw);display:none;padding:7px 10px;font:13px system-ui;color:var(--ink);background:rgba(6,16,26,.85);border:1px solid var(--acc);border-radius:6px;z-index:8;outline:none';
ui.appendChild(radioIn);
function radioAdd(cs,text,fid,sq,me){MMO.radio.push({cs,text,fid,sq,t:performance.now(),me});if(MMO.radio.length>8)MMO.radio.shift();radioDraw();}
function radioDraw(){const now=performance.now();radioEl.innerHTML=MMO.radio.filter(m=>now-m.t<45000||radioIn.style.display==='block').slice(-6).map(m=>`<div style="background:rgba(4,12,20,.55);padding:2px 8px;border-radius:4px;margin-top:2px"><b style="color:${m.sq?'#7dff7a':FACTIONS[m.fid].css}">${m.sq?'[SQUAD] ':''}${esc(m.cs)}</b> ${esc(m.text)}</div>`).join('');}
function radioOpen(){if(!MMO.room){toast('Radio needs the live channel (log in from ACCOUNT on the main menu)',3000);return;}radioIn.style.display='block';radioIn.value='';if(document.exitPointerLock)document.exitPointerLock();setTimeout(()=>radioIn.focus(),20);radioDraw();}
radioIn.addEventListener('keydown',e=>{e.stopPropagation();
 if(e.code==='Escape'){radioIn.style.display='none';radioIn.blur();lockPointer();}
 if(e.code==='Enter'){let t=radioIn.value.trim();const sq=t.startsWith('/s ');if(sq)t=t.slice(3).trim();
  if(t){if(sq&&!MMO.sq())toast('Join a squad first (L opens the War Room)',2500);else MMO.room.emit('radio',{fid:PF,ch:sq?'sq':'fac',sq:MMO.sq(),cs:profile?profile.callsign:'?',text:t.slice(0,140)}).catch(()=>{});}
  radioIn.style.display='none';radioIn.blur();lockPointer();}});
function sendPing(wp){
 if(!MMO.room||!player)return;const [x,z]=VS.type==='plane'?[player.x,player.z]:(()=>{const a=aimPoint();return [a[0],a[2]];})();
 if(wp&&!MMO.sq()){toast('Join a squad to set a squad waypoint',2500);return;}
 MMO.room.emit('ping',{fid:PF,x:Math.round(x),z:Math.round(z),cs:profile?profile.callsign:'?',terr:terrName(facNearest(x,z)),wp:!!wp,sq:MMO.sq()}).catch(()=>{});
 toast(wp?'Squad waypoint set':'Help request sent to your side',1800);
}
function mmoMap(mapX,span,n){
 const now=performance.now();
 for(const r of MMO.remotes.values()){if(!r.p.vt||!sameBloc(r.fid,PF))continue;const px=(r.ix-cam.x)/span*n+n/2,py=(r.iz-cam.z)/span*n+n/2;if(px<0||py<0||px>n||py>n)continue;
  mapX.fillStyle=MMO.sq()&&r.p.sq===MMO.sq()?'#7dff7a':FACTIONS[r.fid].css;mapX.strokeStyle='#000';mapX.beginPath();mapX.arc(px,py,3.5,0,6.283);mapX.fill();mapX.stroke();}
 for(const b of allBots()){if(!sameBloc(b.fid,PF))continue;const px=(b.x-cam.x)/span*n+n/2,py=(b.z-cam.z)/span*n+n/2;if(px<0||py<0||px>n||py>n)continue;mapX.fillStyle=FACTIONS[b.fid].css;mapX.strokeStyle='#000';mapX.beginPath();mapX.arc(px,py,2.6,0,6.283);mapX.fill();mapX.stroke();}
 for(const p of MMO.pings){if(now-p.t>90000)continue;const px=(p.x-cam.x)/span*n+n/2,py=(p.z-cam.z)/span*n+n/2;if(px<0||py<0||px>n||py>n)continue;
  mapX.strokeStyle=p.wp?'#7dff7a':'#ffd36b';mapX.lineWidth=2;mapX.beginPath();mapX.arc(px,py,5+2*Math.sin(now/200),0,6.283);mapX.stroke();mapX.lineWidth=1;}
 for(const o of MMO.outposts.values()){const px=(o.x-cam.x)/span*n+n/2,py=(o.z-cam.z)/span*n+n/2;if(px<0||py<0||px>n||py>n)continue;mapX.fillStyle=FACTIONS[o.fid].css;mapX.fillRect(px-3,py-3,6,6);}
 const o=MMO.off;if(o&&!o.done){const px=(o.x-cam.x)/span*n+n/2,py=(o.z-cam.z)/span*n+n/2;if(px>0&&py>0&&px<n&&py<n){mapX.strokeStyle='#ff5040';mapX.lineWidth=2;mapX.strokeRect(px-6,py-6,12,12);mapX.lineWidth=1;}}
}
function mmoWarMap(g,toPx,W){
 const now=performance.now();
 for(const o of MMO.outposts.values()){const [px,py]=toPx(o.x,o.z);if(px<0||py<0||px>W||py>W)continue;g.fillStyle=FACTIONS[o.fid].css;g.strokeStyle='#000';g.fillRect(px-4,py-4,8,8);g.strokeRect(px-4,py-4,8,8);}
 for(const p of MMO.pings){if(now-p.t>90000)continue;const [px,py]=toPx(p.x,p.z);g.strokeStyle=p.wp?'#7dff7a':'#ffd36b';g.lineWidth=2;g.beginPath();g.arc(px,py,8,0,6.283);g.stroke();g.fillStyle='#fff';g.font='600 9px Segoe UI, Arial';g.textAlign='center';g.fillText(p.cs,px,py-11);}
 for(const r of MMO.remotes.values()){if(!r.p.vt||!sameBloc(r.fid,PF))continue;const [px,py]=toPx(r.ix,r.iz);g.fillStyle=FACTIONS[r.fid].css;g.beginPath();g.arc(px,py,4,0,6.283);g.fill();g.fillStyle='#fff';g.font='600 9px Segoe UI, Arial';g.textAlign='center';g.fillText(r.cs,px,py-7);}
 const o=MMO.off;if(o&&!o.done){const [px,py]=toPx(o.x,o.z);g.strokeStyle='#ff5040';g.lineWidth=2.5;g.strokeRect(px-10,py-10,20,20);g.fillStyle='#ffb0a0';g.font='700 10px Segoe UI, Arial';g.textAlign='center';g.fillText('OFFENSIVE',px,py-14);}
 g.lineWidth=1;
}
function mmoLegend(){
 if(!MMO.on)return '';
 const sc=seasonCount(),o=MMO.off,st=offState();
 let h=`<div class="wsep"></div><div class="sub" style="margin:0 0 6px">THE SHARED WAR &middot; SEASON ${MMO.season.n}</div><p>Compact + League hold <b>${sc.bloc[0]}</b>, Dominion + Syndicate <b>${sc.bloc[1]}</b> of ${sc.total} territories. A bloc that holds ${Math.round(SEASON_SHARE*100)}% wins the season.</p>`;
 if(o&&!o.done)h+=`<p><b style="color:#ff8070">OFFENSIVE</b> ${fTag(o.att)} attack <b>${esc(o.name)}</b> &middot; ${st==='soon'?'starts in '+mmss((o.start-Date.now())/1000):st==='live'?'LIVE, '+mmss((o.end-Date.now())/1000)+' left':'resolving'}</p>`;
 return h;
}
const mmss=v=>{v=Math.max(0,v);return Math.floor(v/60)+':'+String(Math.floor(v%60)).padStart(2,'0');};
// the HUD line: offensive countdown, squad, underdog
function mmoLineHtml(){
 if(!MMO.on)return '';
 const o=MMO.off,st=offState();let h='';
 if(o&&st==='soon')h+=`<br><span style="color:#ff8070">OFFENSIVE ${esc(o.name).toUpperCase()} IN ${mmss((o.start-Date.now())/1000)}</span>`;
 if(o&&st==='live'){const D=player?Math.hypot(player.x-o.x,player.z-o.z):1e9;h+=`<br><span style="color:#ff8070">OFFENSIVE LIVE &middot; ${esc(o.name).toUpperCase()} &middot; ${mmss((o.end-Date.now())/1000)}${D<5000?' &middot; YOU ARE IN IT':' &middot; '+fmtD(D).toUpperCase()}</span>`;}
 const sm=squadMates();if(MMO.sq())h+=`<br><span style="color:#7dff7a">SQUAD ${esc(MMO.sq())} &middot; ${sm.length} ONLINE${squadNear(1500)?' &middot; +20% XP':''}</span>`;
 if(underdog())h+=`<br><span style="color:#ffd36b">UNDERDOG BONUS +25% XP</span>`;
 return h;
}
// ---------- the War Room (L) ----------
const wr=document.createElement('div');wr.id='warroom';wr.className='panel';
wr.style.cssText='position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);width:min(760px,94vw);max-height:86vh;overflow:auto;padding:18px 22px;display:none;z-index:9;pointer-events:auto';
ui.appendChild(wr);let wrTab='war';
function openWarRoom(){if(document.exitPointerLock)document.exitPointerLock();wr.style.display='block';renderWarRoom();}
function closeWarRoom(){wr.style.display='none';if(game.state==='playing')lockPointer();}
function renderWarRoom(){
 const tabs=[['war','THE WAR'],['doctrine','DOCTRINE'],['routes','SUPPLY ROUTES'],['pilots','PILOTS'],['squad','SQUAD'],['treasury','TREASURY'],['side','YOUR SIDE'],...(OWNER?[['owner','OWNER']]:[])];
 let h=`<div style="display:flex;justify-content:space-between;align-items:center"><h2 class="t" style="margin:0">WAR ROOM</h2><button class="btn sm" id="wr-x" style="width:auto;margin:0">CLOSE (L)</button></div>
 <div class="tabs" style="margin:10px 0 12px">${tabs.map(([k,n])=>`<button data-wr="${k}" class="${wrTab===k?'on':''}">${n}</button>`).join('')}</div>`;
 if(!MMO.on&&!['owner','doctrine','routes'].includes(wrTab))h+=`<p style="color:var(--warn)">You are playing offline: log in from ACCOUNT on the main menu to join the shared war. Everything here fills in once you are online.</p>`;
 const cnt=pilotCounts(),sc=seasonCount(),o=MMO.off,st=offState();
 if(wrTab==='war'){
  h+=`<div class="sub" style="margin:0 0 6px">SEASON ${MMO.season.n}</div><p>A bloc that holds ${Math.round(SEASON_SHARE*100)}% of the ${sc.total} territories within ${SEASON_R/1000} km of the centre wins the season early; otherwise the bloc holding more when the week ends (Monday 00:00 UTC) takes it. Its pilots get a badge and the map resets. Your vehicles, salvage and refits are never reset.</p>`;
  for(const b of [0,1]){const pc=sc.bloc[b]/sc.total*100;h+=`<div class="gstat"><span style="text-align:left;color:var(--dim)">${b===0?'COMPACT + LEAGUE':'DOMINION + SYNDICATE'}</span><div><i style="width:${pc}%;background:${FACTIONS[b*2].css}"></i></div><span>${sc.bloc[b]}</span></div>`;}
  h+=`<p style="color:var(--dim);font-size:12px">${FACTIONS.map(F=>`<b style="color:${F.css}">${F.tag}</b> ${sc.c[F.id]} territories, ${cnt[F.id]} pilots`).join(' &middot; ')}</p>`;
  h+=`<div class="sub" style="margin:12px 0 6px">OFFENSIVE</div>`+(o&&!o.done?`<p>${fTag(o.att)} attack <b>${esc(o.name)}</b> held by ${fTag(o.def)}. ${st==='soon'?'Starts in '+mmss((o.start-Date.now())/1000):st==='live'?'<b style="color:#ff8070">Live</b> - '+mmss((o.end-Date.now())/1000)+' left':'Being decided'}. Everything you destroy within 5 km of it scores for your side; the side with more points takes the territory. Winners who fought get 1000 credits.</p>`:`<p style="color:var(--dim)">${o&&o.result?'Last: '+fTag(o.result.winner)+' held '+esc(o.name)+' ('+o.result.pa+' to '+o.result.pd+'). ':''}The next offensive is announced 10 minutes before it starts.</p>`);
  if(MMO.season.hist.length)h+=`<div class="sub" style="margin:12px 0 6px">PAST SEASONS</div>`+MMO.season.hist.slice(-5).reverse().map(x=>`<p class="wlog">Season ${x.n}: ${x.winner===0?'Compact + League':'Dominion + Syndicate'}</p>`).join('');
 }
 if(wrTab==='pilots'){
  const wk=weekId();h+=`<div class="sub" style="margin:0 0 6px">THIS WEEK'S TOP PILOTS (resets every Monday)</div><div style="display:grid;grid-template-columns:1fr 1fr;gap:14px">`;
  for(const F of FACTIONS){const L=MMO.pilots.filter(p=>(p.fid|0)===F.id&&p.week===wk&&p.wk>0).sort((a,b)=>b.wk-a.wk).slice(0,8);const tot=L.reduce((s,p)=>s+(p.wk|0),0);
   h+=`<div><b style="color:${F.css}">${F.name}</b> <span style="color:var(--dim)">&middot; ${tot} pts</span>${L.map((p,i)=>`<div style="font-size:12px">${i+1}. ${esc(String(p.callsign||'?').slice(0,16))} &middot; ${p.wk|0}${p.id===MMO.uid?' (you)':''}${(p.badges||[]).length?' ★':''}</div>`).join('')||'<div style="font-size:12px;color:var(--dim)">nobody yet</div>'}</div>`;}
  h+=`</div><p style="color:var(--dim);font-size:12px;margin-top:10px">Your week: <b>${Math.round(profile&&profile.wk||0)}</b> points${profile&&(profile.badges||[]).length?' &middot; badges: '+profile.badges.map(esc).join(', '):''}</p>`;
 }
 if(wrTab==='squad'){
  const sq=MMO.sq(),mates=squadMates();
  h+=sq?`<p>Squad <b style="color:#7dff7a">${esc(sq)}</b> &middot; ${mates.length} squadmate${mates.length===1?'':'s'} online: ${mates.map(r=>esc(r.cs)).join(', ')||'none right now'}</p><p style="color:var(--dim);font-size:12px">Share the code with your squad. Near each other (1.5 km) you earn +20% XP. Shift+J sets a squad waypoint, /s in the radio talks to the squad.</p><button class="btn sm" id="wr-leave" style="width:auto">LEAVE SQUAD</button>`
   :`<p>Make a squad and give the code to your friends, or join theirs.</p><button class="btn sm pri" id="wr-make" style="width:auto">MAKE A SQUAD</button>`;
  h+=`<div style="display:flex;gap:8px;margin-top:10px"><input id="wr-code" maxlength="12" placeholder="SQUAD CODE" style="flex:1;padding:8px 10px;font:600 14px system-ui;letter-spacing:.1em;text-transform:uppercase;color:var(--ink);background:rgba(6,16,26,.8);border:1px solid var(--line);border-radius:6px"><button class="btn sm" id="wr-join" style="width:auto;margin:0">JOIN</button></div>`;
  const others=[...MMO.remotes.values()].filter(r=>sameBloc(r.fid,PF)&&r.p.sq&&r.p.sq!==sq);const codes=[...new Set(others.map(r=>r.p.sq))];
  if(codes.length)h+=`<p style="color:var(--dim);font-size:12px;margin-top:10px">Squads on your side right now: ${codes.map(c=>`<a href="#" data-sq="${esc(c)}" style="color:#7dff7a">${esc(c)}</a>`).join(' &middot; ')}</p>`;
 }
 if(wrTab==='treasury'){
  const f=PF,funds=factionFunds(f),v=votes(f);
  {const tp=teamProject(),c=upCost(tp.id),pc=Math.min(100,Math.round(funds/c*100));
   h+=`<p>The ${FACTIONS[f].name} treasury: <b>${funds}</b> funds. Convoy kills, captures, outposts and destroyed enemy outposts pay in. There is no vote: the whole side works on one <b>team project</b> at a time, and it is bought the moment the bar is full.</p>
   <div class="svc"><div><h3>TEAM PROJECT &middot; ${tp.name.toUpperCase()} LEVEL ${upLvl(tp.id)+1}</h3><p>${tp.d}</p><div style="height:8px;background:rgba(255,255,255,.1);border-radius:4px;margin-top:8px"><i style="display:block;height:100%;width:${pc}%;background:#f2b84b;border-radius:4px"></i></div><p style="margin-top:6px">${funds} / ${c} &middot; ${pc}%</p></div></div>`;}
  h+=`<p style="color:var(--dim);font-size:12px">Levels now: ${UPGRADES.map(u=>u.name+' '+upLvl(u.id)).join(' &middot; ')}</p>`;
  for(const u of UPGRADES)if(0)h+=`<div class="svc" style="grid-template-columns:1fr auto"><div><h3>${u.name.toUpperCase()} &middot; LEVEL ${upLvl(u.id)}</h3><p>${u.d} &middot; next level ${upCost(u.id)} &middot; ${v[u.id]||0} vote${(v[u.id]||0)===1?'':'s'}</p></div><button class="btn sm ${profile&&profile.vote===u.id?'pri':''}" data-vote="${u.id}" style="width:auto">${profile&&profile.vote===u.id?'YOUR VOTE':'VOTE'}</button></div>`;
 }
 if(wrTab==='side'){
  h+=`<p>You fly for the <b style="color:${FACTIONS[PF].css}">${FACTIONS[PF].name}</b>. ${underdog()?'<b style="color:#ffd36b">Your bloc is short of pilots this week: +25% XP.</b>':''}</p><p style="color:var(--dim);font-size:12px">Changing sides resets your standing with every power and moves you to your new home base. You can change once per season.</p><div style="display:grid;grid-template-columns:1fr 1fr;gap:8px">`;
  for(const F of FACTIONS)h+=`<button class="btn sm ${F.id===PF?'pri':''}" data-side="${F.id}" style="margin:0;border-color:${F.css}" ${F.id===PF?'disabled':''}>${F.name.toUpperCase()} &middot; ${cnt[F.id]} PILOTS</button>`;
  h+=`</div>`;
 }
 if(wrTab==='doctrine')h+=doctrineTab();
 if(wrTab==='routes')h+=routesTab();
 if(wrTab==='owner')h+=ownerTab();
 wr.innerHTML=h;
 $('wr-x').onclick=closeWarRoom;
 wireWarRoomSalv(wr);
 for(const b of wr.querySelectorAll('[data-own]'))b.onclick=()=>ownerAction(b.dataset.own,b);
 for(const b of wr.querySelectorAll('[data-wr]'))b.onclick=()=>{wrTab=b.dataset.wr;renderWarRoom();};
 for(const b of wr.querySelectorAll('[data-vote]'))b.onclick=()=>{if(!profile)return;profile.vote=b.dataset.vote;profileSave();MMO.cardT=0;renderWarRoom();setTimeout(mmoTreasuryCheck,1500);};
 for(const b of wr.querySelectorAll('[data-side]'))b.onclick=()=>{const f=+b.dataset.side;if(profile&&profile.sideSeason===MMO.season.n&&profile.sideChanged){toast('You already changed sides this season',2500);return;}
  if(!b.dataset.arm){b.dataset.arm=1;b.textContent='CLICK AGAIN TO JOIN THE '+FACTIONS[f].tag;return;}
  if(profile){profile.sideChanged=true;profile.sideSeason=MMO.season.n;}setFaction(f,true);closeWarRoom();};
 for(const a of wr.querySelectorAll('[data-sq]'))a.onclick=e=>{e.preventDefault();setSquad(a.dataset.sq);};
 const ci=$('wr-code');if(ci)ci.addEventListener('keydown',e=>e.stopPropagation());
 if($('wr-make'))$('wr-make').onclick=()=>{const w=['WOLF','HAWK','IRON','STORM','VIPER','GHOST','RAVEN','TIDE'];setSquad(w[Math.floor(Math.random()*w.length)]+'-'+(10+Math.floor(Math.random()*90)));};
 if($('wr-join'))$('wr-join').onclick=()=>{const c=$('wr-code').value.toUpperCase().replace(/[^A-Z0-9-]/g,'').slice(0,12);if(c.length>=3)setSquad(c);};
 if($('wr-leave'))$('wr-leave').onclick=()=>setSquad('');
}
function setSquad(code){if(!profile)return;profile.sq=code;profileSave();MMO.presT=0;toast(code?'Squad '+code+' - share the code with your squadmates':'You left the squad',3000);renderWarRoom();}
// changing the power you fly for: relations, home harbour and start position all follow
function setFaction(f,reset){
 if(f<0||f>3)return;PF=f;applyRels();facCache.clear();warMapDirty=true;objCache=null;
 if(profile){profile.fid=f;profileSave();}
 if(reset){career.rep=[0,0,0,0];careerDirty=true;}
 for(const key of Object.keys(war.own))rebuildTerritory(key);
 const h=safeHomePort();
 if(h){gotoPort(h);if(player){const b=berthFor(h,'ship');player.x=b.x;player.z=b.z;player.hd=b.hd;}
  for(const u of [800,1000,1300,1700,2200,2800]){const x=h.x+h.ux*u,z=h.z+h.uz*u;if(T.height(x,z)<-10&&facRel(factionAt(x,z))>=0){game.start={x,z,hd:headingOf(h.ux,h.uz)};break;}}}
 foes.length=0;MMO.cardT=0;
 if(game.state==='playing'||game.state==='paused'||game.state==='docked')setState('menu');
 toast('You now fly for the '+FACTIONS[f].name+'. Your home base is '+(h?portName(h.id):'ready')+'.',6000);
}
// ---------- per frame ----------
function mmoTick(t,dt){
 remotesTick(dt);drawTags();botTick(dt);botChatter(dt);
 if(MMO.radio.length&&frameNo%30===0)radioDraw();
 if(!MMO.on)return;
 presenceTick(dt);
 MMO.hostT-=dt;if(MMO.hostT<=0){MMO.hostT=20;mmoHostTick();}
 MMO.offT-=dt;if(MMO.offT<=0){MMO.offT=10;mmoOffHost();}
 MMO.seasonT-=dt;if(MMO.seasonT<=0){MMO.seasonT=30;mmoSeasonCheck();}
 MMO.treasT-=dt;if(MMO.treasT<=0){MMO.treasT=40;mmoTreasuryCheck();}
 MMO.cardT-=dt;if(MMO.cardT<=0){MMO.cardT=45;cloudPush(false);}
 if(frameNo%60===0)outpostFlush();
 if(game.state==='playing'){mmoOffLocal(dt);outpostTick(dt);}
}
addEventListener('keydown',e=>{
 if(e.code==='KeyL'&&(game.state==='playing'||game.state==='menu')){if(wr.style.display==='block')closeWarRoom();else openWarRoom();return;}
 if(game.state!=='playing'||camMode!=='ship'||wr.style.display==='block')return;
 if(e.code==='KeyY'){e.preventDefault();radioOpen();}
 if(e.code==='KeyJ')sendPing(e.shiftKey);
 if(e.code==='KeyO')buildOutpost();
});
addEventListener('keydown',e=>{if(e.code==='Escape'&&wr.style.display==='block'&&!(e.target&&e.target.tagName==='INPUT')){closeWarRoom();e.stopImmediatePropagation();}},true);   // Esc closes the War Room without pausing
window.__mmo={MMO,setFaction,setSquad,seasonCount,openWarRoom,mmoSetTerr,buildOutpost,offState};


// ---------- v2.6 every front, deployment, and the owner's account ----------
// FRONT LINES: frontLines() walks every border between the two blocs over land within SEASON_R of the centre (cached; recomputed when the
//   war map changes) - drawn on the war map and minimap, listed on the deploy screen.
// DEPLOY: from the garage (menu), the harbour screen or the pause menu, pick where the sortie starts: home harbour, any front, the live
//   offensive, or one of your side's outposts. Ships start in the nearest deep water on your side, tanks behind your trenches, planes
//   in the air 3 km back, heading in. deployAt(D) runs after newVoyage().
// OWNER: the artifact owner's account (user.isOwner()) has every unlock, the sandbox switch, and the War Room OWNER tab (start/end an
//   offensive, reset the shared map, end the season, credits, ladder step). Nobody else gets these.
var OWNER=false;
let flCache=null,flDirtyT=0,flVer=-1;
function frontLines(force){
 const ver=JSON.stringify(war.own).length+Object.keys(war.own).length*7+PF;
 if(flCache&&!force&&(ver===flVer||performance.now()-flDirtyT<20000))return flCache;
 flVer=ver;flDirtyT=performance.now();
 const n=Math.ceil(SEASON_R/FAC_CELL),seeds=[];
 for(let j=-n;j<=n;j++)for(let i=-n;i<=n;i++){const s=facSeed(i,j);if(Math.hypot(s.x,s.z)<SEASON_R)seeds.push(s);}
 const out=[];
 for(let p=0;p<seeds.length;p++)for(let q=p+1;q<seeds.length;q++){
  const a=seeds[p],b=seeds[q];if(Math.abs(a.i-b.i)>2||Math.abs(a.j-b.j)>2||Math.hypot(a.x-b.x,a.z-b.z)>FAC_CELL*2.2)continue;
  const fa=facOfSeed(a),fb=facOfSeed(b);if(sameBloc(fa,fb))continue;
  const mx=(a.x+b.x)/2,mz=(a.z+b.z)/2,dx=b.x-a.x,dz=b.z-a.z,l=Math.hypot(dx,dz),ex=dz/l,ez=-dx/l,ka=terrKey(a),kb=terrKey(b);
  {const km=terrKey(facNearest(mx,mz));if(km!==ka&&km!==kb)continue;}                 // not neighbours: their bisector runs through a third territory
  let run=null;const runs=[];
  for(let t=-9000;t<=9000;t+=200){const x=mx+ex*t,z=mz+ez*t,s=facNearest(x,z),k=terrKey(s);
   const ok=(k===ka||k===kb)&&T.heightNR(x,z)>4;if(!ok&&!run&&runs.length&&(k!==ka&&k!==kb))continue;
   if(ok){if(!run){run=[];runs.push(run);}run.push([x,z]);}else run=null;}
  for(const r of runs)if(r.length>=3)out.push({a,b,fa,fb,pts:r,n:[-dx/l,-dz/l],name:terrName(a)+' / '+terrName(b),key:ka+'~'+kb,mid:r[Math.floor(r.length/2)]});
 }
 return flCache=out;
}
function drawFrontLines(g,toPx,W,thin){
 // v3.5: each line is drawn where the fighting has pushed it, in the colour of the side gaining ground, with an arrow showing the push
 const cut=[];
 for(const F of frontLines()){
  const mine=sameBloc(F.fa,PF)||sameBloc(F.fb,PF),p=war.fp[F.key]||0,sh=frontShift(F.key),ox=-F.n[0]*sh,oz=-F.n[1]*sh;
  const lead=Math.abs(p)<8?-1:p>0?F.fa:F.fb,col=lead<0?(mine?'rgba(255,80,60,.95)':'rgba(255,170,80,.6)'):FACTIONS[lead].css;
  g.strokeStyle='rgba(0,0,0,.55)';g.lineWidth=(thin?2.6:4.4);g.setLineDash([]);g.beginPath();
  F.pts.forEach((q,i)=>{const [x,y]=toPx(q[0]+ox,q[1]+oz);if(i)g.lineTo(x,y);else g.moveTo(x,y);});g.stroke();
  g.strokeStyle=col;g.lineWidth=thin?1.6:2.6+Math.abs(p)/50;g.setLineDash(thin?[3,2]:[7,4]);g.beginPath();
  F.pts.forEach((q,i)=>{const [x,y]=toPx(q[0]+ox,q[1]+oz);if(i)g.lineTo(x,y);else g.moveTo(x,y);});g.stroke();g.setLineDash([]);
  if(!thin&&lead>=0){                                                    // the push: an arrow into the losing side, and how far it has got
   const [mx,my]=toPx(F.mid[0]+ox,F.mid[1]+oz),dir=p>0?-1:1,ax=F.n[0]*dir,az=F.n[1]*dir,L=8+Math.abs(p)/7;
   g.strokeStyle=FACTIONS[lead].css;g.fillStyle=FACTIONS[lead].css;g.lineWidth=3;g.beginPath();g.moveTo(mx-ax*L*.4,my-az*L*.4);g.lineTo(mx+ax*L,my+az*L);g.stroke();
   g.beginPath();g.moveTo(mx+ax*(L+6),my+az*(L+6));g.lineTo(mx+ax*L-az*5,my+az*L+ax*5);g.lineTo(mx+ax*L+az*5,my+az*L-ax*5);g.closePath();g.fill();
   g.font='700 9px Segoe UI, Arial, sans-serif';g.textAlign='center';g.fillStyle='#fff';g.strokeStyle='rgba(0,0,0,.7)';g.lineWidth=3;
   const tx=mx-ax*14,ty=my-az*14+3,lbl=Math.round(Math.abs(p))+'%';g.strokeText(lbl,tx,ty);g.fillText(lbl,tx,ty);}
 }
 if(!thin)for(const [k,v] of supplyMap){if(v>=1)continue;const [i,j]=k.split(',').map(Number),sd=facSeed(i,j),[x,y]=toPx(sd.x,sd.z);   // pockets cut off from their capital
  if(x<-20||y<-20||x>W+20||y>W+20)continue;g.font='700 9px Segoe UI, Arial, sans-serif';g.textAlign='center';g.fillStyle='#ffb347';g.strokeStyle='rgba(0,0,0,.75)';g.lineWidth=3;
  g.strokeText('⚠ CUT OFF',x,y+14);g.fillText('⚠ CUT OFF',x,y+14);}
 g.setLineDash([]);g.lineWidth=1;
}
// ---- the deploy screen ----
ui.insertAdjacentHTML('beforeend',`<div id="deploy" class="screen"><div class="box panel" style="max-width:640px;max-height:84vh;overflow:auto">
 <h2 class="t">DEPLOY</h2><div class="sub" id="dp-sub">WHERE DOES THIS SORTIE START?</div><div id="dp-list" style="margin-top:12px"></div>
 <button class="btn" id="dp-back" style="margin-top:12px">BACK</button></div></div>`);
SCREENS.push('deploy');
let deployFrom='menu',pendingDeploy=null;
function deployOptions(){
 const opts_=[],me=player?[player.x,player.z]:[cam.x,cam.z],home=safeHomePort();
 opts_.push({kind:'home',name:'Home base'+(home?' · '+portName(home.id):''),sub:'Safe behind the lines - the slow way to the war'});
 const o=MMO.off,st=typeof offState==='function'?offState():null;
 if(o&&(st==='live'||st==='soon'))opts_.push({kind:'off',name:'Offensive: '+o.name,sub:(st==='live'?'LIVE NOW':'starts in '+mmss((o.start-Date.now())/1000))+' · '+FACTIONS[o.att].tag+' attack',x:o.x,z:o.z,att:o.att,def:o.def,hot:true});
 const lines=frontLines().filter(F=>sameBloc(F.fa,PF)||sameBloc(F.fb,PF)).map(F=>({F,d:Math.hypot(F.mid[0]-me[0],F.mid[1]-me[1])})).sort((p,q)=>p.d-q.d);
 for(const {F,d} of lines.slice(0,10)){const us=sameBloc(F.fa,PF)?F.fa:F.fb,them=us===F.fa?F.fb:F.fa;
  opts_.push({kind:'front',name:'Front: '+F.name,sub:`${FACTIONS[us].tag} against ${FACTIONS[them].tag} · ${(F.pts.length*.2).toFixed(1)} km of line · ${fmtD(d)} away`,F});}
 if(MMO.on)for(const op of MMO.outposts.values())if(sameBloc(op.fid,PF))opts_.push({kind:'outpost',name:'Outpost of '+FACTIONS[op.fid].tag+(op.by?' ('+String(op.by).slice(0,16)+')':''),sub:'rearm and repair there with F · '+fmtD(Math.hypot(op.x-me[0],op.z-me[1]))+' away',x:op.x,z:op.z});
 return opts_;
}
function openDeploy(from){
 deployFrom=from;const L=deployOptions();
 $('dp-sub').textContent='WHERE DOES YOUR '+(VS?VS.name.toUpperCase():'SORTIE')+' START?';
 $('dp-list').innerHTML=L.map((d,i)=>`<div class="svc" style="grid-template-columns:1fr auto"><div><h3>${d.hot?'<span style="color:#ff8070">● </span>':''}${esc(d.name).toUpperCase()}</h3><p>${esc(d.sub)}</p></div><button class="btn sm ${i===0&&from!=='pause'?'':'pri'}" data-dp="${i}" style="width:auto">DEPLOY</button></div>`).join('');
 for(const b of $('dp-list').querySelectorAll('[data-dp]'))b.onclick=()=>chooseDeploy(L[+b.dataset.dp]);
 showScreen('deploy');if(document.exitPointerLock&&document.pointerLockElement)document.exitPointerLock();
}
$('dp-back').onclick=()=>{if(hgReturn){const f=hgReturn;hgReturn=null;showScreen(f==='play'?null:'menu');openHangar(f);return;}if(deployFrom==='garage')showScreen('garage');else if(deployFrom==='port')showScreen('port');else if(deployFrom==='pause')showScreen('pause');else showScreen('menu');};
function chooseDeploy(D){
 pendingDeploy=D.kind==='home'?null:D;
 if(deployFrom==='port'){game.port=null;}
 newVoyage();
}
// where a vehicle should start for a deployment point
function deployAt(D){
 if(typeof escSortie!=='undefined')escSortie++;
 hgReturn=null;
 ride=null;
 if(!D||!player||!VS)return;
 let tx,tz,nx=0,nz=1;                                   // n: toward our side
 if(D.kind==='front'){const F=D.F,us=sameBloc(F.fa,PF);nx=us?F.n[0]:-F.n[0];nz=us?F.n[1]:-F.n[1];
  let best=F.mid,bd=1e9;for(const p of F.pts){const d=Math.hypot(p[0]-player.x,p[1]-player.z);if(d<bd){bd=d;best=p;}}[tx,tz]=best;}
 else if(D.kind==='off'){tx=D.x;tz=D.z;const c=capitalOf(PF),dx=c.x-tx,dz=c.z-tz,l=Math.hypot(dx,dz)||1;nx=dx/l;nz=dz/l;}
 else{tx=D.x;tz=D.z;const c=capitalOf(PF),dx=c.x-tx,dz=c.z-tz,l=Math.hypot(dx,dz)||1;nx=dx/l;nz=dz/l;}
 let pos=null;
 if(VS.type==='plane'){                                             // v2.8: planes go up from the airfield of your side nearest the front
  pos=[tx+nx*2500,tz+nz*2500];}
 if(VS.type==='ship'){for(const back of [900,1600,2500,3500,5000]){const q=seaSpot(tx+nx*back,tz+nz*back,900);if(q&&facRel(factionAt(q[0],q[1]))>=0){pos=q;break;}}
  if(!pos){toast('No water near that front for a ship - starting from your home base. Take a tank or a plane there.',5000);return;}
  }
 else if(VS.type==='tank'){const back=D.kind==='outpost'?40:TRENCH_OFF+420;for(const r of [80,200,400,800]){const q=landSpot(tx+nx*back,tz+nz*back,r);if(q){pos=q;break;}}
  if(!pos){toast('No firm ground behind that front - starting from your home base',4000);return;}
  }
 const hd=headingOf(tx-pos[0],tz-pos[1]);
 player.x=pos[0];player.z=pos[1];player.hd=hd;player.v=0;player.pitch=0;player.roll=0;
 if(VS.type==='ship'){player.y=.5;player.gnd=false;game.start={x:pos[0],z:pos[1],hd};}
 else if(VS.type==='tank'){player.y=T.height(pos[0],pos[1]);player.gnd=true;groundPose(player,1);}
 else{player.y=Math.max(T.height(pos[0],pos[1]),0)+600;player.gnd=false;player.v=VS.cruise;helm.throttle=.75;planeAim.init=null;}
 game.port=null;orbit.yaw=hd-Math.PI/2;cam.x=player.x;cam.z=player.z;
 toast('Deployed: '+D.name+'. The world around you is loading in.',4500);
}
// ---- the owner's account ----
function ownerReady(){
 OWNER=true;ladHudDirty=true;
 for(const id of ['s-lad-l','s-lad'])if($(id))$(id).style.display='';
 garage.specs={ship:garage.specs.ship,tank:garage.specs.tank,plane:garage.specs.plane};
 if(game.state==='garage')renderGarage();
 toast('Owner account: every unlock is open to you, and the War Room has an OWNER tab',4500);
}
function ownerTab(){
 if(!OWNER)return '';
 return `<p>Only your account sees this. Every unlock is open to you whatever your ladder step (step ${ladStep()+1}).</p>
 <div style="display:grid;grid-template-columns:1fr 1fr;gap:8px">
  <button class="btn sm" data-own="off">START AN OFFENSIVE NOW</button><button class="btn sm" data-own="offend">END THE OFFENSIVE NOW</button>
  <button class="btn sm" data-own="credits">+10,000 CREDITS</button><button class="btn sm" data-own="sandbox">${ladLoad().sandbox?'SANDBOX DIFFICULTY: ON':'SANDBOX DIFFICULTY: OFF'}</button>
  <button class="btn sm" data-own="stepdn">LADDER STEP -1</button><button class="btn sm" data-own="stepup">LADDER STEP +1</button>
  <button class="btn sm" data-own="reset">RESET THE SHARED MAP</button><button class="btn sm" data-own="season">END THE SEASON NOW</button></div>`;
}
async function ownerAction(a,btn){
 if(!OWNER)return;
 if((a==='reset'||a==='season')&&!btn.dataset.arm){btn.dataset.arm=1;btn.textContent='CLICK AGAIN TO CONFIRM';return;}
 if(a==='credits'){career.credits=(career.credits||0)+10000;careerDirty=true;toast('+10,000 credits',2000);}
 if(a==='sandbox'){ladLoad().sandbox=!ladLoad().sandbox;ladSave();ladHudDirty=true;}
 if(a==='stepup'||a==='stepdn'){const L=ladLoad();L.step=Math.max(0,Math.min(LADDER.length-1,L.step+(a==='stepup'?1:-1)));L.prog={};ladSave();ladHudDirty=true;}
 if(!MMO.on&&['off','offend','reset','season'].includes(a)){toast('That needs the shared war (log in from ACCOUNT on the main menu)',3000);renderWarRoom();return;}
 if(a==='off'){const cap=player?{x:player.x,z:player.z}:capitalOf(PF);const pairs=frontPairs(cap.x,cap.z).filter(([p,q,fa,fb])=>!sameBloc(fa,fb));
  if(!pairs.length){toast('No border between the blocs near you',2500);}
  else{const [p,q,fa,fb]=pairs[Math.floor(Math.random()*pairs.length)],att=sameBloc(fa,PF)?fb:fa,def=att===fa?fb:fa,tgt=att===fa?q:p,now=Date.now();
   await MMO.db.doc('world/offensive').set({id:'o'+now,key:terrKey(tgt),name:terrName(tgt),x:(p.x+q.x)/2,z:(p.z+q.z)/2,att,def,start:now+60000,end:now+16*60000,done:false}).catch(()=>{});toast('Offensive called: starts in 1 minute',2500);}}
 if(a==='offend'&&MMO.off&&!MMO.off.done){const o={...MMO.off,end:Date.now()-6000};MMO.off=o;await mmoOffResolve();}
 if(a==='reset'){const q=await MMO.db.collection('terr').get().catch(()=>null);if(q)for(const d of q.docs)await MMO.db.doc('terr/'+d.id).delete().catch(()=>{});toast('Shared map reset',2500);}
 if(a==='season'){const sc=seasonCount(),b=sc.bloc[0]>=sc.bloc[1]?0:1,hist=[...MMO.season.hist,{n:MMO.season.n,winner:b,end:Date.now()}].slice(-10);
  await MMO.db.doc('world/season').set({n:MMO.season.n+1,winner:b,hist,start:Date.now()}).catch(()=>{});
  const q=await MMO.db.collection('terr').get().catch(()=>null);if(q)for(const d of q.docs)await MMO.db.doc('terr/'+d.id).delete().catch(()=>{});toast('Season ended',2500);}
 renderWarRoom();
}
window.__deploy={frontLines,deployOptions,openDeploy,deployAt,get OWNER(){return OWNER;},set OWNER(v){if(v)ownerReady();else OWNER=false;}};


// ---------- v2.7 AI tank turrets that turn, and AI pilots so the war is never empty ----------
// TURRETS: the AI tank mesh is split in two: the hull (UNIT.TANKAI) and the turret with its gun (UNIT.TANKTUR, turned about its own pivot).
//   emit() draws the turret with every AI tank; tankTurHd (set just before an emit) is the way it points - at the target for war tanks.
// AI PILOTS: named computer pilots (call sign + "AI") of both blocs keep the area round you busy: warships at sea, tanks on land, fighters
//   in the air, matched to what you are driving. Friendly ones fight beside you and talk on the radio; enemy ones hunt you. Fewer spawn
//   when real pilots are online. They are ordinary war units (foes / armour / air) carrying .bot = {cs}.
UNIT.TANKTUR=unitList.length;unitList.push([]);UNIT_DRAW_R.push(UNIT_DRAW_R[UNIT.TANKAI]);
let tankTurHd=null,tankPivot=[0,0];
(function(){
 const tk=defaultSpec('tank');tk.p.paint=2;const M=scaleMesh(tankMesh(tk),TANK_K*1.8);   // v4.9 the same mid-war size as the hit box
 const tur=new Set(),flash=new Set();
 M.parts.forEach((d,i)=>{const id=i+1;if(d.kind==='turret'||(d.parent&&tur.has(d.parent)))tur.add(id);if(d.kind==='flash')flash.add(id);});
 const tp=M.parts.findIndex(d=>d.kind==='turret');const pv=tp>=0?M.parts[tp].pivot:[0,0,0];tankPivot=[pv[0],pv[2]];
 const H=mesh(),Tm=mesh(),hg=new Map(),tg=new Map(),AH=[],AT=[];
 M.parts.forEach((d,i)=>{const id=i+1;if(tur.has(id)||flash.has(id)){if(d.kind==='barrel'||d.kind==='flash'){AT.push(d);tg.set(id,AT.length);}}
  else if(d.kind==='wheel'||d.kind==='tread'){AH.push(d);hg.set(id,AH.length);}});
 for(let v=0;v<M.G.length;v+=3){const g=M.G[v],onT=tur.has(g)||flash.has(g),O=onT?Tm:H,dx=onT?pv[0]:0,dz=onT?pv[2]:0,gi=onT?(tg.get(g)||0):(hg.get(g)||0);
  for(let k=v;k<v+3;k++){O.P.push(M.P[k*3]-dx,M.P[k*3+1],M.P[k*3+2]-dz);O.N.push(M.N[k*3],M.N[k*3+1],M.N[k*3+2]);O.C.push(M.C[k*4],M.C[k*4+1],M.C[k*4+2],M.C[k*4+3]);O.G.push(gi);}}
 H.parts=AH;Tm.parts=AT;AI_U={H:aiPartU(AH,0,0),T:aiPartU(AT,pv[0],pv[2])};
 if(Tm.P.length){unitMeshSrc[UNIT.TANKAI]=H;unitMesh[UNIT.TANKAI]=uploadUnitMesh(H);bindUnitVAO(UNIT.TANKAI);addUnitKind(Tm);extraDrawKinds.push(UNIT.TANKTUR);}
 else addUnitKind(mesh());
})();
function emitTankTurret(x,y,z,hd,pitch,phase,scale){
 {const F=kindFlags(UNIT.TANKAI),dx=x-cam.x,dz=z-cam.z;if(F.lod>=0&&dx*dx+dz*dz>(F.lodD*(opts.detail||1))**2)return;}   // far tanks are the low-detail stand-in, turret included
 const c=Math.cos(hd),s=Math.sin(hd),sc=scale||1,px=tankPivot[0]*sc,pz=tankPivot[1]*sc,th=tankTurHd===null?hd:tankTurHd;
 unitList[UNIT.TANKTUR].push(x+c*px+s*pz-cam.x,y,z-s*px+c*pz-cam.z,th,pitch,tankTurRec,phase,sc);
}
// ---- AI pilots ----
const BOT_WORDS=['VIPER','HAWK','WOLF','RAVEN','COBRA','LANCER','SABRE','GHOST','ROOK','TALON','BISON','HUNTER','JACKAL','MAKO','ORCA','PIKE','ARROW','FALCON','STORM','ANVIL'];
let botT=2,botChatT=25,botSeq=1;
function botName(){botSeq++;return BOT_WORDS[Math.floor(Math.random()*BOT_WORDS.length)]+'-'+(10+Math.floor(Math.random()*89));}
function allBots(){const o=[];for(const f of foes)if(f.bot&&!f.dead)o.push({u:f,t:'ship',x:f.x,z:f.z,y:f.y,fid:f.fid});for(const k of armour)if(k.bot&&!k.dead)o.push({u:k,t:'tank',x:k.x,z:k.z,y:k.y,fid:k.fid});for(const a of air)if(a.bot&&!a.dead)o.push({u:a,t:'plane',x:a.x,z:a.z,y:a.y,fid:a.fid});return o;}
function botTick(dt){
 if(!player||!VS||game.state!=='playing'||tut.on)return;
 botT-=dt;if(botT>0)return;botT=4;
 const real=[...MMO.remotes.values()].filter(r=>r.p.vt).length,bots=allBots().filter(b=>Math.hypot(b.x-player.x,b.z-player.z)<9000);
 const wantF=Math.max(0,4-real*2),wantE=Math.max(0,Math.min(4,ladFoe().cap+1)-real);
 const nF=bots.filter(b=>sameBloc(b.fid,PF)).length,nE=bots.length-nF;
 if(CW.on){}else if(nF<wantF)spawnBot(true);else if(nE<wantE)spawnBot(false);
 // give idle bots somewhere to go: toward the nearest enemy they know of, or a point near you
 for(const b of bots){const u=b.u;if(!u.wpT||u.wpT<performance.now()){u.wpT=performance.now()+20000+Math.random()*20000;const a=Math.random()*6.28,r=600+Math.random()*1800;u.wp=[player.x+Math.cos(a)*r,player.z+Math.sin(a)*r];}}
}
function spawnBot(friendly){
 const fids=FACTIONS.filter(F=>friendly?sameBloc(F.id,PF):!sameBloc(F.id,PF)).map(F=>F.id),fid=fids[Math.floor(Math.random()*fids.length)];
 const r=Math.random(),want=r<.6?VS.type:r<.8?'plane':(T.height(player.x,player.z)<0?'ship':'tank');
 const a=Math.random()*6.28,R=friendly?1200+Math.random()*1500:3500+Math.random()*2000,cx=player.x+Math.cos(a)*R,cz=player.z+Math.sin(a)*R,cs=botName();
 let ok=false;
 if(want==='ship'){const q=seaSpot(cx,cz,1200);if(q){const f=addFoe(q[0],q[1],Math.random()*6.28,fid);f.bot={cs};f.v=f.K.speed*.6;ok=true;}}
 else if(want==='tank'){const q=landSpot(cx,cz,500);if(q){addArmourAt(q[0],q[1],fid,{hd:Math.random()*6.28,bot:{cs},friendly});ok=true;}}
 else{air.push({x:cx,z:cz,y:Math.max(T.height(cx,cz),0)+400+Math.random()*300,hd:Math.random()*6.28,pitch:0,roll:0,v:110+Math.random()*20,fid,hp:180,bot:{cs},tgt:null,tgtT:0,fireT:0,burst:0,breakT:0,dead:false,fall:0,ang:Math.random()*6});ok=true;}
 if(false)radioAdd(cs+' (AI)',['On station, joining you.','Moving up - who needs help?','Checking in. Weapons hot.','Coming to your position.'][Math.floor(Math.random()*4)],fid,false,false);
}
// a few lines of radio from the friendly AI, about what is actually around
function botChatter(dt){
 if(!player||game.state!=='playing')return;botChatT-=dt;if(botChatT>0)return;botChatT=30+Math.random()*35;
 const fr=allBots().filter(b=>sameBloc(b.fid,PF)&&Math.hypot(b.x-player.x,b.z-player.z)<7000);if(!fr.length)return;
 const b=fr[Math.floor(Math.random()*fr.length)],cs=b.u.bot.cs;
 const en=contacts.length?contacts[Math.floor(Math.random()*Math.min(3,contacts.length))]:null;
 const brg=en?Math.round(((Math.atan2(en.x-player.x,-(en.z-player.z))*57.3)+360)%360):0;
 const lines=[en?`Contact: ${en.label.toLowerCase()} ${fmtD(en.d)} out, bearing ${String(brg).padStart(3,'0')}.`:null,
  `Pushing toward ${terrName(facNearest(b.x,b.z))}. Cover me.`,
  en?`Engaging the ${en.label.toLowerCase()} - anyone close, help out.`:'Sector quiet here. Moving on.',
  'Watch the skies, their fighters are about.','Front line is holding. Keep the pressure on.'].filter(Boolean);
 /* v3.4: AI pilots no longer chat on the radio */
}
// call-sign tags over friendly AI pilots (same pool as the human pilots' tags)
function drawBotTags(n0){
 let n=n0;if(game.state!=='playing'||camMode!=='ship'||!player)return n;
 for(const b of allBots()){if(!sameBloc(b.fid,PF))continue;const D=Math.hypot(b.x-player.x,b.z-player.z);if(D>5000)continue;
  const s=toScreen(b.x,b.y+(b.t==='ship'?18:b.t==='tank'?6:4),b.z);if(!s)continue;
  let el=tagEls[n];if(!el){el=document.createElement('div');el.style.cssText='position:absolute;left:0;top:0;pointer-events:none;font:600 11px system-ui;letter-spacing:.08em;text-shadow:0 1px 2px #000;white-space:nowrap;z-index:5';ui.appendChild(el);tagEls.push(el);}
  el.style.display='block';el.style.color=FACTIONS[b.fid].css;el.style.opacity=.85;el.style.transform=`translate(${Math.round(s[0])}px,${Math.round(s[1])}px) translate(-50%,-120%)`;
  const t=b.u.bot.cs+' · AI · '+fmtD(D);if(el.textContent!==t)el.textContent=t;n++;}
 return n;
}
window.__bots={allBots,spawnBot};


// ---------- v2.8 deployment rides and real shells ----------
// Deploying to a front is a ride in, not a teleport:
//   TANK   rides in the hold of a big four-engined transport (C-130 style, the TRANSPORT model at 1.35x) from 5 km behind the line; over the
//          drop zone (or on SPACE) it rolls out of the ramp and comes down under a cargo parachute.
//   PLANE  takes off from the airfield (harbour runway) of your side nearest that front.
//   SHIP   is carried in the stern well dock of the MOTHERSHIP - a 340 m wave-piercing carrier, dark hull, cyan light strips - which runs in
//          at 50 m/s and floods its dock to launch you (on arrival or SPACE), then turns away and leaves.
// While a ride runs, rideStep() owns the player (stepPlayer defers to it), the camera pulls back, and the HUD shows the distance to go.
// SHELLS: every shell in flight is drawn as a real projectile (UNIT.PROJ: boat-tailed body, copper driving band, ogive nose, glowing
//   tracer base), sized by calibre and drawn a little larger with distance so it stays visible; the old glow stays as a short tracer.
UNIT.MOTHER=unitList.length;UNIT.PROJ=UNIT.MOTHER+1;unitList.push([],[]);UNIT_DRAW_R.push(22000,4000);
(function(){
 const M=mesh(),hull=[.16,.18,.21],deck=[.11,.12,.14],dark=[.06,.07,.08],glow=[.35,.95,1],trim=[.30,.33,.37],glass=[.05,.2,.28];
 const S=[[-170,25,27,13,-9],[-120,28,30,13,-11],[-40,30,31,13.5,-12],[40,29,30.5,14,-12],[100,22,26,15,-11],[140,12,18,16.5,-8],[172,1,3,18,-3]];
 const dY=shipHull(M,S,{top:hull,under:[.10,.11,.13],deck,bw:.3,n:24});
 // the flight deck and hangar over the after two thirds, open at the stern for the well dock
 prism(M,octo(-40,0,240,54,10),dY(-40),dY(-40)+12,hull,0,.98);
 box(M,-160,dY(-160)-12,0,26,22,44,dark);                                 // the well dock mouth
 box(M,-150,dY(-150)+11.5,0,10,.6,46,glow);                                // dock lights over the mouth
 for(const sg of [-1,1]){box(M,-40,dY(-40)+6,sg*27.4,236,.5,.3,glow);box(M,30,dY(30)-2,sg*30.6,250,.35,.3,glow);}   // light strips along both sides
 for(let x=-150;x<=80;x+=28)box(M,x,dY(-40)+12.05,0,14,.06,1.2,[.5,.55,.6]);     // flight deck centre-line markings
 // the angular island: a raked tower with a glass band and twin sensor masts
 prism(M,octo(55,-14,62,20,8),dY(55)+12,dY(55)+30,trim,0,.86);
 prism(M,octo(58,-14,44,15,6),dY(55)+30,dY(55)+40,trim,0,.8);
 box(M,58,dY(55)+33,-14,40,2.2,15.6,glass);
 for(const z of [-20,-8]){cylY(M,52,dY(55)+40,z,.7,22,6,trim);box(M,52,dY(55)+56,z,1,1,7,glow);}
 // a bow wedge and forward weapon blisters
 prism(M,octo(130,0,50,20,8),dY(130),dY(130)+6,hull,0,.7);
 for(const z of [-9,9]){cylY(M,120,dY(120)+6,z,3.4,2.4,10,trim);cylX(M,121,dY(120)+7.6,z,9,.5,6,dark);}
 addUnitKind(M);
 // v4.2 a shell, drawn properly: tracer glow out of the base, boat tail, two copper driving bands with a groove, a long olive body with
 // a yellow high-explosive band, the bourrelet, and a curved ogive nose with its fuze. 1 unit ~ a 1 m body at scale 1
 const P=mesh(),steel=[.44,.45,.43],olive=[.38,.41,.24],copper=[.78,.45,.22],yel=[.9,.74,.16],tr=[1,.78,.38],R0=.2;
 cyl(P,[-1.15,0,0],[-.6,0,0],.0,.13,10,[1,.62,.25],7,false);cyl(P,[-.6,0,0],[-.52,0,0],.13,.15,10,tr,7,true);      // the tracer burning out of the base
 cyl(P,[-.52,0,0],[-.32,0,0],.15,R0,14,steel,0,false);                                                              // boat tail
 cylX(P,-.32,0,0,.06,R0*1.06,14,copper);cylX(P,-.26,0,0,.03,R0*.98,14,[.3,.2,.12]);cylX(P,-.23,0,0,.06,R0*1.06,14,copper);   // driving bands
 cylX(P,-.17,0,0,.47,R0,14,olive);cylX(P,.3,0,0,.07,R0*1.01,14,yel);cylX(P,.37,0,0,.2,R0,14,olive);                  // body and its band
 cylX(P,.57,0,0,.05,R0*1.03,14,steel);                                                                               // bourrelet
 const og=[[.62,1],[.72,.96],[.82,.87],[.91,.73],[.99,.55],[1.06,.34],[1.1,.2]];
 for(let i=0;i<og.length-1;i++)cyl(P,[og[i][0],0,0],[og[i+1][0],0,0],R0*og[i][1],R0*og[i+1][1],14,i<2?olive:steel,0,false);   // curved ogive nose
 cyl(P,[1.1,0,0],[1.16,0,0],R0*.2,R0*.08,8,[.7,.62,.3],0,true);                                                      // fuze
 addUnitKind(P);
 // v3.7 a tracer streak: one smooth glowing taper along the line of flight, in place of a string of separate glow beads
 UNIT.STREAK=unitList.length;unitList.push([]);UNIT_DRAW_R.push(9000);
 const Q=mesh();cyl(Q,[-30,0,0],[-6,0,0],.02,.16,6,[1,.62,.25],7,false);cyl(Q,[-6,0,0],[0,0,0],.16,.26,6,[1,.86,.5],7,false);addUnitKind(Q);
 extraDrawKinds.push(UNIT.MOTHER,UNIT.PROJ,UNIT.STREAK);
})();
// ---- rides ----
var ride=null;
const RIDE_PLANE_K=1.15;
function waterFrac(ax,az,bx,bz){const L=Math.hypot(bx-ax,bz-az),n=Math.ceil(L/120);let w=0;for(let k=0;k<=n;k++){const t=k/n*(1-Math.min(.5,250/L));if(T.height(ax+(bx-ax)*t,az+(bz-az)*t)<-5)w++;}return w/(n+1);}   // the last 250 m may be shallow
const waterLine=(ax,az,bx,bz)=>waterFrac(ax,az,bx,bz)>=1;
// a tank's ride: from 5 km behind the drop zone, inbound at 110 m/s
function startAirRide(px,pz,nx,nz){
 const sx=px+nx*5000,sz=pz+nz*5000,hd=headingOf(px-sx,pz-sz);
 ride={kind:'air',x:sx,z:sz,y:Math.max(T.height(sx,sz),T.height(px,pz),0)+260,hd,v:110,tx:px,tz:pz,phase:'fly',t:0,dist0:orbit.dist};
 orbit.dist=Math.max(orbit.dist,95);rideHold();
 toast('Aboard the transport. You drop over the front - or press SPACE to jump now.',5000);
}
// a ship's ride: in the mothership's well dock, on a clear line of water ending off the front
function startSeaRide(px,pz,nx,nz){
 let s=null;
 for(const back of [3500,2600,1800,1200,800])for(const sw of [0,.4,-.4,.8,-.8,1.2,-1.2,1.6,-1.6,2.2,-2.2,3.14]){const c=Math.cos(sw),sn=Math.sin(sw),dx=nx*c-nz*sn,dz=nx*sn+nz*c,sx=px+dx*back,sz=pz+dz*back;
  if(!s&&T.height(sx,sz)<-15&&waterLine(sx,sz,px,pz))s=[sx,sz];}
 if(!s){let bf=.6;for(const back of [1500,1000,700])for(let a=0;a<6.28;a+=.4){const sx=px+Math.cos(a)*back,sz=pz+Math.sin(a)*back;if(T.height(sx,sz)>-15)continue;const f=waterFrac(sx,sz,px,pz);if(f>bf){bf=f;s=[sx,sz];}}}   // a short run in, mostly over water
 if(!s)return false;
 const k=Math.max(1,(VS.length+90)/260);
 ride={kind:'sea',x:s[0],z:s[1],y:0,hd:headingOf(px-s[0],pz-s[1]),v:50,tx:px,tz:pz,phase:'fly',t:0,k,dist0:orbit.dist};
 orbit.dist=Math.max(orbit.dist,420*k);rideHold();
 toast('Aboard the mothership, in the well dock. You launch off the front - or press SPACE to launch now.',5500);
 return true;
}
function rideHold(){player.v=0;helm.throttle=0;game.port=null;}
function rideRelease(){
 if(!ride)return;
 const c=Math.cos(ride.hd),s=-Math.sin(ride.hd);
 if(ride.kind==='air'){player.gnd=false;ride.phase='fall';ride.fx=player.x;ride.fz=player.z;ride.vy=-2;ride.vh=ride.v*.4;ride.chute=0;ride.ft=0;toast('Tank away - parachute deploying',2500);}
 else{ride.phase='leave';player.x=ride.x-c*(170*ride.k+VS.length*.55);player.z=ride.z-s*(170*ride.k+VS.length*.55);player.hd=ride.hd;player.v=Math.min(VS.cruise||14,16);helm.throttle=.75;
  orbit.dist=ride.dist0;toast('Launched from the mothership. She turns for home - the front is yours.',4000);}
}
// runs instead of the player's physics while a ride is on. Returns true while it owns the player.
function rideStep(dt){
 const R=ride;if(!R)return false;
 R.t+=dt;const c=Math.cos(R.hd),s=-Math.sin(R.hd);
 if(R.phase==='fly'||R.phase==='leave'||R.phase==='fall'){                          // the carrier itself keeps moving
  if(R.phase==='leave'||R.phase==='fall'){R.lt=(R.lt||0)+dt;if(R.lt>3)R.hd+=dt*.08;}
  R.x+=Math.cos(R.hd)*R.v*dt;R.z-=Math.sin(R.hd)*R.v*dt;
  if(R.kind==='air'){const fl=Math.max(T.height(R.x,R.z),0)+(R.phase==='fly'?240:520);R.y+=clamp(fl-R.y,-15,15)*dt;}
 }
 if(R.phase==='fly'){
  const D=Math.hypot(R.tx-R.x,R.tz-R.z);
  if(R.kind==='air'){player.x=R.x;player.z=R.z;player.y=R.y-3;player.hd=R.hd;player.pitch=0;player.roll=0;}
  else{player.x=R.x-c*(150*R.k-VS.length*.5);player.z=R.z-s*(150*R.k-VS.length*.5);player.y=0;player.hd=R.hd;player.pitch=0;player.roll=0;}
  player.v=R.v;
  if(D<140)rideRelease();
  return true;
 }
 if(R.phase==='fall'){
  R.ft+=dt;if(R.ft>1.2)R.chute=Math.min(1,R.chute+dt*.9);
  R.vy+=(-9.81+(R.chute?(-R.vy-12)*2.4*R.chute+9.81*R.chute:0))*dt;   // ~12 m/s under the canopyR.vh*=Math.exp(-(.3+R.chute)*dt);
  R.fx+=c*R.vh*dt;R.fz+=s*R.vh*dt;
  player.x=R.fx;player.z=R.fz;player.y+=R.vy*dt;player.hd=R.hd;player.v=0;
  const gh=Math.max(T.height(player.x,player.z),0);
  if(player.y<=gh+.3){player.y=gh;player.gnd=true;groundPose(player,1);orbit.dist=R.dist0;
   for(let k=0;k<6;k++)shellFx.push({kind:'dust',x:player.x+(Math.random()-.5)*10,y:gh,z:player.z+(Math.random()-.5)*10,age:0,life:2.2,size:10});
   R.phase='done';R.doneT=0;toast('Down safe. Tank, roll out!',2500);return false;}
  return true;
 }
 // after the drop or the launch the carrier flies or sails on for a while, then is gone
 R.doneT=(R.doneT||0)+dt;if(R.doneT>40||Math.hypot(R.x-player.x,R.z-player.z)>15000)ride=null;
 return false;
}
function emitRide(){
 const R=ride;if(!R)return;
 if(R.kind==='air'){emit(UNIT.TRANSPORT,R.x,R.y,R.z,R.hd,0,0,PF+1,RIDE_PLANE_K);
  if(R.phase==='fall'&&R.chute>0)emit(UNIT.CHUTE,player.x,player.y,player.z,R.hd+R.t*.2,Math.sin(R.t*1.3)*.05,0,0,R.chute*1.15);}
 else{emit(UNIT.MOTHER,R.x,0,R.z,R.hd,0,0,PF+1,R.k);}
}
function rideHud(){
 const R=ride;if(!R||R.phase!=='fly')return '';
 const D=Math.hypot(R.tx-R.x,R.tz-R.z);
 return `<br><span style="color:#ffd36b">${R.kind==='air'?'IN THE TRANSPORT':'IN THE MOTHERSHIP'} &middot; ${fmtD(D).toUpperCase()} TO GO &middot; SPACE TO ${R.kind==='air'?'JUMP':'LAUNCH'} NOW</span>`;
}
addEventListener('keydown',e=>{if(e.code==='Space'&&ride&&ride.phase==='fly'&&game.state==='playing'){e.preventDefault();rideRelease();}});
// the plane's way in: the airfield of your side nearest the front
function airfieldNear(x,z){
 let best=null,bd=1e18;
 for(const R of [12000,30000,60000]){for(const p of T.portsIn(x-R,z-R,x+R,z+R)){if(facRel(portFaction(p))<0)continue;const d=Math.hypot(p.x-x,p.z-z);if(d<bd){bd=d;best=p;}}if(best)break;}
 return best;
}
// shells as real projectiles
function shellScale(s,d){return Math.max(.35,s.size*.9)*(1+d*.0025);}
window.__ride={get ride(){return ride;},rideRelease,startAirRide,startSeaRide,airfieldNear};

// ---------- v3.0 the salvage war: harvest, bank, climb the service tree; faction doctrines; supply routes; the weekly war ----------
// The loop: every battle leaves salvage. Break salvage sites (wrecks at sea, supply dumps on land, cargo balloons in the air) and
// destroy enemies; the salvage drops as glowing crates you scoop up (cargo, capped by your vehicle's tier). Carry it home: banking
// happens at any friendly base (dock / land / enter) or outpost. Die with a hold full of it and it spills where you fell.
// Banked salvage buys nodes on the SERVICE TREE (land, sea, air: one of two at each tier, new vehicles at the top) and REFITS
// (armour, engine, reload, magazines, cargo per domain). None of it ever resets.
// Every pilot's banked salvage this week also fills their faction's pool; at four thresholds the faction picks one of two DOCTRINES
// (votes on the pilot cards; offline, your vote decides). Territories carry a resource (steelworks, shipyard, airfield, oil field):
// the more your bloc holds, the more each kind pays - those are the SUPPLY ROUTES. The war map, doctrines and pools reset every
// Monday (00:00 UTC); pilots keep everything they own.
// Saved in irontide.salvage (and the cloud save); the card carries sw (salvage this week), sk (its week) and dv (doctrine votes).
var SALV=null;
var boot=null;
const SALV_KEY='irontide.salvage';
const DOM_OF={ship:'sea',tank:'land',plane:'air'},TYPE_OF={sea:'ship',land:'tank',air:'plane'};
const DOM_LABEL={land:'LAND',sea:'SEA',air:'AIR'},DOM_COL={land:'#c9b26b',sea:'#58c6ff',air:'#b7a6ff'};
const salvWeek=()=>Math.floor((Date.now()/864e5+3)/7);
const salvWeekLeft=()=>((salvWeek()+1)*7-3)*864e5-Date.now();
function salvLoad(){
 if(SALV)return SALV;
 SALV={bank:0,total:0,cargo:0,own:{},refit:{land:{},sea:{},air:{}},dv:'----',wk:salvWeek(),sw:0,pick:{},seen:0};
 try{const s=JSON.parse(store.get(SALV_KEY));if(s&&typeof s==='object'){Object.assign(SALV,s);SALV.refit=Object.assign({land:{},sea:{},air:{}},s.refit||{});SALV.own=s.own||{};}}catch(e){}
 for(const d of ['land','sea','air'])SALV.own[d[0].toUpperCase()+'1']=1;           // the first vehicle of every tree is yours
 // v3.8 the Service Tree was rebuilt: old vehicles are refunded in full as banked salvage (their ids now mean different vehicles)
 if(SALV.tv!==38){let refund=0;for(const id in SALV.own){const m=/^[SLA]([1-6])/.exec(id);if(m&&+m[1]>1)refund+=[0,150,400,900,3000,9000][+m[1]-1];}
  SALV.own={};SALV.pick={};SALV.bank=(+SALV.bank||0)+refund;SALV.tv=38;SALV.refund=refund;}
 try{for(const d of ['land','sea','air'])for(const n of TREE[d])if(n.t===1)SALV.own[n.id]=1;}catch(e){SALV.own.S1b=SALV.own.S1c=1;}   // every tier 1 start is yours
 if(SALV.wk!==salvWeek()){SALV.wk=salvWeek();SALV.sw=0;SALV.dv='----';}
 SALV.cargo=Math.max(0,+SALV.cargo||0);
 return SALV;
}
function salvSave(){store.set(SALV_KEY,JSON.stringify(salvLoad()));}

