const NODE=new Map();for(const d in TREE)for(const n of TREE[d]){n.dom=d;n.type=TYPE_OF[d];NODE.set(n.id,n);}
for(const d in TREE)for(const n of TREE[d])n.parents=TREE[d].filter(q=>(q.next||[]).includes(n.id)).map(q=>q.id);
const nodeOwned=id=>OWNER||!!salvLoad().own[id];
const nodeOpen=n=>n.t===1||n.parents.some(nodeOwned);
// the garage rows of the new vehicles are locked until their node is owned
function salvGate(t,key,i){const L=(NEW_OPT[t]||{})[key];if(!L||!L.includes(i))return null;for(const n of TREE[DOM_OF[t]])if(n.p[key]===i)return n;return null;}
function salvOptOk(t,key,i){if(TREE[DOM_OF[t]].some(n=>n.custom&&nodeOwned(n.id)))return true;const n=salvGate(t,key,i);return !n||nodeOwned(n.id);}   // v3.8 owning 'Make your own' unlocks every part of that branch
// the build a node stands for
function nodeSpec(n){
 const s=n.type==='ship'?shipDefault():defaultSpec(n.type);
 for(const k in n.p)if(s.p[k]!==undefined)s.p[k]=n.p[k];
 if(salvLoad().pick[n.dom+'paint']!==undefined)s.p.paint=salvLoad().pick[n.dom+'paint'];
 s.node=n.id;return s;
}
// the tier a build counts as (sets its cargo hold): its node's, or the lowest node using the same hull
function specTier(spec){
 if(spec&&spec.node&&NODE.has(spec.node))return NODE.get(spec.node).t;
 const d=DOM_OF[spec.type],k=LAD_HKEY[spec.type],hi=spec.p[k];let t=7;
 for(const n of TREE[d])if(n.p[k]===hi)t=Math.min(t,n.t);
 return t===7&&!TREE[d].some(n=>n.p[k]===hi)?3:t;
}
