let docCache={t:-1,pool:0,act:[]};
function factionPool(f){
 const wk=salvWeek();let p=0;
 if(MMO&&MMO.on)for(const c of MMO.pilots)if((c.fid|0)===f&&c.sk===wk&&c.id!==MMO.uid)p+=+c.sw||0;
 if(f===PF)p+=salvLoad().sw;
 const hrs=Math.max(0,(Date.now()-(salvWeek()*7-3)*864e5)/36e5);
 return Math.round(p+hrs*95*(1+.1*f%2));                                       // the AI pilots of every side harvest too
}
function docVotes(f,tier){
 const v={A:0,B:0};const wk=salvWeek();
 if(MMO&&MMO.on)for(const c of MMO.pilots)if((c.fid|0)===f&&c.sk===wk&&c.id!==MMO.uid&&typeof c.dv==='string'){const x=c.dv[tier];if(x==='A'||x==='B')v[x]++;}
 if(f===PF){const x=salvLoad().dv[tier];if(x==='A'||x==='B')v[x]++;}
 return v;
}
// the doctrines in force for your side: tiers reached, each decided by the majority (ties go to the first vote cast: yours offline)
