// ---------- supply routes: what each territory produces ----------
const RES=[{id:'steel',name:'Steelworks',dom:'land',col:'#c9b26b',d:'land salvage'},{id:'yard',name:'Shipyard',dom:'sea',col:'#58c6ff',d:'sea salvage'},
 {id:'strip',name:'Airfield',dom:'air',col:'#b7a6ff',d:'air salvage'},{id:'oil',name:'Oil field',dom:'all',col:'#ff9a4a',d:'speed for everything'}];
const resOf=s=>RES[Math.floor(hsh(s.i,s.j,4101)*4)];
let routeCache={t:-1e9,held:{steel:0,yard:0,strip:0,oil:0},near:{}};
function supplyRoutes(){
 const now=performance.now();if(now-routeCache.t<15000)return routeCache;
 const held={steel:0,yard:0,strip:0,oil:0},near={steel:[],yard:[],strip:[],oil:[]},n=Math.ceil(SEASON_R/FAC_CELL),px=player?player.x:0,pz=player?player.z:0;
 for(let j=-n;j<=n;j++)for(let i=-n;i<=n;i++){const s=facSeed(i,j);if(Math.hypot(s.x,s.z)>SEASON_R)continue;const r=resOf(s),f=facOfSeed(s);
  if(sameBloc(f,PF))held[r.id]++;else near[r.id].push({s,f,d:Math.hypot(s.x-px,s.z-pz)});}
 for(const k in near)near[k]=near[k].sort((a,b)=>a.d-b.d).slice(0,3);
 routeCache={t:now,held,near};return routeCache;
}
const routeBonus=id=>Math.min(id==='oil'?.15:.3,(supplyRoutes().held[id]||0)*(id==='oil'?.01:.015));
// ---------- every multiplier in one place ----------
function salvMul(kind,dom){
 const d=dom||(VS?DOM_OF[VS.type]:'sea');let m=1;
 if(kind==='hp'){m*=1+.06*refitLvl(d,'armour');if(docOn('spear')&&d==='land')m*=1.15;if(docOn('blue')&&d==='sea')m*=1.15;if(docOn('sky')&&d==='air')m*=1.15;}
 if(kind==='speed'){m*=1+.04*refitLvl(d,'engine');if(docOn('spear')&&d==='land')m*=1.08;if(docOn('blue')&&d==='sea')m*=1.08;if(docOn('sky')&&d==='air')m*=1.1;if(docOn('blitz'))m*=1.06;m*=1+routeBonus('oil');}
 if(kind==='reload'){m*=Math.pow(.94,refitLvl(d,'reload'));if(docOn('guns'))m*=.85;}
 if(kind==='mags')m*=1+.12*refitLvl(d,'mags');
 if(kind==='cargo'){m*=1+.15*refitLvl(d,'cargo');if(docOn('blitz'))m*=1.25;}
 if(kind==='salv'){if(docOn('salv'))m*=1.25;m*=1+routeBonus(d==='land'?'steel':d==='sea'?'yard':'strip');}
 if(kind==='xp'&&docOn('bonds'))m*=1.2;
 return m;
}
// stats: refits, doctrines and the node's perk on top of the garage numbers (garage previews show them too)
for(const t of ['ship','tank','plane']){const base=STATS[t];STATS[t]=spec=>{
 const st=base(spec),d=DOM_OF[t],pk=spec.node&&NODE.has(spec.node)?NODE.get(spec.node).perk||{}:{};
 const hp=salvMul('hp',d)*(pk.hp||1),sp=salvMul('speed',d)*(pk.speed||1);
 st.hp*=hp;st.cruise*=sp;st.flank*=sp;if(st.stall)st.stall=st.stall;st.perk=pk;st.node=spec.node||null;return st;};}
function salvCargoCap(){if(!vehicle)return 300;const pk=vehicle.node&&NODE.has(vehicle.node)?NODE.get(vehicle.node):null;return Math.round(TIER_CARGO[specTier(vehicle)-1]*salvMul('cargo',DOM_OF[vehicle.type]));}
function salvReloadMul(){const pk=vehicle&&vehicle.node&&NODE.has(vehicle.node)?NODE.get(vehicle.node).perk||{}:{};return salvMul('reload')*(pk.reload||1);}

