// ---------- salvage sites: the "asteroids" of the war ----------
const SITE_CELL=1800,SITE_RESPAWN=8*60e3;
const siteBroken=new Map(),siteHp=new Map();
function siteAt(i,j){
 const h=hsh(i,j,4201);if(h>.5)return null;
 const x=(i+.2+.6*hsh(i,j,4202))*SITE_CELL,z=(j+.2+.6*hsh(i,j,4203))*SITE_CELL,gh=T.height(x,z),key=i+','+j;
 let kind;
 if(hsh(i,j,4204)<.3)kind='air';
 else if(gh<-6)kind='sea';
 else if(gh>2&&gh<160&&!(T.pave&&T.pave(x,z)>.05))kind='land';
 else return null;
 const y=kind==='air'?Math.max(gh,0)+260+hsh(i,j,4205)*340:kind==='sea'?0:gh;
 const S={key,i,j,kind,x,y,z,hd:hsh(i,j,4206)*6.28,hp0:kind==='sea'?320:kind==='land'?220:70,r:kind==='sea'?30:kind==='land'?14:10,h:kind==='sea'?12:kind==='land'?9:24};
 S.hp=siteHp.has(key)?siteHp.get(key):S.hp0;return S;
}
let sitesNear=[],siteT=0;
function scanSites(){
 if(!player)return;sitesNear=bootSites.filter(q=>q.hp>0);const ci=Math.floor(player.x/SITE_CELL),cj=Math.floor(player.z/SITE_CELL),now=Date.now();
 for(let j=cj-3;j<=cj+3;j++)for(let i=ci-3;i<=ci+3;i++){const k=i+','+j,b=siteBroken.get(k);if(b&&now-b<SITE_RESPAWN)continue;if(b){siteBroken.delete(k);siteHp.delete(k);}const s=siteAt(i,j);if(s)sitesNear.push(s);}
}
function siteDamage(s,dmg,x,y,z){
 s.hp-=dmg;if(!s.boot)siteHp.set(s.key,s.hp);
 shellFx.push({kind:'blast',x,y,z,age:0,life:.5,size:5+Math.min(dmg,150)*.05});
 if(s.hp>0)return;
 if(!s.boot)siteBroken.set(s.key,Date.now());siteHp.delete(s.key);sitesNear=sitesNear.filter(q=>q!==s);
 const n=s.kind==='sea'?6:s.kind==='land'?5:3,each=s.kind==='sea'?26:s.kind==='land'?22:30;
 salvAuto(Math.round(n*each*(.8+Math.random()*.4)),s.x,s.kind==='air'?s.y-2:s.y+2,s.z,s.kind==='air');
 for(let k=0;k<4;k++)shellFx.push({kind:'blast',x:s.x+(Math.random()-.5)*s.r,y:s.y+3+Math.random()*s.h*.5,z:s.z+(Math.random()-.5)*s.r,age:-k*.12,life:.8,size:10+Math.random()*8});
}
// a player round passing through a site (checked before the ground, so rounds aimed at a wreck's waterline still count)
function salvShell(s){
 for(const q of sitesNear){const dx=s.x-q.x,dz=s.z-q.z;if(Math.abs(dx)>q.r||Math.abs(dz)>q.r)continue;if(dx*dx+dz*dz>q.r*q.r||s.y<q.y-4||s.y>q.y+q.h)continue;
  SALV_HIT.x=s.x;SALV_HIT.y=s.y;SALV_HIT.z=s.z;SALV_HIT.t=performance.now();siteDamage(q,s.dmg,s.x,s.y,s.z);hitMark(s.dmg);return true;}
 return false;
}
function salvArea(x,y,z,r,dmg){for(const q of sitesNear.slice()){const d=Math.hypot(q.x-x,(q.y+q.h*.4)-y,q.z-z)-q.r;if(d<r)siteDamage(q,dmg*(1-.6*Math.max(0,d)/r),x,y,z);}}
// ---------- crates ----------
const crates=[];const SALV_HIT={x:0,y:0,z:0,t:-1e9};
function dropCrate(x,y,z,amt,air){
 const gh=T.height(x,z);
 crates.push({x,y,z,amt,vy:air?-6:0,fall:!!air||y>Math.max(gh,0)+3,age:0,ph:Math.random()*6,hd:Math.random()*6.28});
 if(crates.length>160)crates.shift();
}
// kills drop salvage where the last of your rounds struck (or where you are aiming)
const KILL_SALV={ship:70,fort:60,armour:38,air:45,convoy:55,infantry:3};
function salvKill(kind){
 const a=KILL_SALV[kind];if(!a||!player)return;
 let x=SALV_HIT.x,y=SALV_HIT.y,z=SALV_HIT.z;
 if(performance.now()-SALV_HIT.t>4000){const ap=typeof aimPoint==='function'?aimPoint():null;if(ap&&ap[0]!==undefined){x=ap[0];y=ap[1];z=ap[2];}else{x=player.x;y=player.y;z=player.z;}}
 salvAuto(Math.round(a*(.8+Math.random()*.4)),x,y+2,z,kind==='air');
}
// v3.1: what you destroy goes straight into the hold; only what will not fit spills out as crates
function salvAuto(a,x,y,z,air){
 const S=salvLoad();
 if(!player||!VS||game.hull<=0){dropCrate(x,y,z,a,air);return;}
 const cap=salvCargoCap(),gain=Math.round(a*salvMul('salv')),fit=Math.max(0,Math.min(gain,cap-S.cargo));
 S.cargo+=fit;salvHudDirty=true;salvPickAmt+=fit;salvPickT=1.2;
 if(fit<gain){const left=Math.round((gain-fit)/salvMul('salv'));if(left>0)dropCrate(x,y,z,left,air);const t=performance.now()/1000;if(t-salvFullT>6){salvFullT=t;toast('CARGO FULL - bank it at a friendly base or outpost. The rest is floating where it fell.',3600);}}
 if(fit>0){const p=toScreen(x,y,z);if(p)salvPop(p,'+'+fit);}
}
// a short-lived "+N" that rises from where the salvage came from
function salvPop(p,txt){const e=document.createElement('div');e.className='spop';e.textContent=txt;e.style.left=p[0]+'px';e.style.top=p[1]+'px';salvTags.appendChild(e);setTimeout(()=>e.remove(),1300);}
function salvMarkHit(s){SALV_HIT.x=s.x;SALV_HIT.y=s.y;SALV_HIT.z=s.z;SALV_HIT.t=performance.now();}
// ---------- picking up, banking, spilling ----------
let salvHudDirty=true,salvFullT=0,salvLastDead=false,salvPickT=0,salvPickAmt=0;
function pickRadius(){if(!VS)return 0;return VS.type==='ship'?Math.max(28,VS.length*.45):VS.type==='tank'?16:150;}
function salvTick(t,dt){
 const S=salvLoad();
 if((salvWkT-=dt)<=0){salvWkT=60;salvWeeklyLocal();}
 if((siteT-=dt)<=0){siteT=2;scanSites();}
 // crates fall, bob and expire after 6 minutes
 for(let i=crates.length-1;i>=0;i--){const c=crates[i];c.age+=dt;if(c.age>360){crates.splice(i,1);continue;}
  const gh=T.height(c.x,c.z),floor=gh<0?0:gh;
  if(c.fall){c.vy=Math.max(c.vy-9.81*dt,-7);c.y+=c.vy*dt;if(c.y<=floor+.2){c.y=floor+.2;c.fall=false;if(gh<0)shellFx.push({kind:'splash',x:c.x,y:0,z:c.z,age:0,life:1,size:3});}}
  else c.y=gh<0?(typeof waveH==='function'?waveH(c.x,c.z,t)*.6:0)+.1:floor+.2;}
 if(!player||game.state!=='playing'||(typeof ride!=='undefined'&&ride))return;
 const cap=salvCargoCap();
 // pick up
 if(game.hull>0){const R=pickRadius(),air=VS.type==='plane';
  for(let i=crates.length-1;i>=0;i--){const c=crates[i],dx=c.x-player.x,dz=c.z-player.z;if(dx*dx+dz*dz>R*R)continue;if(air?player.y-c.y>280||c.y-player.y>60:Math.abs(player.y-c.y)>12)continue;
   if(S.cargo>=cap){if(performance.now()/1000-salvFullT>6){salvFullT=performance.now()/1000;toast('CARGO FULL - bank it at a friendly base or outpost',3200);}break;}
   const take=Math.min(c.amt,Math.ceil((cap-S.cargo)/salvMul('salv'))),gain=Math.min(cap-S.cargo,Math.round(take*salvMul('salv')));S.cargo+=gain;c.amt-=take;salvPickAmt+=gain;salvPickT=1.6;
   if(c.amt<=0)crates.splice(i,1);salvHudDirty=true;}
  if(salvPickT>0&&(salvPickT-=dt)<=0){if(salvPickAmt)careerFeed={text:'+'+salvPickAmt+' SALVAGE  scooped up',t:3};salvPickAmt=0;salvSave();}
 }
 // wrecked with a full hold: it spills where you fell (and every pilot nearby sees it)
 const dead=game.hull<=0;
 if(dead&&!salvLastDead&&S.cargo>0){const a=S.cargo,n=Math.min(6,1+Math.floor(a/60));
  for(let k=0;k<n;k++)dropCrate(player.x+(Math.random()-.5)*20,player.y+3,player.z+(Math.random()-.5)*20,Math.round(a/n),VS.type==='plane');
  if(MMO&&MMO.room)MMO.room.emit('drop',{x:Math.round(player.x),y:Math.round(player.y),z:Math.round(player.z),a,n,air:VS.type==='plane'}).catch(()=>{});
  toast('Your cargo spilled - '+a+' salvage lies where you fell',4500);S.cargo=0;salvSave();salvHudDirty=true;}
 salvLastDead=dead;
 salvHud(cap);fieldTick(dt);bootTick();if(typeof t6Tick==='function')t6Tick(dt);
}
function salvBank(where){
 const S=salvLoad();if(S.cargo<=0)return;
 const a=Math.round(S.cargo*(where==='outpost'&&docOn('fort')?1.15:1));
 S.bank+=a;S.total+=a;if(boot&&!boot.done){boot.banked=1;bootSave();}if(S.wk!==salvWeek()){S.wk=salvWeek();S.sw=0;S.dv='----';}S.sw+=a;S.cargo=0;salvSave();salvHudDirty=true;docCache.t=-1;
 const on=opts.banners;opts.banners=true;showBanner('SALVAGE BANKED','+'+a,'BANK '+S.bank.toLocaleString()+' · SPEND IT IN THE SERVICE TREE (B)','#f2b84b');opts.banners=on;
 news(`<b style="color:#f2b84b">+${a} salvage banked</b> &middot; ${FACTIONS[PF].tag} pool ${factionPool(PF).toLocaleString()}`,12000);
 if(typeof cloudPush==='function')setTimeout(()=>cloudPush(),500);
}
// remote spills arrive here
function salvRemoteDrop(d){if(!d||typeof d.x!=='number')return;const n=Math.min(6,d.n|0||1);for(let k=0;k<n;k++)dropCrate(d.x+(Math.random()-.5)*20,(d.y||0)+3,d.z+(Math.random()-.5)*20,Math.round((d.a|0)/n),!!d.air);}
function salvCard(){const S=salvLoad();return {sw:S.wk===salvWeek()?Math.round(S.sw):0,sk:salvWeek(),dv:S.dv,sal:Math.round(S.total)};}
// ---------- drawing ----------
function emitSalv(t){
 for(const c of crates){if(Math.abs(c.x-cam.x)>2600||Math.abs(c.z-cam.z)>2600)continue;
  emit(UNIT.SALV,c.x,c.y,c.z,c.hd+t*.4,0,0,.5+.5*Math.sin(t*4+c.ph)>.5?.37:.62,1.3);
  if(c.fall&&UNIT.CHUTE!==undefined)emit(UNIT.CHUTE,c.x,c.y+2,c.z,c.hd,0,0,0,.18);}
 for(const s of sitesNear){const k=s.kind==='sea'?UNIT.WRECK:s.kind==='land'?UNIT.DUMP:UNIT.BALLOON;
  const y=s.kind==='sea'?(typeof waveH==='function'?waveH(s.x,s.z,t)*.3:0)-.4:s.kind==='air'?s.y+Math.sin(t*.5+s.i)*1.5:s.y;
  emit(k,s.x,y,s.z,s.hd+(s.kind==='air'?t*.05:0),0,0,(Math.sin(t*3+s.j)>0?.3:.7),1);}
}
// ---------- HUD: cargo row in the gauges, site and crate markers ----------
const salvTags=document.createElement('div');salvTags.id='salvtags';ui.appendChild(salvTags);
let salvTagPool=[];
function salvHud(cap){
 const S=salvLoad(),row=$('g-cargo');
 if(row&&salvHudDirty){salvHudDirty=false;const f=Math.min(1,S.cargo/cap);row.querySelector('i').style.width=(f*100)+'%';row.querySelector('i').style.background=f>=1?'var(--bad)':'#f2b84b';$('g-cargot').textContent=S.cargo+'/'+cap;}
 if(row&&row._cap!==cap){row._cap=cap;salvHudDirty=true;}
 // markers: salvage sites within 2.5 km, crates within 900 m
 const list=[];
 for(const s of sitesNear){const d=Math.hypot(s.x-player.x,s.z-player.z);if(d>2500)continue;list.push({x:s.x,y:s.y+s.h+4,z:s.z,site:s,d});}
 for(const c of crates){const d=Math.hypot(c.x-player.x,c.z-player.z);if(d>900)continue;list.push({x:c.x,y:c.y+3,z:c.z,crate:c,d});}
 list.sort((a,b)=>a.d-b.d);list.length=Math.min(list.length,14);
 while(salvTagPool.length<list.length){const e=document.createElement('div');e.className='stag';salvTags.appendChild(e);salvTagPool.push(e);}
 salvTagPool.forEach((e,i)=>{const L=list[i],p=L&&toScreen(L.x,L.y,L.z);if(!p){if(e._v){e.style.display='none';e._v=0;}return;}
  if(!e._v){e.style.display='block';e._v=1;}
  e.style.transform=`translate(${p[0]|0}px,${p[1]|0}px)`;
  const h=L.site?`<i class="sd"></i><span>${L.site.kind==='sea'?'WRECK':L.site.kind==='land'?'SUPPLY DUMP':'CARGO BALLOON'} &middot; ${fmtD(L.d)}</span><b style="width:${Math.max(0,L.site.hp/L.site.hp0*100)|0}%"></b>`:`<i class="sc"></i><span>+${L.crate.amt}</span>`;
  if(e._h!==h){e._h=h;e.innerHTML=h;e.classList.toggle('crate',!L.site);}});
}

// ---------- the Service Tree screen (K, the menu's DEPLOY, the pause menu) ----------
const hg=document.createElement('div');hg.id='hangar';hg.className='screen';ui.appendChild(hg);
let hgDom='sea',hgSel=null,hgFrom='menu';
var hgReturn=null;
function openHangar(from){
 hgFrom=from||'menu';if(document.exitPointerLock)document.exitPointerLock();
 if(VS&&!hgSel)hgDom=DOM_OF[VS.type];
 if(hgFrom==='play'&&game.state==='playing')setState('paused');
 if(hgFrom==='play')showScreen(null);
 hg.classList.add('on');hg.style.display='block';renderHangar();
}
function closeHangar(resume){hg.classList.remove('on');hg.style.display='none';if(resume&&hgFrom==='play'&&game.state==='paused'){setState('playing');lockPointer();}}
window.addEventListener('keydown',e=>{
 if(e.code!=='KeyB'||e.repeat||(e.target&&/INPUT|TEXTAREA/.test(e.target.tagName)))return;
 if(hg.classList.contains('on')){closeHangar(true);if(hgFrom==='menu')setState('menu');else if(hgFrom==='port'&&game.port){openPort();e.preventDefault();return;}else if(game.state==='paused')showScreen('pause');e.preventDefault();return;}
 if(game.state==='playing'){openHangar('play');e.preventDefault();}
});
let salvWkT=0;
function nodeState(n){return nodeOwned(n.id)?'own':nodeOpen(n)?'open':'lock';}
function renderHangar(){
 const S=salvLoad(),nodes=TREE[hgDom],tiers=[1,2,3,4,5,6,7];
 if(S.refund){toast('The Service Tree is new! Your old vehicles were refunded: +'+S.refund.toLocaleString()+' salvage banked',7000);S.refund=0;salvSave();}
 if(!hgSel||NODE.get(hgSel).dom!==hgDom)hgSel=(S.pick[hgDom]&&NODE.has(S.pick[hgDom]))?S.pick[hgDom]:nodes[0].id;
 const sel=NODE.get(hgSel),st=vehicleStats(nodeSpec(sel)),ns=nodeState(sel),dc=doctrines();
 const W=1050,H=550,colW=W/7,pos={};
 for(const t of tiers){const row=nodes.filter(n=>n.t===t);row.forEach((n,k)=>{pos[n.id]=[colW*(t-.5),H*(k+1)/(row.length+1)];});}
 let lines='';for(const n of nodes)for(const c of (n.next||[])){const a=pos[n.id],b=pos[c],on=nodeOwned(n.id)&&nodeOwned(c),av=nodeOwned(n.id)&&!nodeOwned(c);
  lines+=`<path d="M${a[0]+70},${a[1]} C${a[0]+colW/2},${a[1]} ${b[0]-colW/2},${b[1]} ${b[0]-70},${b[1]}" class="${on?'own':av?'av':''}"/>`;}
 const card=n=>{const s=nodeState(n),p=pos[n.id],cost=TIER_COST[n.t-1],isNew=n.role.startsWith('NEW');
  return `<button class="tn ${s} ${n.id===hgSel?'sel':''}" data-node="${n.id}" style="left:${p[0]/W*100}%;top:${p[1]/H*100}%">
   <small>TIER ${['I','II','III','IV','V','VI','VII'][n.t-1]}${isNew?' &middot; <em>NEW</em>':''}</small><b>${n.name}</b>
   <span>${s==='own'?'IN SERVICE':s==='open'?'&#9670; '+cost.toLocaleString():'LOCKED'}</span></button>`;};
 const bar=(l,v,max,txt)=>`<div class="hs"><label>${l}</label><div><i style="width:${Math.min(100,v/max*100)}%"></i></div><span>${txt}</span></div>`;
 const kn=v=>sel.type==='ship'?Math.round(v*1.944)+' kn':Math.round(v*3.6)+' km/h',sc=({ship:[45,70],tank:[45,60],plane:[340,440]})[sel.type];
 const pk=sel.perk||{},perk=[pk.hp?'+'+Math.round((pk.hp-1)*100)+'% armour':'',pk.speed?'+'+Math.round((pk.speed-1)*100)+'% speed':'',pk.reload?Math.round((1-pk.reload)*100)+'% faster reloads':''].filter(Boolean).join(' &middot; ');
 const parents=sel.parents.map(id=>NODE.get(id).name);
 const d=hgDom;
 let h=`<div class="hg-top"><div><h2 class="t">HANGAR</h2><div class="hmode"><button class="on">SERVICE TREE</button><button id="hg-mode-cust">CUSTOMISE</button></div><div class="sub">Bank salvage, pick one of two at every tier, then customise what you own. Everything you unlock stays yours.</div></div>
  <div class="hg-bank"><small>BANKED SALVAGE</small><b>&#9670; ${S.bank.toLocaleString()}</b><span>${S.cargo?'+'+S.cargo+' carried (bank it at a base)':'carried: none'}</span></div>
  <button class="btn sm" id="hg-x">${hgFrom==='play'?'BACK TO THE FIGHT (B)':hgFrom==='port'?'BACK TO THE BASE':'BACK'}</button></div>
  <div class="hg-tabs">${['land','sea','air'].map(k=>{const o=TREE[k].filter(n=>nodeOwned(n.id)).length;return `<button data-dom="${k}" class="${k===d?'on':''}" style="--dc:${DOM_COL[k]}"><b>${DOM_LABEL[k]}</b><span>${k==='land'?'tanks':k==='sea'?'ships':'aircraft'} &middot; ${o}/${TREE[k].length}</span></button>`;}).join('')}</div>
  <div class="hg-body"><div class="hg-scroll"><div class="hg-tree" style="--dc:${DOM_COL[d]}"><svg viewBox="0 0 ${W} ${H}" preserveAspectRatio="none">${lines}</svg>${nodes.map(card).join('')}
   <div class="hg-tiers">${tiers.map(t=>`<span>${t===1?'START':'TIER '+t+' &middot; &#9670; '+TIER_COST[t-1].toLocaleString()}</span>`).join('')}</div></div></div>
  <div class="hg-side"><div class="hg-sel"><small>${DOM_LABEL[d]} &middot; TIER ${sel.t} &middot; ${ns==='own'?'IN SERVICE':ns==='open'?'AVAILABLE':'LOCKED'}</small><h3>${sel.name}</h3><p>${sel.role.replace(/^NEW · /,'<em>NEW</em> ')}</p>
   ${bar('SPEED',st.cruise,sc[0],kn(st.cruise))}${bar('HEALTH',st.hp/(HP_MUL[sel.type]||1),2.2,Math.round(st.hp*HP_PER).toLocaleString()+' HP')}${bar('FIREPOWER',st.firepower,400,String(Math.round(st.firepower)))}${bar('CARGO',TIER_CARGO[sel.t-1]*salvMul('cargo',d),1500,String(Math.round(TIER_CARGO[sel.t-1]*salvMul('cargo',d))))}
   ${perk?`<p class="perk">VETERAN PERK &middot; ${perk}</p>`:''}
   ${(sel.next||[]).length?`<p class="lead">Leads to: ${sel.next.map(id=>NODE.get(id).name).join(' <i>or</i> ')}</p>`:'<p class="lead">Top of the tree.</p>'}
   <div class="hg-act">${ns==='own'?`<button class="btn pri" id="hg-go">DEPLOY THIS ${sel.type==='plane'?'AIRCRAFT':sel.type.toUpperCase()}</button><button class="btn" id="hg-gar">CUSTOMISE</button>`
     :ns==='open'?`<button class="btn pri" id="hg-buy" ${S.bank<TIER_COST[sel.t-1]&&!OWNER?'disabled':''}>UNLOCK &middot; &#9670; ${TIER_COST[sel.t-1].toLocaleString()}</button>${S.bank<TIER_COST[sel.t-1]?`<p class="need">${(TIER_COST[sel.t-1]-S.bank).toLocaleString()} more salvage needed</p>`:''}`
     :`<p class="need">Unlock ${parents.join(' or ')} first.</p>`}</div></div>
   <div class="hg-ref"><small>${DOM_LABEL[d]} REFITS &middot; EVERY ${d==='land'?'TANK':d==='sea'?'SHIP':'AIRCRAFT'}</small>${REFITS.map(r=>{const l=refitLvl(d,r.id),c=REFIT_COST[l];
    return `<div class="rf"><div><b>${r.name}</b><span>${r.d}</span><em>${[0,1,2,3,4].map(k=>`<i class="${k<l?'on':''}"></i>`).join('')}</em></div><button class="btn sm" data-ref="${r.id}" ${l>=5||(S.bank<c&&!OWNER)?'disabled':''}>${l>=5?'MAX':'&#9670; '+c.toLocaleString()}</button></div>`;}).join('')}</div>
   <div class="hg-doc"><small>${FACTIONS[PF].name.toUpperCase()} DOCTRINES THIS WEEK</small>${DOCTRINE.map((D,i)=>{const a=dc.act[i];return `<p>${dc.pool>=D.need?`<b style="color:#f2b84b">${a?(a===D.a.id?D.a.name:D.b.name):'VOTE NOW'}</b>`:`<span>${D.need.toLocaleString()}</span>`}</p>`;}).join('')}<a href="#" id="hg-doc">Open the War Room &rsaquo;</a></div>
  </div></div>`;
 hg.innerHTML=`<div class="hg-wrap">${h}</div>`;
 $('hg-x').onclick=()=>{closeHangar(true);if(hgFrom==='menu')setState('menu');else if(hgFrom==='port'&&game.port)openPort();};
 for(const b of hg.querySelectorAll('[data-dom]'))b.onclick=()=>{hgDom=b.dataset.dom;hgSel=null;renderHangar();};
 for(const b of hg.querySelectorAll('[data-node]'))b.onclick=()=>{hgSel=b.dataset.node;renderHangar();};
 for(const b of hg.querySelectorAll('[data-ref]'))b.onclick=()=>{const l=refitLvl(d,b.dataset.ref),c=REFIT_COST[l];if(l>=5||(S.bank<c&&!OWNER))return;if(!OWNER)S.bank-=c;S.refit[d][b.dataset.ref]=l+1;salvSave();
  toast(REFITS.find(r=>r.id===b.dataset.ref).name+' refit level '+(l+1)+' for every '+(d==='land'?'tank':d==='sea'?'ship':'aircraft'),2600);if(vehicle&&DOM_OF[vehicle.type]===d)setVehicle(vehicle);renderHangar();};
 const buy=$('hg-buy');if(buy)buy.onclick=()=>{const c=TIER_COST[sel.t-1];if(S.bank<c&&!OWNER)return;if(!OWNER)S.bank-=c;S.own[sel.id]=1;salvSave();
  const on=opts.banners;opts.banners=true;showBanner('NEW IN SERVICE',sel.name.toUpperCase(),DOM_LABEL[d]+' · TIER '+sel.t+(sel.next?' · NEXT: '+sel.next.map(id=>NODE.get(id).name.toUpperCase()).join(' OR '):''),'#f2b84b');opts.banners=on;renderHangar();};
 const go=$('hg-go');if(go)go.onclick=()=>{S.pick[d]=sel.id;salvSave();const spec=nodeSpec(sel);garage.specs[sel.type]=spec;garage.type=sel.type;
  if(hgFrom==='port'&&game.port){garage.from='port';garage.port=game.port;closeHangar();deployFromGarage();return;}   // v3.7 at a dock: swap to it right here
  garage.from='menu';hgReturn=hgFrom;closeHangar();deployFromGarage();};
 const toCust=n=>{S.pick[d]=n.id;salvSave();garage.specs[n.type]=nodeSpec(n);if(hgFrom==='port'&&game.port){closeHangar();openGarage('port');garageType(n.type);return;}const fromPlay=hgFrom==='play';closeHangar();if(fromPlay&&game.state==='paused')setState('menu');openGarage('menu');garageType(n.type);};
 const ga=$('hg-gar');if(ga)ga.onclick=()=>toCust(sel);
 const mc=$('hg-mode-cust');if(mc)mc.onclick=()=>{const n=ns==='own'?sel:NODE.get(S.pick[d]&&NODE.has(S.pick[d])&&nodeOwned(S.pick[d])?S.pick[d]:(TREE[d].find(x=>nodeOwned(x.id))||sel).id);if(!nodeOwned(n.id)){toast('Unlock a '+(d==='land'?'tank':d==='sea'?'ship':'aircraft')+' first',2600);return;}toCust(n);};
 const dl=$('hg-doc');if(dl)dl.onclick=e=>{e.preventDefault();closeHangar(true);if(hgFrom==='menu')setState('menu');if(typeof openWarRoom==='function'){wrTab='doctrine';openWarRoom();}};
}
// ---------- War Room tabs: doctrine and supply routes ----------
function doctrineTab(){
 const dc=doctrines(),S=salvLoad(),left=salvWeekLeft();
 let h=`<p>Every pilot's banked salvage this week fills the <b style="color:${FACTIONS[PF].css}">${FACTIONS[PF].name}</b> pool. At each mark your side adopts one of two doctrines for the rest of the week; every pilot votes. Pools and doctrines reset with the war map on Monday (in ${Math.floor(left/864e5)}d ${Math.floor(left/36e5)%24}h).</p>
  <div class="gstat"><span style="text-align:left;color:var(--dim)">POOL</span><div><i style="width:${Math.min(100,dc.pool/DOCTRINE[3].need*100)}%;background:#f2b84b"></i></div><span>${dc.pool.toLocaleString()}</span></div>
  <p style="color:var(--dim);font-size:12px">You banked <b style="color:var(--ink)">${(S.wk===salvWeek()?S.sw:0).toLocaleString()}</b> this week.</p>`;
 DOCTRINE.forEach((D,i)=>{const reached=dc.pool>=D.need,v=docVotes(PF,i),mine=S.dv[i];
  h+=`<div class="doc ${reached?'on':''}"><small>MARK ${i+1} &middot; ${D.need.toLocaleString()} ${reached?'&middot; REACHED':''}</small><div class="docr">${[['A',D.a],['B',D.b]].map(([k,o])=>`<button data-doc="${i}${k}" class="${mine===k?'mine':''} ${dc.act[i]===o.id?'act':''}"><b>${o.name}</b><span>${o.d}</span><em>${v[k]} vote${v[k]===1?'':'s'}${dc.act[i]===o.id?' &middot; IN FORCE':mine===k?' &middot; YOUR VOTE':''}</em></button>`).join('<i>or</i>')}</div></div>`;});
 return h;
}
function routesTab(){
 const R=supplyRoutes();
 let h=`<p>Every territory produces something. The more of a kind your bloc holds (within ${SEASON_R/1000} km of the centre), the more it pays every pilot on your side. Push where your side needs it.</p><div class="routes">`;
 for(const r of RES){const b=routeBonus(r.id);
  h+=`<div class="rt"><b style="color:${r.col}">${r.name.toUpperCase()}</b><span>${R.held[r.id]} held &middot; +${Math.round(b*100)}% ${r.d}</span>${R.near[r.id].map(q=>`<a href="#" data-route="${q.s.x|0},${q.s.z|0}" title="Set a waypoint">${esc(terrName(q.s))} <em>${fTag(q.f)} &middot; ${fmtD(q.d)}</em></a>`).join('')||'<p style="color:var(--dim)">all held</p>'}</div>`;}
 return h+'</div>';
}
function wireWarRoomSalv(root){
 for(const b of root.querySelectorAll('[data-doc]'))b.onclick=()=>{const i=+b.dataset.doc[0],k=b.dataset.doc[1],S=salvLoad();S.dv=S.dv.slice(0,i)+k+S.dv.slice(i+1);salvSave();docCache.t=-1;if(MMO)MMO.cardT=0;renderWarRoom();};
 for(const a of root.querySelectorAll('[data-route]'))a.onclick=e=>{e.preventDefault();const [x,z]=a.dataset.route.split(',').map(Number);game.wp={id:'route',x,z,name:a.textContent.split(' ')[0]+' '+(a.textContent.split(' ')[1]||'')};toast('Waypoint set: '+game.wp.name,2400);};
}
// ---------- the weekly war (offline): the local map resets on Monday ----------
function salvWeeklyLocal(){
 if(MMO&&MMO.on)return;
 if(war.wk===undefined){war.wk=salvWeek();warSave();return;}
 if(war.wk!==salvWeek()){war.wk=salvWeek();resetWar();war.wk=salvWeek();warSave();toast('A new week of war: the map has reset. Your vehicles, salvage and refits are all still yours.',8000);}
}
// ---------- v3.2 field upgrades: fill the hold, pick one of two, it is flown in (G) ----------
// Your current vehicle's two next vehicles on the Service Tree. Owned ones are free; others cost their tier, paid from the hold first,
// then the bank. Pick one and a transport is inbound for a few seconds (survive it); then you are in the new vehicle where you stand,
// repaired, refuelled and rearmed.
let fieldT=0,fieldPick=null,fieldOpen=false,fieldReadyShown='';
function fieldNext(){
 if(!vehicle||!vehicle.node||!NODE.has(vehicle.node))return [];
 return (NODE.get(vehicle.node).next||[]).map(id=>NODE.get(id));
}
const fieldCost=n=>nodeOwned(n.id)?0:TIER_COST[n.t-1];
function fieldAfford(n){const S=salvLoad();return OWNER||S.cargo+S.bank>=fieldCost(n);}
function fieldReady(){return fieldNext().filter(fieldAfford);}
const fp=document.createElement('div');fp.id='fieldpick';ui.appendChild(fp);
const fr=document.createElement('div');fr.id='fieldready';ui.appendChild(fr);
function openFieldPick(){
 const L=fieldNext();if(!L.length){toast('This is the top of the '+DOM_LABEL[DOM_OF[vehicle.type]].toLowerCase()+' tree.',2600);return;}
 if(fieldT>0)return;
 fieldOpen=true;if(document.exitPointerLock)document.exitPointerLock();
 const S=salvLoad(),cur=NODE.get(vehicle.node);
 fp.innerHTML=`<div class="fp-box"><small>FIELD UPGRADE &middot; FROM ${cur.name.toUpperCase()}</small><h2>PICK ONE</h2>
  <div class="fp-row">${L.map(n=>{const st=vehicleStats(nodeSpec(n)),c=fieldCost(n),ok=fieldAfford(n);
   return `<button class="fp-card ${ok?'':'no'}" data-fp="${n.id}" ${ok?'':'disabled'} style="--dc:${DOM_COL[n.dom]}"><small>TIER ${n.t}${n.role.startsWith('NEW')?' &middot; NEW':''}</small><b>${n.name}</b><span>${n.role.replace(/^NEW · /,'')}</span>
    <em>health ${Math.round(st.hp*HP_PER).toLocaleString()} HP &middot; firepower ${Math.round(st.firepower)} &middot; cargo ${Math.round(TIER_CARGO[n.t-1]*salvMul('cargo',n.dom))}</em>
    <strong>${c?'&#9670; '+c.toLocaleString():'ALREADY YOURS'}</strong>${ok?'':`<p>${(c-S.cargo-S.bank).toLocaleString()} more salvage</p>`}</button>`;}).join('<i>or</i>')}</div>
  <p class="fp-hint">You have &#9670; ${S.cargo} in the hold and &#9670; ${S.bank.toLocaleString()} banked. The new vehicle is flown in where you are.</p>
  <button class="btn sm" id="fp-x">NOT NOW (G)</button></div>`;
 fp.classList.add('on');
 $('fp-x').onclick=closeFieldPick;
 for(const b of fp.querySelectorAll('[data-fp]'))b.onclick=()=>fieldBuy(NODE.get(b.dataset.fp));
}
function closeFieldPick(){fieldOpen=false;fp.classList.remove('on');if(game.state==='playing')lockPointer();}
function fieldBuy(n){
 const S=salvLoad(),c=fieldCost(n);if(!fieldAfford(n))return;
 if(!OWNER&&c){const fromCargo=Math.min(S.cargo,c);S.cargo-=fromCargo;S.bank-=c-fromCargo;}
 S.own[n.id]=1;S.pick[n.dom]=n.id;salvSave();salvHudDirty=true;
 closeFieldPick();fieldPick=n;fieldT=5;
 toast((n.type==='ship'?'Your new ship is on its way':'A transport is inbound with your '+n.name.toLowerCase())+' - hold on for 5 seconds',3000);
}
function fieldTick(dt){
 // the "upgrade ready" card
 const rd=game.state==='playing'&&!fieldT?fieldReady():[];
 const key=rd.map(n=>n.id).join(',');
 if(key!==fieldReadyShown){fieldReadyShown=key;
  fr.innerHTML=rd.length?`<b>UPGRADE READY</b><span>${rd.map(n=>n.name).join(' or ')}</span><kbd>G</kbd>`:'';fr.classList.toggle('on',!!rd.length);
  if(rd.length&&!fr._pinged){fr._pinged=1;if(typeof sfx==='function')try{sfx('ping');}catch(e){}}if(!rd.length)fr._pinged=0;}
 if(!fieldT)return;
 if(game.hull<=0){fieldT=0;fieldPick=null;toast('The delivery was called off - you were wrecked. The new vehicle is waiting in the Service Tree.',4500);return;}
 fieldT-=dt;
 if(fieldT>0){careerFeed={text:'DELIVERY INBOUND  '+Math.ceil(fieldT)+' s',t:1.1};return;}
 fieldT=0;const n=fieldPick;fieldPick=null;if(!n)return;
 const x=player.x,z=player.z,y=player.y,hd=player.hd,v=player.v,air=VS.type==='plane'&&!player.gnd;
 setVehicle(nodeSpec(n));player.x=x;player.z=z;player.hd=hd;
 if(VS.type==='plane'){player.y=y;if(air){player.v=Math.max(v,VS.stall*1.4);player.gnd=false;}}
 else if(VS.type==='tank'){player.y=T.height(x,z);groundPose(player,1);player.v=0;}else player.v=Math.min(v,VS.cruise);
 game.hull=1;game.fuel=1;if(typeof rearmAll==='function')rearmAll();
 for(let k=0;k<5;k++)shellFx.push({kind:'blast',x:x+(Math.random()-.5)*10,y:player.y+3,z:z+(Math.random()-.5)*10,age:-k*.08,life:.7,size:6});
 const on=opts.banners;opts.banners=true;showBanner('NOW IN SERVICE',n.name.toUpperCase(),DOM_LABEL[n.dom]+' · TIER '+n.t+(n.next?' · NEXT: '+n.next.map(id=>NODE.get(id).name.toUpperCase()).join(' OR '):' · TOP OF THE TREE'),'#f2b84b');opts.banners=on;
 fieldReadyShown='?';bootEv('upgrade');
}
// a transport flies over while the delivery is inbound
function emitField(t){
 if(!fieldT||!player||UNIT.TRANSPORT===undefined)return;
 const k=1-fieldT/5,hd=player.hd+.6,d=(k-.55)*900;
 emit(UNIT.TRANSPORT,player.x+Math.cos(hd)*d,Math.max(player.y,T.height(player.x,player.z),0)+140,player.z-Math.sin(hd)*d,hd,0,0,PF+1,1.15);
}
window.addEventListener('keydown',e=>{
 if(e.code!=='KeyG'||e.repeat||e.shiftKey||(e.target&&/INPUT|TEXTAREA/.test(e.target.tagName)))return;
 if(fieldOpen){closeFieldPick();return;}
 if(game.state==='playing'&&!(typeof ride!=='undefined'&&ride))openFieldPick();
});

// ---------- v3.2 boot camp: a dead-simple start ----------
// A new pilot picks LAND, SEA or AIR and is straight in the field next to three salvage sites. Four steps, each one line on screen:
// break a site, fill your hold, upgrade in the field (G), bank at a base. Everything else (tree, war room, doctrines) comes after.
const bootSites=[];
const BOOT_STEPS=[
 // v3.7 controls first
 {id:'move',text:d=>d==='air'?'<span class="bk">W</span> / <span class="bk">S</span> set the throttle (Shift for full power). The plane flies towards the ring - move the mouse to steer':d==='sea'?'<span class="bk">W</span> rings the engines ahead, <span class="bk">S</span> slows and reverses, <span class="bk">A</span> / <span class="bk">D</span> steer. Get under way':'<span class="bk">W</span> / <span class="bk">S</span> drive forward and back, <span class="bk">A</span> / <span class="bk">D</span> steer. Drive 80 m'},
 {id:'look',text:'The mouse is your reticle - no clicking needed. Move it to look and aim all the way round'},
 {id:'fire',text:'Hold the <span class="bk">left mouse button</span> to fire. <span class="bk">Right button</span>, <span class="bk">Q</span> and <span class="bk">E</span> fire your other weapons. Auto-aim only locks on to targets inside the red ring. Open fire'},
 {id:'break',text:'Shoot the marked salvage site until it breaks'},
 {id:'fill',text:'Fill your hold: break more sites or destroy enemies'},
 {id:'upgrade',text:'Press G: pick your next vehicle - it is flown in'},
 {id:'bank',text:'Drive back to the base marker and bank your salvage (move in slowly, press F)'}];
function bootLoad(){try{return JSON.parse(store.get('irontide.boot')||'null');}catch(e){return null;}}
function bootSave(){store.set('irontide.boot',JSON.stringify(boot));}
 // v3.7 after banking: the war itself, one card each (Enter to continue)
BOOT_STEPS.push(
 {id:'map',text:'Press <span class="bk">N</span> for the war map: the fronts, arrows for who is pushing, and pockets that are CUT OFF from supply. <span class="bk">M</span> changes the minimap range - it shows your teammates only'},
 {id:'r_front',read:1,text:'The front is two trench lines. The ground between them is an <span class="bk">artillery zone</span>: shells walk in on anything that stays there. Armour takes only a third of the splash, so <span class="bk">tanks are the breakthrough</span> - crossing an enemy trench in a tank pushes the whole line'},
 {id:'r_ships',read:1,text:'Ships hit hard but slowly: a big gun takes several seconds to reload. Bombers get a <span class="bk">HIT</span>, <span class="bk">NEAR MISS</span> or <span class="bk">MISSED</span> report on every bomb'},
 {id:'r_death',read:1,text:'Dying costs you: you drop <span class="bk">two tiers</span> and buy them back in the Service Tree (<span class="bk">B</span>). Die 5 times in a short window (15 min at T6, up to an hour at T3 and below) and the whole branch resets'},
 {id:'r_more',read:1,text:'At any base, <span class="bk">CHANGE VEHICLE</span> swaps you to any ship, tank or aircraft you own. In a plane, <span class="bk">1</span>-<span class="bk">4</span> set the speed, and the plane adds power by itself if you get too slow. Every tier 6 vehicle has a special ability on <span class="bk">T</span>'},
 {id:'r_team',read:1,text:'The bar at the top is your side\'s <span class="bk">team project</span>: convoy kills, captures and outposts fill it, and when it is full the whole side gets the upgrade. Banked salvage fills the doctrine marks below it'},
 {id:'r_end',read:1,text:'<span class="bk">B</span> Service Tree &middot; <span class="bk">L</span> War Room &middot; <span class="bk">G</span> field upgrade &middot; <span class="bk">F</span> dock &middot; <span class="bk">R</span> reload &middot; <span class="bk">Esc</span> pause. That is everything - hold the line'});
const bootTmp={};
const bootScreen=document.createElement('div');bootScreen.id='bootpick';bootScreen.className='screen';ui.appendChild(bootScreen);
function openBootPick(){
 const S=salvLoad();
 bootScreen.innerHTML=`<div class="bp-box"><small>WELCOME, ${esc(profile&&profile.callsign||'COMMANDER').toUpperCase()}</small><h1>WHERE DO YOU FIGHT?</h1>
  <p>Pick one to start. You can unlock the other two any time.</p>
  <div class="bp-row">${[['land','L1','Light tank','Fast, small, hard to hit. Shoot supply dumps and enemy armour.'],['sea','S1','Small destroyer','Quick and nimble. Break open wrecks and sink enemy patrols.'],['air','A1','Light plane','Fly low over the islands. Pop cargo balloons and shoot down planes.']].map(([d,id,n,t])=>
   `<button class="bp-card" data-bp="${id}" style="--dc:${DOM_COL[d]}"><small>${DOM_LABEL[d]}</small><b>${n}</b><span>${t}</span><em>START HERE &rsaquo;</em></button>`).join('')}</div>
  <button class="btn sm" id="bp-skip" style="width:auto">SKIP - I KNOW WHAT I'M DOING</button></div>`;
 showScreen(null);bootScreen.classList.add('on');bootScreen.style.display='block';
 for(const b of bootScreen.querySelectorAll('[data-bp]'))b.onclick=()=>bootStart(NODE.get(b.dataset.bp));
 $('bp-skip').onclick=()=>{bootScreen.classList.remove('on');bootScreen.style.display='none';boot={step:9,done:1};bootSave();setState('menu');};
}
function bootStart(n){
 bootScreen.classList.remove('on');bootScreen.style.display='none';
 if(profile){profile.tutorialDone=true;profileSave();}
 const S=salvLoad();S.pick[n.dom]=n.id;salvSave();
 boot={step:0,dom:n.dom,t0:Date.now(),v:37};bootSave();
 garage.specs[n.type]=nodeSpec(n);garage.type=n.type;setVehicle(garage.specs[n.type]);
 pendingDeploy=null;newVoyage();
 setTimeout(bootPlaceSites,600);
}
// three practice sites of your kind, 350-800 m from where you start
function bootPlaceSites(){
 if(!player||!boot)return;bootSites.length=0;const kind=boot.dom;
 for(let k=0,tries=0;bootSites.length<3&&tries<400;tries++){
  const a=tries*2.399+.4,r=350+(tries%9)*55,x=player.x+Math.cos(a)*r,z=player.z+Math.sin(a)*r,gh=T.height(x,z);
  if(kind==='sea'&&gh>-8)continue;if(kind==='land'&&(gh<3||gh>120||(T.pave&&T.pave(x,z)>.05)||Math.abs(T.height(x+12,z)-gh)>4))continue;
  const y=kind==='air'?Math.max(gh,0)+180:kind==='sea'?0:gh;
  bootSites.push({key:'boot'+k++,i:k*7,j:k*3,kind:kind,x,y,z,hd:a,hp0:kind==='sea'?160:kind==='land'?120:50,hp:kind==='sea'?160:kind==='land'?120:50,r:kind==='sea'?30:kind==='land'?14:10,h:kind==='sea'?12:kind==='land'?9:24,boot:1});
 }
 bootAim();
}
function bootAim(){
 if(!boot||!player)return;const st=BOOT_STEPS[boot.step];if(!st)return;
 if(st.id==='break'||st.id==='fill'){const s=bootSites.concat(sitesNear.filter(q=>q.kind===boot.dom)).filter(q=>q.hp>0).sort((a,b)=>Math.hypot(a.x-player.x,a.z-player.z)-Math.hypot(b.x-player.x,b.z-player.z))[0];
  if(s)game.wp={id:'boot',x:s.x,z:s.z,name:'Salvage site'};}
 else if(st.id==='bank'){const p=friendlyPortNear(player.x,player.z,30000);if(p)game.wp={id:'boot',x:p.x,z:p.z,name:portName(p.id)};}
 else game.wp=null;
}
function bootEv(what){
 if(!boot||boot.done)return;const st=BOOT_STEPS[boot.step];if(!st)return;
 if(st.id===what){boot.step++;bootSave();
  if(boot.step>=BOOT_STEPS.length){boot.done=1;bootSave();game.wp=null;
   const on=opts.banners;opts.banners=true;showBanner('YOU ARE IN THE WAR','BOOT CAMP DONE','B SERVICE TREE · L WAR ROOM · G FIELD UPGRADE','#f2b84b');opts.banners=on;
   news('<b style="color:#f2b84b">Boot camp done.</b> Your salvage now also fills your side\'s weekly pool. Press <b>B</b> for the Service Tree, <b>L</b> for the War Room.',20000);}
  else{bootAim();const nx=BOOT_STEPS[boot.step];if(!nx.read)toast('NEXT: '+(typeof nx.text==='function'?nx.text(boot.dom):nx.text).replace(/<[^>]+>/g,''),4000);}
 }
}
boot=bootLoad();
if(boot&&!boot.done&&boot.v!==37){const old=['break','fill','upgrade','bank'][boot.step];boot.step=Math.max(0,BOOT_STEPS.findIndex(s=>s.id===old));boot.v=37;bootSave();}   // v3.7 carry an unfinished boot camp over to the new step list
addEventListener('keydown',e=>{if(e.code==='Enter'&&boot&&!boot.done&&game.state==='playing'&&!(e.target&&/INPUT|TEXTAREA/.test(e.target.tagName))){const st=BOOT_STEPS[boot.step];if(st&&st.read)bootEv(st.id);}});
{const st=document.createElement('style');st.textContent='#bootcard .bk{display:inline;font-weight:800;color:#f2b84b}#t6ab{position:fixed;left:50%;bottom:92px;transform:translateX(-50%);display:none;z-index:6;padding:7px 14px;font:700 12px/1.3 system-ui,sans-serif;letter-spacing:.16em;color:#9aa3a0;background:rgba(10,14,18,.72);border:1px solid rgba(255,255,255,.15);border-radius:4px;pointer-events:none;text-align:center}#t6ab small{display:block;font-size:10px;opacity:.8}#t6ab.rdy{color:#f2b84b;border-color:#f2b84b}#t6ab.act{color:#7be08f;border-color:#7be08f}';document.head.appendChild(st);const d=document.createElement('div');d.id='t6ab';document.body.appendChild(d);}
const bootEl=document.createElement('div');bootEl.id='bootcard';ui.appendChild(bootEl);let bootKey='';
function bootTick(){
 ui.classList.toggle('bootmode',!!(boot&&!boot.done));
 if(!boot||boot.done||game.state!=='playing'){if(bootKey){bootKey='';bootEl.classList.remove('on');}return;}
 const S=salvLoad(),st=BOOT_STEPS[boot.step];
 if(st&&bootTmp.step!==boot.step){bootTmp.step=boot.step;bootTmp.x=player.x;bootTmp.z=player.z;bootTmp.yaw=orbit.yaw;bootTmp.acc=0;bootTmp.shots=shotsFired;}
 if(st&&st.id==='move'&&Math.hypot(player.x-bootTmp.x,player.z-bootTmp.z)>80)bootEv('move');
 if(st&&st.id==='look'){bootTmp.acc+=Math.abs(wrapPi(orbit.yaw-bootTmp.yaw))+(typeof planeAim!=='undefined'&&VS&&VS.type==='plane'?Math.abs(wrapPi(planeAim.yaw-(bootTmp.py??planeAim.yaw))):0);bootTmp.yaw=orbit.yaw;if(typeof planeAim!=='undefined')bootTmp.py=planeAim.yaw;if(bootTmp.acc>2.4)bootEv("look");}
 if(st&&st.id==='fire'){const nw=performance.now(),fdt=Math.min(.25,(nw-(bootTmp.ft||nw))/1000);bootTmp.ft=nw;if(pa.mouse||wep.rmb||keys.Space||keys.KeyQ||keys.KeyE)bootTmp.acc+=fdt;if(shotsFired-bootTmp.shots>=3||bootTmp.acc>1.2)bootEv('fire');}   // holding fire for a moment counts (some guns wait until they are laid)
 if(st&&st.id==='map'&&warOpen)bootEv('map');
 if(st.id==='break'&&S.cargo>0)bootEv('break');
 if(st.id==='fill'&&fieldReady().length)bootEv('fill');
 if(st.id==='bank'&&S.cargo===0&&boot.banked)bootEv('bank');
 if(BOOT_STEPS[boot.step]&&(BOOT_STEPS[boot.step].id==='break'||BOOT_STEPS[boot.step].id==='fill')&&(!game.wp||game.wp.id!=='boot'))bootAim();
 const cur=BOOT_STEPS[boot.step];if(!cur)return;
 const cap=salvCargoCap(),k=boot.step+'|'+(cur.id==='fill'?S.cargo:'');
 if(k!==bootKey){bootKey=k;bootEl.classList.add('on');
  bootEl.innerHTML=`<small>BOOT CAMP &middot; ${boot.step+1} / ${BOOT_STEPS.length}</small><b>${typeof cur.text==='function'?cur.text(boot.dom):cur.text}</b>${cur.read?'<small style="display:block;margin-top:6px;opacity:.75">ENTER TO CONTINUE</small>':''}${cur.id==='fill'?`<div class="bc-bar"><i style="width:${Math.min(100,S.cargo/Math.max(1,(fieldNext()[0]?Math.min(...fieldNext().map(fieldCost).filter(c=>c>0),cap):cap))*100)}%"></i></div>`:''}`;}
}

// v3.1: the garage always fits out a Service Tree vehicle - the one in use, or the one last picked from the tree
function salvGarageFix(from){
 const S=salvLoad();
 for(const t of ['ship','tank','plane']){const sp=garage.specs[t];if(!sp)continue;const d=DOM_OF[t],hk=LAD_HKEY[t];
  if(sp.node&&NODE.has(sp.node)&&NODE.get(sp.node).p[hk]===sp.p[hk]&&nodeOwned(sp.node))continue;
  const n=(S.pick[d]&&NODE.has(S.pick[d])&&nodeOwned(S.pick[d]))?NODE.get(S.pick[d]):(TREE[d].find(q=>nodeOwned(q.id)&&q.p[hk]===sp.p[hk])||TREE[d][0]);
  const ns=nodeSpec(n);if(n.p[hk]===sp.p[hk]&&sp.mods){ns.mods=sp.mods;for(const k in sp.p)if(k!==hk)ns.p[k]=sp.p[k];}garage.specs[t]=ns;}
}
function renderMenuCard(){
 const el=$('m-card');if(!el)return;const S=salvLoad(),dc=doctrines(),left=salvWeekLeft(),own=k=>TREE[k].filter(n=>nodeOwned(n.id)).length;
 const F=FACTIONS[PF],act=dc.act.filter(Boolean).length;
 el.innerHTML=`<small>THIS WEEK'S WAR</small><div class="big">${Math.floor(left/864e5)}d ${Math.floor(left/36e5)%24}h</div><div style="font-size:11px;color:var(--dim);letter-spacing:.1em;margin:-2px 0 10px">until the map resets &middot; your progress never does</div>
  <div class="row2"><span>Your side</span><b style="color:${F.css}">${F.name}</b></div>
  <div class="row2"><span>Banked salvage</span><b style="color:var(--acc)">&#9670; ${S.bank.toLocaleString()}</b></div>
  <div class="row2"><span>Service Tree</span><b>${['land','sea','air'].map(k=>`<span style="color:${DOM_COL[k]}">${DOM_LABEL[k]} ${own(k)}/${TREE[k].length}</span>`).join(' &nbsp;')}</b></div>
  <div class="row2"><span>${F.tag} salvage pool</span><b>${dc.pool.toLocaleString()}</b></div>
  <div class="row2"><span>Doctrines in force</span><b>${act} of ${DOCTRINE.length}</b></div>
  <p style="font-size:11px;color:var(--dim);line-height:1.5;margin:10px 0 0">Break wrecks, supply dumps and cargo balloons and destroy the enemy - the salvage goes straight into your hold. Bank it at any friendly base or outpost. Press <span class="kbd">B</span> in the field for the Service Tree.</p>`;
}
window.__setV=sp=>{setVehicle(sp);if(typeof rearmAll==='function')rearmAll();game.hull=1;game.fuel=1;};
window.__salv={stats:id=>{const st=vehicleStats(nodeSpec(NODE.get(id)));return {fp:st.firepower,hp:st.hp,cruise:st.cruise,flank:st.flank};},get fx(){return shellFx;},get vehicle(){return vehicle;},openBootPick,openFieldPick,fieldBuy,fieldNext,get boot(){return boot;},bootSites,get fieldT(){return fieldT;},get S(){return salvLoad();},get crates(){return crates;},get shells(){return shells;},salvShell,get sites(){return sitesNear;},TREE,NODE,doctrines,supplyRoutes,salvBank,dropCrate,openHangar,closeHangar,renderHangar,nodeSpec,salvCargoCap,salvMul,scanSites,
 give(n){salvLoad().bank+=n;salvSave();},cargo(n){salvLoad().cargo=n;salvSave();salvHudDirty=true;}};

function drawRain(vp,common){
 if(!progRain||wx.rain<.02||window.__noWater===2)return;
 gl.enable(gl.BLEND);gl.blendFunc(gl.SRC_ALPHA,gl.ONE_MINUS_SRC_ALPHA);gl.depthMask(false);
 gl.useProgram(progRain.p);common(progRain);setU(progRain,'uVP',vp);setU(progRain,'uFall',[wind*7,-11,wind*3.5]);
 gl.bindVertexArray(emptyVAO);const rk=Math.min(1,wx.rain);
 setU(progRain,'uLayer',[70,18,34,1]);gl.drawArrays(gl.LINES,0,Math.floor(rk*12000)*2);           // close drops: crisp streaks
 setU(progRain,'uLayer',[240,30,120,2.6]);gl.drawArrays(gl.LINES,0,Math.floor(rk*rk*16000)*2);   // v3.7 a far curtain, so heavy rain greys out the distance too
 gl.depthMask(true);gl.disable(gl.BLEND);
}
