 for(const p of PERF.pend){if(gl.getQueryParameter(p.q,gl.QUERY_RESULT_AVAILABLE)){if(!dis){const ms=gl.getQueryParameter(p.q,gl.QUERY_RESULT)/1e6;const g=PERF.gpu[p.name]||(PERF.gpu[p.name]=0);PERF.gpu[p.name]=g*.9+ms*.1;}gl.deleteQuery(p.q);}else keep.push(p);}
